INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1017135104', 'SP004502', '1017135104', 'https://www.maytinhbienhoa.vn/products/laptop-asus-vivobook-s13-s330ua-ey053t-gold-i3-8130u-4gb-lpddr3-256gb-ssd-vga-onboard-13-3-fhd-ips-win10', 'LAPTOP ASUS S330U (S330UA-EY053T) I3-8130U/256B SSD/4GB/13.3" FHD/WIN10 NEW BH 24TH', 'laptop-asus-vivobook-s13-s330ua-ey053t-gold-i3-8130u-4gb-lpddr3-256gb-ssd-vga-onboard-13-3-fhd-ips-win10', 'brand_asus_316', 'cat_laptop', 14490000, 14490000, 0, 11592000, 24, 'out_of_stock', 'LAPTOP ASUS S330U (S330UA-EY053T) I3-8130U/256B SSD/4GB/13.3" FHD/WIN10 NEW BH 24TH', 'GIÁ BÁN CHÍNH HÃNG&nbsp; 14,490,000 VNĐ &nbsp; ------------------------------------- ▶️ KHUYẾN MÃI&nbsp;◀️ Quý khách hàng được lựa chọn 1 trong 3 gói khuyến mãi sau đây: ★ KM 1: Mua trả thẳng Tặng voucher MTBH trị giá &nbsp; 900,000 VNĐ &nbsp; (có thể giảm giá trực tiếp) → Giá chỉ còn&nbsp; 13,590,000&nbsp;VNĐ ★ KM 2: Mua trả góp Hỗ trợ &nbsp; Trả góp&nbsp;0% &nbsp; lãi suất &nbsp; (Không hỗ trợ giảm giá hay tặng quà khác) → Trả trước 50%, t rả góp phần còn lại trong &nbsp; 7 &nbsp; tháng ★ KM thêm từ MTBH: Mặc định sẽ có → Balo Asus Gray&nbsp; → Bộ dụng cụ vệ sinh Laptop 4 món → Combo 4 nút cao su đế tản nhiệt →&nbsp;Túi chống sốc Laptop → Chuột không dây Rimax V168 ------------------------------------- ▶️&nbsp; ƯU ĐÃI &amp; DỊCH VỤ &nbsp;◀️ ✔️ Tặng Voucher giảm&nbsp;10% khi mua Gaming Gears&nbsp; ✔️ Mua phần mềm diệt virus với giá chỉ &nbsp; 129,000 VNĐ ✔️ Trả Góp&nbsp;0% bằng thẻ tín dụng qua M-Pos &nbsp; (chi tiết) ✔️ Bảo hành 1 đổi 1 trong 30 ngày đầu nếu phát sinh lỗi kỹ thuật do NSX. ✔️ Bảo hành chính hãng 2 năm tại các TTBH Asus trên toàn quốc. ✔️ Miễn phí vệ sinh laptop trong suốt thời gian bảo hành ✔️ Miễn phí cài đặt và nâng cấp phần mềm trọn đời ✔️ Miễn phí giao hàng toàn quốc ! ✔️ Miễn phí quẹt thẻ ATM, Visa, Master. ✔️ Miễn phí tiền công dịch vụ nâng cấp linh kiện (SSD, RAM, ...) ------------------------------------- ▶️ &nbsp; CẤU HÌNH&nbsp;◀️ Model Asus Vivobook S13 S330UA-EY053T (Gold) CPU Intel® Core™ i3-8130U (2.20Ghz upto 3.40GHz, 2Cores, 4Threads, 4MB Cach', '{"Model":"Asus Vivobook S13 S330UA-EY053T (Gold)","CPU":"Intel® Core™ i3-8130U (2.20Ghz upto 3.40GHz, 2Cores, 4Threads, 4MB Cache, FSB 4GT/s)","RAM":"4GB LPDDR3-2133MHz","Ổ cứng":"256GB SSD M.2 Sata","CD/DVD":"None","Card VGA":"Intel® UHD Graphics 620","Màn hình":"13.3-inch FHD (1920 x 1080) IPS 60Hz, Anti-Glare with 45% NTSC","Kết nối":"Integrated 802.11 AC (2x2) + Bluetooth V4.2","Tích hợp":"1x Type-C™ USB 3.1 Gen 1 1x Type-A USB 3.1 Gen 1 1x USB 2.0 1x HDMI 1x Combo audio jack 1x MicroSD card reader","Trọng lượng":"1.2 Kg","Pin":"3 Cells 42 Whrs Battery","Hệ điều hành":"Windows 10 bản quyền"}', 0, 1);
