INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1069416498', 'SP1082481', '1069416498', 'https://www.maytinhbienhoa.vn/products/cpu-amd-ryzen-3-3200g-mpk-chinh-hang', 'CPU AMD Ryzen 3 3200G MPK Chính Hãng', 'cpu-amd-ryzen-3-3200g-mpk-chinh-hang', 'brand_amd_210', 'cat_cpu', 1650000, 1650000, 0, 1320000, 24, 'in_stock', 'CPU AMD Ryzen 3 3200G MPK Chính Hãng', 'THÔNG SỐ KỸ THUẬT Thương hiệu AMD Bảo hành 36 tháng CPU Ryzen 3 3200G Socket AM4 Kiến trúc Zen+ (12 nm) Thế hệ AMD Ryzen thế hệ thứ 3 Dòng Ryzen 3 Tốc độ xử lý 3.6 GHz up to 4GHz Số nhân xử lý 4 Số luồng xử lý 4 Cache 4MB Chip đồ họa AMD Vega 8 Graphics TDP 65W Bộ nhớ hỗ trợ DDR4 Dual channel &nbsp; Giới thiệu bộ xử lý&nbsp;CPU&nbsp;AMD&nbsp;Ryzen&nbsp;3 3200G Cách đây vài năm, trước khi AMD giới thiệu kiến trúc Zen thì việc chơi game đối với bộ xử lý đồ họa tích hợp trên&nbsp;CPU&nbsp;gần như là điều không thể với rất nhiều hạn chế về khả năng xử lý. Với sự ra mắt của&nbsp;Ryzen&nbsp;3 2200G và&nbsp;Ryzen&nbsp;5 2400G, 2 đại diện Raven Ridge tiêu biểu dựa trên kiến trúc Zen+ của AMD, đem lại sự linh hoạt rất cao cho người dùng cả về hiệu năng lẫn khả năng nâng cấp. Mới đây tại sự kiện Computex 2019, AMD vừa tung ra&nbsp;Ryzen&nbsp;3 3200G là phiên bản nâng cấp của&nbsp;Ryzen&nbsp;3 2200G với hiệu năng đồ họa được cải thiện một cách rõ rệt. Hiệu năng Điểm thay đổi lớn nhất của&nbsp;Ryzen&nbsp;3 3200G so với 2200G đó chính là về tốc độ xử lý đã được cải thiện lên khá đáng kể, cả về&nbsp;CPU&nbsp;lẫn bộ xử lý đồ họa tích hợp Vega 8. Với hiệu năng chơi game trên độ phân giải 1080p, nhờ vào việc được cải thiện tốc độ xử lý,&nbsp;Ryzen&nbsp;3 3200G chắc chắn sẽ đem lại trải nghiệm mượt mà đối với các tựa game e-Sport phổ biến hiện nay. &nbsp; Sẽ thật khó có thể thuyết phục một game thủ hay một content creator lựa chọn&nbsp;Ryzen&nbsp;3 3200G, vì dù gì đi n', '{"Thương hiệu":"AMD","Bảo hành":"36 tháng","CPU":"Ryzen 3 3200G","Socket":"AM4","Kiến trúc":"Zen+ (12 nm)","Thế hệ":"AMD Ryzen thế hệ thứ 3","Dòng":"Ryzen 3","Tốc độ xử lý":"3.6 GHz up to 4GHz","Số nhân xử lý":"4","Số luồng xử lý":"4","Cache":"4MB","Chip đồ họa":"AMD Vega 8 Graphics"}', 0, 1);
