INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1072152624', 'SP1083076', '1072152624', 'https://www.maytinhbienhoa.vn/products/cpu-amd-ryzen-5-3400g-socket-am4-mpk-chinh-hang', 'CPU AMD Ryzen 5 3400G Socket AM4 MPK Chính Hãng', 'cpu-amd-ryzen-5-3400g-socket-am4-mpk-chinh-hang', 'brand_amd_210', 'cat_cpu', 1850000, 1989000, 7, 1480000, 24, 'in_stock', 'CPU AMD Ryzen 5 3400G Socket AM4 MPK Chính Hãng', 'THÔNG SỐ KỸ THUẬT &nbsp; Dòng CPU Ryzen 5 Thế hệ CPU AMD Ryzen 5000 series Model CPU Ryzen 5 3400G Socket Socket AM4 Tốc độ 3.7 GHz Tốc độ Turbo tối đa Up to 4.2GHz Nhân CPU 4 Cores Luồng CPU 8 Threads Bộ nhớ hỗ trợ Up to 3200MHz Bộ nhớ Cache 6MB VXL đồ họa Radeon™ Graphics Dây chuyền công nghệ 12nm TDP 65W Kiểu đóng gói Box &nbsp; CPU AMD Ryzen 5 3400G Hiệu năng xử lí đa nguồn CPU&nbsp;AMD Ryzen 5 3400G &nbsp;gồm 4 lõi, 8 luồng tiết kiệm điện nhất, cùng với những công nghệ thông minh nhất. Mỗi vi xử lý thuộc dòng AMD Ryzen đều được giải phóng để đạt sức mạnh tối đa từ trong nhà máy, và bạn có thể hoàn toàn cá nhân hóa hiệu suất&nbsp; CPU AMD Ryzen 5 3400G &nbsp;theo ý của bạn. AMD cung cấp tiện ích AMD Ryzen Master để dễ dàng tùy chỉnh lợi thế này. Cá nhân hóa hiệu năng CPU của bạn AMD Ryzen Master cung cấp cho bạn 4 bảng tùy chỉnh để lưu trữ những thiết lập về xung nhịp và điện áp của cả&nbsp; AMD Ryzen 5 3400G &nbsp;và DDR4. Bạn cũng có thể chọn lõi và căn thời gian bộ nhớ. Giám sát hệ thống AMD Ryzen Master thể hiện hết cho bạn những thông số chính xác của phần cứng, cho phép bạn quản lý hệ thống thời gian thực và theo dõi xung nhịp, nhiệt độ của từng lõi. Công nghệ AMD SENSEMI AMD xin giới thiệu công nghệ AMD SenseMI, bao gồm các tính năng tự học và tự thích nghi giúp vi xử lý&nbsp; AMD Ryzen 5 3400G &nbsp;điều chỉnh hiệu năng phù hợp với bạn và với ứng dụng. Kết quả cho ra đời một công nghệ tự tư duy.', '{"Dòng CPU":"Ryzen 5","Thế hệ CPU":"AMD Ryzen 5000 series","Model CPU":"Ryzen 5 3400G","Socket":"Socket AM4","Tốc độ":"3.7 GHz","Tốc độ Turbo tối đa":"Up to 4.2GHz","Nhân CPU":"4 Cores","Luồng CPU":"8 Threads","Bộ nhớ hỗ trợ":"Up to 3200MHz","Bộ nhớ Cache":"6MB","VXL đồ họa":"Radeon™ Graphics","Dây chuyền công nghệ":"12nm"}', 0, 1);
