INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1020604752', 'SP005791', '1020604752', 'https://www.maytinhbienhoa.vn/products/cpu-amd-ryzen-5-3400g-with-wraith-spire-cooler-3-7-ghz-4-2-ghz-with-boost-6mb-4-cores-8-threads-radeon-vega-11-65w-socket-am4', 'CPU AMD Ryzen 5 3400G, with Wraith Spire cooler/ 3.7 GHz (4.2 GHz with boost) / 6MB / 4 cores 8 threads / Radeon Vega 11 / 65W / Socket AM4', 'cpu-amd-ryzen-5-3400g-with-wraith-spire-cooler-3-7-ghz-4-2-ghz-with-boost-6mb-4-cores-8-threads-radeon-vega-11-65w-socket-am4', 'brand_amd_210', 'cat_cpu', 2050000, 1989000, 0, 1640000, 24, 'in_stock', 'CPU AMD Ryzen 5 3400G, with Wraith Spire cooler/ 3.7 GHz (4.2 GHz with boost) / 6MB / 4 cores 8 threads / Radeon Vega 11 / 65W / Socket AM4', 'THÔNG SỐ KỸ THUẬT Bộ vi xử lý&nbsp;CPU AMD Ryzen 5 3400G đến từ thương hiệu&nbsp; CPU AMD Sản phẩm Bộ vi xử lý CPU Hãng sản xuất AMD Model Ryzen 5 3400G Socket AM4a Tốc độ 3.6GHz Tốc độ Tubor tối đa 4.2GHz Cache 6MB Nhân CPU 4 Cores Luồng CPU 8 Threads Bus ram hỗ trợ 3200MHz Dây chuyền công nghệ TSMC 7nm FinFET Điện áp tiêu thụ tối đa 65W Đồ họa tích hợp Radeon Vega 11 CPU AMD Ryzen 5 3400G &nbsp;được thiết kế dựa trên kiến trúc Zen+ và tiến trình 12nm giúp cải thiện xung nhịp và nhiệt độ so với thế hệ cũ.&nbsp; AMD Ryzen 5 3400G &nbsp;được ép xung sẵn ở mức 4.2GHz, cao hơn 8% so với 2400G có mức xung 3.9GHz.&nbsp; &nbsp; Card đồ họa tích hợp VEGA 11 cũng có mức xung cao hơn 12% so với 2400G. Số nhân, số luồng xử lý của &nbsp;AMD Ryzen 5 3400G &nbsp;vẫn được trang bị 4 nhân 8 luồng như thế hệ trước và công suất thiết kế nhiệt độ (TDP) của CPU này là 65W. &nbsp; Bên cạnh đó AMD cũng cập nhật phần mềm AMD Ryzen Master của họ lên phiên bản mới nhất hiện tại là 2.0.1 với nhiều thay đổi mới. Phần báo nhiệt độ của CPU sẽ được báo cáo chính xác hơn cho người dùng nhờ sự tính toán, đo đạc của toàn bộ cảm biến nhiệt trên CPU thay vì chỉ đo đạc ở một cảm biến có nhiệt độ cao nhất dẫn đến báo cáo không thực tế. Về điện áp của CPU thì phần mềm cũng cho biết mức điện áp trung bình được sử dụng thay vì chỉ báo điện áp cao nhất. Đây là 2 thay đổi lớn giúp người dùng có thể kiểm soát được hành vi của CPU tốt hơn trong AMD Ryzen Master phiên bản mới này. &nbsp; &nbsp; Vẫn là hình', '{"Sản phẩm":"Bộ vi xử lý CPU","Hãng sản xuất":"AMD","Model":"Ryzen 5 3400G","Socket":"AM4a","Tốc độ":"3.6GHz","Tốc độ Tubor tối đa":"4.2GHz","Cache":"6MB","Nhân CPU":"4 Cores","Luồng CPU":"8 Threads","Bus ram hỗ trợ":"3200MHz","Dây chuyền công nghệ":"TSMC 7nm FinFET","Điện áp tiêu thụ tối đa":"65W"}', 0, 1);
