INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1040796003', 'SP106443', '1040796003', 'https://www.maytinhbienhoa.vn/products/cpu-intel-core-i3-12100f-3-3ghz-turbo-4-3ghz-4-nhan-8-luong-lga-1700-tray-1', 'Cpu Intel Core i3 12100F 12TH TRAY BH 36 THÁNG', 'cpu-intel-core-i3-12100f-3-3ghz-turbo-4-3ghz-4-nhan-8-luong-lga-1700-tray-1', 'brand_intel_380', 'cat_cpu', 2450000, 2749000, 11, 1960000, 24, 'in_stock', 'Cpu Intel Core i3 12100F 12TH TRAY BH 36 THÁNG', 'MÔ TẢ SẢN PHẨM CPU Intel Core i3-12100F &nbsp; Intel đã công bố sản phẩm CPU Intel Core i3-12100F thế hệ thứ 12 mới nhất trong sự kiện Intel InnovatiON diễn ra vào ngày 27/10/2021. Với tên gọi Alder Lake trải đều từ Core i3, i5, i7, i9 như đối với các phiên bản tiền nhiệm. Với 6 mẫu CPU này dành cho máy tính để bàn, tất cả sản phẩm đều được mở khóa hệ số nhân để phục vụ ép xung tốt nhất. Intel Core thế hệ thứ 12 này là thiết bị đanh thép nhất của Intel dành cho các đối thủ của mình sau nhiều năm chỉ dừng lại ở tiến trình 14nm.&nbsp; &nbsp; Cải tiến hơn về tốc độ Chip Intel Core i3-12100F thế hệ 12 này được cải tiến nhiều về tốc độ, hiệu suất cùng với sự kết hợp giữa nhân tiết kiệm điện Efficient-cores (E-cores). Cùng với đó là nhân hiệu năng cao&nbsp; Performance cores (P-cores).. &nbsp; Trang bị quạt tản nhiệt Laminar RM1 mới nhất CPU Intel Core i3-12100F được trang bị bộ tản nhiệt có thiết kế hình xoắn ốc kết nối với tấm đế đồng. Bên cạnh đó còn có 5 cánh quạt bằng nhôm với logo Intel có nhiệm vụ làm mát chip. Từ đó giúp tăng hiệu quả tản nhiệt tốt hơn cho CPU. Với cơ chế lắp ráp, bộ tản nhiệt này bao gồm 4 chân đẩy và kéo, dễ dàng lắp ráp trên bất kỳ bo mạch chủ nào của LGA 1700.&nbsp; &nbsp; Hệ sinh thái ở tầm đẳng cấp &nbsp; Intel đã làm việt chặt chẽ với những nhà sản xuất phần cứng cũng như phần mềm. Điều này giúp đảm bảo mọi thứ có thể vận hành một cách hoàn hảo trên những hệ thống của hãng. Những ai ưa chuộng sự lành tính chắc chắn sẽ không thể bỏ qua những gì mà Int', '{"Model":"Cpu Intel Core i3 12100F 12TH TRAY BH 36 THÁNG"}', 0, 1);
