INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1055414078', 'SP1080341', '1055414078', 'https://www.maytinhbienhoa.vn/products/cpu-intel-core-i5-14400f-up-to-4-7ghz-10-nhan-16-luong-20mb-cache-65w-tray-gen-15', 'CPU INTEL CORE I5 14400F (UP TO 4.7GHZ, 10 NHÂN 16 LUỒNG, 20MB CACHE, 65W) TRAY GEN 14', 'cpu-intel-core-i5-14400f-up-to-4-7ghz-10-nhan-16-luong-20mb-cache-65w-tray-gen-15', 'brand_intel_380', 'cat_cpu', 3250000, 3589000, 9, 2600000, 24, 'in_stock', 'CPU INTEL CORE I5 14400F (UP TO 4.7GHZ, 10 NHÂN 16 LUỒNG, 20MB CACHE, 65W) TRAY GEN 14', 'Thông số kỹ thuật: Socket FCLGA1700 Dòng CPU Core i5 CPU Intel® Core® i5-14400F (Raptor Lake) Số nhân 10 (6 Performance-cores/ 4 Efficient-cores) Số luồng 16 Tốc độ Turbo tối đa của P-core 4.7 GHz Tốc độ&nbsp;Turbo tối đa của E-core&nbsp; 3.5 GHz Tốc độ cơ bản của P-core 2.5 GHz Tốc độ cơ bản của E-core 1.8 GHz Điện năng tiêu thụ 65W - 148W Bộ nhớ đệm 20MB Intel® Smart Cache Bo mạch chủ tương thích 600 và 700 series Bộ nhớ hỗ trợ tối đa 192GB Loại bộ nhớ DDR5, DDR4 Nhân đồ họa tích hợp Không Phiên bản&nbsp;PCI Express 5.0 and 4.0 Số lượng PCIe lanes 20 &nbsp; GIỚI THIỆU CPU INTEL CORE I5 14400F TRAY NEW (UP TO 4.70GHZ, 10 NHÂN 16 LUỒNG, 20MB CACHE, LGA 1700) Intel Core i5-14400F mở ra một kỷ nguyên mới trong lĩnh vực vi xử lý với kiến trúc kết hợp được tối ưu hóa, cùng với công nghệ đầu ngành. CPU này không chỉ nâng cao trải nghiệm chơi game và sáng tạo của bạn mà còn mang lại khả năng thực hiện đa nhiệm mượt mà và hiệu suất xử lý ấn tượng. Hiệu suất mạnh mẽ&nbsp; Intel Core i5-14400F đưa hiệu năng đa nhiệm lên một tầm cao mới với cấu hình ấn tượng, gồm 10 nhân và 16 luồng. Không chỉ đảm bảo khả năng xử lý mượt mà các tác vụ phức tạp, mà còn nâng cao hiệu suất tổng thể. Với Intel Core i5-14400F, bạn có thể dễ dàng thực hiện các công việc nặng như chỉnh sửa video, thiết kế đồ họa, và thậm chí chơi các trò chơi đòi hỏi sức mạnh xử lý lớn mà không gặp phải bất kỳ trở ngại nào. Sự kết hợp giữa số lượng lõi và luồng lớn cùng với hiệu suất cao làm cho Intel Core i5-14400F trở thành', '{"Socket":"FCLGA1700","Dòng CPU":"Core i5","CPU":"Intel® Core® i5-14400F (Raptor Lake)","Số nhân":"10 (6 Performance-cores/ 4 Efficient-cores)","Số luồng":"16","Tốc độ Turbo tối đa của P-core":"4.7 GHz","Tốc độ&nbsp;Turbo tối đa của E-core&nbsp;":"3.5 GHz","Tốc độ cơ bản của P-core":"2.5 GHz","Tốc độ cơ bản của E-core":"1.8 GHz","Điện năng tiêu thụ":"65W - 148W","Bộ nhớ đệm":"20MB Intel® Smart Cache","Bo mạch chủ tương thích":"600 và 700 series"}', 0, 1);
