INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1075201966', 'SP1083761', '1075201966', 'https://www.maytinhbienhoa.vn/products/du-an-cpu-intel-core-i5-14600k-raptor-lake-refresh-lga-1700-tray-gen-14', '(S) CPU Intel Core I5 14600K (Raptor Lake Refresh, LGA 1700) TRAY GEN 14', 'du-an-cpu-intel-core-i5-14600k-raptor-lake-refresh-lga-1700-tray-gen-14', 'brand_intel_380', 'cat_cpu', 5890000, 5890000, 0, 4712000, 24, 'in_stock', '(S) CPU Intel Core I5 14600K (Raptor Lake Refresh, LGA 1700) TRAY GEN 14', 'THÔNG SỐ KỸ THUẬT &nbsp; Nhà sản xuất Intel Model i5-14600K CPU Intel Core&nbsp;i5-14600K Socket LGA1700 TDP 125W P-Cores 6 E-Cores 8 Số nhân 14 Số luồng 20 Base Core Frequency 3.5GHz Bộ nhớ Cache 24MB P-Core Max Turbo Frequency 5.3GHz E-Core Max Turbo Frequency 4.0GHz Tổng bộ đệm L2 20 MB Công suất Turbo tối đa 181 W Kích thước bộ nhớ tối đa 192GB Phân loại bộ nhớ Lên đến DDR5 5600 MT/s Lên đến DDR4 3200 MT/s Số kênh bộ nhớ tối đa 2 Băng thông bộ nhớ tối đa 89.6 GB/s Đồ họa bộ xử lý Intel® UHD 770 Tần số cơ sở đồ họa 300 MHz Tần số động tối đa của đồ họa 1,55 GHz Hỗ trợ DirectX 12 Hỗ trợ OpenGL 4,5 Hỗ trợ OpenCL 3.0 Công cụ Codec đa định dạng 2 Bộ tăng tốc thần kinh và Gaussian Intel 3.0&nbsp; Công nghệ Intel® Turbo Boost 2.0 Bảo hành 36 tháng CPU Intel Core i5-14600K&nbsp;là một sản phẩm ấn tượng trong dòng sản phẩm Intel với hiệu suất vượt trội và tích hợp đồ họa.&nbsp; Hiệu suất mạnh mẽ của &nbsp; CPU Intel i5-14600K Với 14 lõi và 20 luồng xử lý, CPU Intel Core i5-14600K cung cấp sức mạnh xử lý mạnh mẽ. Tốc độ cơ bản 4.0GHz và khả năng tăng tốc lên đến 5.3GHz giúp xử lý mọi tác vụ mượt mà và hiệu quả. Bộ nhớ đệm 24MB đảm bảo hiệu suất tối ưu. CPU Gen 14 này được tích hợp đồ họa Intel UHD Graphics 770: CPU Intel thế hệ 14&nbsp;này đi kèm với chip đồ họa tích hợp Intel UHD Graphics 770, giúp bạn xử lý các tác vụ đồ họa và thậm chí cả gaming một cách mượt mà. Hỗ Trợ Đa Dạng Cho Bộ Nhớ: CPU 14600K này hỗ trợ cả DDR5 5600 và DDR4 3200, cho phép bạn sử dụng bộ nhớ nhanh chóng v', '{"Nhà sản xuất":"Intel","Model":"i5-14600K","CPU":"Intel Core&nbsp;i5-14600K","Socket":"LGA1700","TDP":"125W","P-Cores":"6","E-Cores":"8","Số nhân":"14","Số luồng":"20","Base Core Frequency":"3.5GHz","Bộ nhớ Cache":"24MB","P-Core Max Turbo Frequency":"5.3GHz"}', 0, 1);
