INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1073558668', 'SP1083411', '1073558668', 'https://www.maytinhbienhoa.vn/products/cpu-intel-core-i9-14900kf-tray-gen-14', 'CPU Intel Core I9 14900KF Tray GEN 14', 'cpu-intel-core-i9-14900kf-tray-gen-14', 'brand_intel_380', 'cat_cpu', 11990000, 11990000, 0, 9592000, 24, 'out_of_stock', 'CPU Intel Core I9 14900KF Tray GEN 14', 'Thông số kỹ thuật CPU Intel Core i9-14900KF Thông tin chung Kiến trúc: Raptor Lake Refresh (14th Gen) Socket: LGA1700 Tiến trình: Intel 7 (≈10 nm) Ra mắt: Q4 / 2023 Không có iGPU (KF = không đồ họa tích hợp) Cấu hình nhân Tổng số nhân: 24 nhân 8 Performance-cores (P-cores) 16 Efficient-cores (E-cores) Luồng: 32 threads Xung nhịp P-core base: 3.2 GHz E-core base: 2.4 GHz Turbo tối đa: 6.0 GHz Turbo P-core: 5.6 GHz Turbo E-core: 4.4 GHz Bộ nhớ Cache L3 Cache: 36 MB Intel Smart Cache L2 Cache: 32 MB Bộ nhớ RAM hỗ trợ DDR4: 3200 MT/s DDR5: 5600 MT/s Dung lượng RAM tối đa: 192 GB Dual-channel memory PCIe PCIe 5.0 x16 PCIe 4.0 x4 (tổng 20 lanes từ CPU) Điện năng Processor Base Power: 125 W Maximum Turbo Power: 253 W Nhiệt độ tối đa (Tjunction): 100°C Công nghệ nổi bật Intel Turbo Boost Max 3.0 Intel Thermal Velocity Boost Hyper-Threading Intel Thread Director AVX2 / AES-NI / VT-x / VT-d &nbsp; &nbsp; Mô tả CPU Intel Core i9-14900KF Intel Core i9-14900KF là bộ vi xử lý cao cấp thuộc Intel Core thế hệ 14 (Raptor Lake Refresh) dành cho máy tính để bàn hiệu năng cao. CPU được thiết kế cho các hệ thống gaming, làm việc đồ họa, dựng phim và xử lý đa nhiệm nặng, mang lại sức mạnh xử lý vượt trội nhờ kiến trúc hybrid kết hợp giữa nhân hiệu năng cao và nhân tiết kiệm điện. Bộ xử lý này sở hữu 24 nhân và 32 luồng , bao gồm 8 Performance-cores (P-cores) dành cho các tác vụ nặng và 16 Efficient-cores (E-cores) giúp tối ưu đa nhiệm và tiết kiệm điện năng. Nhờ công nghệ Intel Hyper-Threading cùn', '{"Kiến trúc":"Raptor Lake Refresh (14th Gen)","Socket":"LGA1700","Tiến trình":"Intel 7 (≈10 nm)","Ra mắt":"Q4 / 2023","Tổng số nhân":"24 nhân 8 Performance-cores (P-cores)","Luồng":"32 threads","P-core base":"3.2 GHz","E-core base":"2.4 GHz"}', 0, 1);
