INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1055593582', 'SP1080462', '1055593582', 'https://www.maytinhbienhoa.vn/products/cpu-intel-core-i7-14700-raptor-lake-refresh-lga-1700-tray-gen-14', 'CPU Intel Core I7 14700 (Raptor Lake Refresh, LGA 1700) TRAY GEN 14', 'cpu-intel-core-i7-14700-raptor-lake-refresh-lga-1700-tray-gen-14', 'brand_intel_380', 'cat_cpu', 10490000, 10490000, 0, 8392000, 24, 'out_of_stock', 'CPU Intel Core I7 14700 (Raptor Lake Refresh, LGA 1700) TRAY GEN 14', 'THÔNG SỐ KỸ THUẬT &nbsp; Thương hiệu Intel Tình trạng Mới 100% Socket FCLGA1700 Thế hệ CPU 14 Số nhân 20 Số luồng 28 Tần số cơ bản 2.10 GHz Tần số tối đa 5.40 GHz Đồ họa tích hợp Intel® UHD Graphics 770 Bộ sản phẩm bao gồm CPU, quạt tản nhiệt, tem Intel, sách HDSD Bảo hành 3 Năm &nbsp; CPU Intel Core i7 14700 CPU Intel Core i7 14700 (Intel LGA1700 - 20 Core - 28 Thread - Base 2.1Ghz - Turbo 5.4Ghz - Cache 33MB) là bộ xử lý dành cho &nbsp;PC &nbsp;có 20 nhân 28 luồng được sử dụng kiến ​​trúc Products formerly Raptor Lake với Intel LGA1700. Đây là mẫu CPU vô cùng phù hợp với những dòng PC khủng, thường thực hiện các tác vụ với đồ họa và hiện đại. Sản phẩm có dung lượng bộ nhớ tối đa là 192 GB - là thông số ấn tượng thể hiện khả năng lưu trữ hoàn hảo của sản phẩm. Với &nbsp;bộ nhớ hỗ trợ tuy không dẫn đầu xu hướng công nghệ hiện nay - DDR5 4800 MT/s và DDR4 3200 MT/s, CPU Intel Core i7 14700 tự tin cung cấp cho người dùng những trải nghiệm tuyệt vời khi vẫn đủ khả năng cung cấp một loạt dữ liệu hình ảnh, video, âm thanh…&nbsp; một cách chính xác và nhanh chóng. Bên cạnh đó, việc xử các thông tin nặng cũng gọn gàng và xuất hiện độ trễ nhỏ. Sản phẩm còn được hỗ trợ tần số turbo tối đa là 5.4 GHz và tần số cơ sở là 2.1 GHz, lần lượt giúp chiếc CPU này tăng tốc độ xung nhịp khi cần thiết để xử lý các tác vụ nặng và giúp tiết kiệm điện năng. Với sản phẩm CPU Intel này với điện áp tiêu thụ tối đa là 219W, người dùng có thể sử dụng cho PC của mình kể cả trong thời gian dài cũng không t', '{"Thương hiệu":"Intel","Tình trạng":"Mới 100%","Socket":"FCLGA1700","Thế hệ CPU":"14","Số nhân":"20","Số luồng":"28","Tần số cơ bản":"2.10 GHz","Tần số tối đa":"5.40 GHz","Đồ họa tích hợp":"Intel® UHD Graphics 770","Bộ sản phẩm bao gồm":"CPU, quạt tản nhiệt, tem Intel, sách HDSD","Bảo hành":"3 Năm"}', 0, 1);
