INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1056305830', 'SP1080724', '1056305830', 'https://www.maytinhbienhoa.vn/products/main-asus-b760m-f-prime-d4', 'Main ASUS B760M-F PRIME D4', 'main-asus-b760m-f-prime-d4', 'brand_asus_316', 'cat_mainboard', 2150000, 2150000, 0, 1720000, 24, 'in_stock', 'Main ASUS B760M-F PRIME D4', '&nbsp; THỐNG SỐ KỸ THUẬT &nbsp; Model PRIME B760M-K D4 News &amp; Updates 2024/08/12: The new BIOS with Intel microcode (0x129) enhancing the stability of Intel Core 13th and 14th Gen desktop processors is now available. Please visit support site for the latest BIOS updates. CPU Ổ cắm Intel®&nbsp;LGA1700 dành cho bộ xử lý Intel®&nbsp;Core™ thế hệ thứ 14 và 13, bộ xử lý Intel®&nbsp;Core™ thế hệ thứ 12, Pentium®&nbsp;Gold và Celeron®* Hỗ trợ Công nghệ Intel® Turbo Boost 2.0 và Công nghệ Intel® Turbo Boost Max 3.0** * Tham khảo&nbsp;www.asus.com&nbsp;để biết danh sách hỗ trợ CPU. ** Hỗ trợ Công nghệ Intel® Turbo Boost Max 3.0 tùy thuộc vào loại CPU. Bộ chip Chipset Intel®&nbsp;B760 Bộ nhớ 2 x DIMM, Tối đa. 64GB, DDR4 5333(OC)/5066(OC)/5000(OC)/4800(OC)/4600(OC)/4400(OC)/4266(OC)/4000(OC)/3733(OC)/3600(OC)/3466(OC) /3400(OC)/3333(OC)/3200/3000/2933/2800/2666/2400/2133 Không ECC, Bộ nhớ không đệm* Kiến trúc bộ nhớ Dual Channel Hỗ trợ cấu hình bộ nhớ cực cao Intel® (XMP) Loại bộ nhớ được hỗ trợ, tốc độ dữ liệu (tốc độ), và số lượng module DRAM phụ thuộc vào CPU và cấu hình bộ nhớ, để biết thêm thông tin, vui lòng tham khảo danh sách hỗ trợ CPU/Bộ nhớ trong tab Hỗ trợ của trang thông tin sản phẩm hoặc truy cập&nbsp;https://www.asus.com/support/. Đồ họa 1 cổng VGA 1 cổng HDMI® ** Thông số đồ họa có thể thay đổi giữa các loại CPU. Vui lòng tham khảo&nbsp;www.intel.com&nbsp;để biết thông tin cập nhật. ** Hỗ trợ độ phân giải 4K@60Hz với cổng HDMI® 2.1. Khe cắm mở rộng Bộ xử lý Intel® Co', '{"Model":"PRIME B760M-K D4","CPU":"Ổ cắm Intel®&nbsp;LGA1700 dành cho bộ xử lý Intel®&nbsp;Core™ thế hệ thứ 14 và 13, bộ xử lý Intel®&nbsp;Core™ thế hệ thứ 12, Pentium®&nbsp;Gold và Celeron®*","Bộ nhớ":"2 x DIMM, Tối đa. 64GB, DDR4","Đồ họa":"1 cổng VGA","1 cổng HDMI® **":"Thông số đồ họa có thể thay đổi giữa các loại CPU. Vui lòng tham khảo&nbsp;www.intel.com&nbsp;để biết thông tin cập nhật.","1 x khe cắm PCIe 4.0 x16":"Chipset Intel® B760","2 x khe cắm PCIe 4.0 x1":"Lưu ý: Để đảm bảo tính tương thích của thiết bị được cài đặt, vui lòng tham khảo&nbsp;https://www.asus.com/support/&nbsp;để biết danh sách các thiết bị ngoại vi được hỗ trợ.","Lưu trữ":"Tổng cộng hỗ trợ 2 khe cắm M.2 và 4 cổng SATA 6Gb/s*","Chipset&nbsp;Intel® B760&nbsp;":"Khe M.2_2 (Key M), loại 2242/2260/2280 (hỗ trợ PCIe 4.0 x4 chế độ)","4 cổng SATA 6Gb/s":"* Công nghệ Intel® Rapid Storage hỗ trợ SATA RAID 0/1/5/10.","Ethernet":"1 x Realtek 2.5Gb Ethernet","USB":"Cổng USB phía sau (Tổng cộng 6 cổng)"}', 0, 1);
