INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1051109221', 'SP109013', '1051109221', 'https://www.maytinhbienhoa.vn/products/main-asrock-b760m-steel-legend-wifi-d5', 'Main ASROCK B760M Steel Legend WIFI D5', 'main-asrock-b760m-steel-legend-wifi-d5', 'brand_asrock_451', 'cat_mainboard', 3890000, 3890000, 0, 3112000, 24, 'out_of_stock', 'Main ASROCK B760M Steel Legend WIFI D5', 'THÔNG SỐ KỸ THUẬT &nbsp; Loại sản phẩm Mainboard Bo Mạch Chủ Hãng sản xuất ASRock Model B760M Steel Legend Wifi Hỗ trợ CPU - Hỗ trợ hệ thứ 13 &amp; 12 ( LGA1700 ) Bộ xử lý Intel Core - Hỗ trợ Công nghệ Intel Hybrid - Hỗ trợ Công nghệ Intel Turbo Boost Max 3.0 - Hỗ trợ Intel Thermal Velocity Boost (TVB) - Hỗ trợ Công nghệ tăng cường thích ứng Intel (ABT) - Hỗ trợ Công cụ ASRock Hyper BCLK Chipset Intel B760 RAM - Công nghệ bộ nhớ kênh đôi DDR5 - 4 khe cắm DIMM DDR5 - Hỗ trợ bộ nhớ DDR5 non-ECC, un-buffered lên đến 7200+(OC) * - Tối đa. Dung lượng bộ nhớ hệ thống: 128GB - Hỗ trợ Intel® Extreme Memory Profile (XMP) 3.0 BIOS BIOS hợp pháp AMI UEFI 128Mb có hỗ trợ GUI VGA - Kiến trúc đồ họa Intel® Xe (Thế hệ 12) - 1 x eDP 1.4, hỗ trợ tối đa. độ phân giải lên đến Full HD 60Hz - 1 x HDMI 2.1 Tương thích TMDS, hỗ trợ HDCP 2.3 trở lên. độ phân giải lên tới 4K 60Hz - 1 x DisplayPort 1.4 với DSC (đã nén), hỗ trợ HDCP 2.3 trở lên. độ phân giải lên tới 8K 60Hz / 5K 120Hz Âm thanh Âm thanh 7.1 CH HD (Codec âm thanh Realtek ALC897) Nahimic Audio LAN - Mạng LAN 2,5 Gigabit 10/100/1000/2500 Mb/giây - Rồng RTL8125BG - Hỗ trợ phần mềm Dragon 2.5G LAN - Kiểm soát băng thông tự động điều chỉnh thông minh - Giao diện người dùng thân thiện với người dùng trực quan - Thống kê sử dụng mạng trực quan - Cài đặt mặc định được tối ưu hóa cho chế độ trò chơi, trình duyệt và phát trực tuyến - Kiểm soát ưu tiên tùy chỉnh của người dùng Wireless LAN - Mô-đun Wi-Fi 6E 802.11ax - Hỗ trợ IEEE 802.11a/b/g/n/ac/a', '{"Loại sản phẩm":"Mainboard Bo Mạch Chủ","Hãng sản xuất":"ASRock","Model":"B760M Steel Legend Wifi","Chipset":"Intel B760","BIOS":"BIOS hợp pháp AMI UEFI 128Mb có hỗ trợ GUI","VGA":"Âm thanh","LAN":"Wireless LAN","Khe mở rộng":"Lưu trữ","RAID":"Supports RAID 0, RAID 1, RAID 5 and RAID 10 for SATA storage devices","USB":"- 2 x USB 3.2 Gen2 Type-C (1 Rear, 1 Front) - 1 x USB 3.2 Gen2 Type-A (Rear) - 6 x USB 3.2 Gen1 (4 Rear, 2 Front) - 6 x USB 2.0 (2 Rear, 4 Front) *&nbsp;All USB ports support ESD Protection","Cổng kết nối":"Phần mềm và UEFI","Phụ kiện":"Kích thước"}', 0, 1);
