INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1048261763', 'SP108453', '1048261763', 'https://www.maytinhbienhoa.vn/products/main-asrock-b760m-pg-lightning-d4-intel-b760-socket-1700-micro-atx-4-khe-ddr4', 'Main Asrock B760M PG Lightning D4 ( Intel B760, Socket 1700, Micro ATX, 4 khe DDR4)', 'main-asrock-b760m-pg-lightning-d4-intel-b760-socket-1700-micro-atx-4-khe-ddr4', 'brand_asrock_451', 'cat_mainboard', 2690000, 2690000, 0, 2152000, 24, 'out_of_stock', 'Main Asrock B760M PG Lightning D4 ( Intel B760, Socket 1700, Micro ATX, 4 khe DDR4)', 'ĐẶC ĐIỂM NỔI BẬT Mainboard PC ASRock B760M PG Lightning/D4 Hoạt động bền vững, ổn định Bo mạch chủ&nbsp; ASRock B760M PG Lightning/D4 &nbsp;cung cấp&nbsp;giao diện PCI Express 4.0 tốc độ cao&nbsp;và bo mạch&nbsp;cung cấp khả năng phân phối điện mạnh mẽ và làm mát hiệu quả, giúp&nbsp;khai thác tiềm năng của bộ xử lý Intel thế hệ thứ 12th và 13th&nbsp;mới nhất. Cổng kết nối ASRock B760M PG Lightning/D4&nbsp; được trang bị đẩy đủ các cổng kết nối để bạn dễ dàng lắp đặt. Hỗ trợ M.2 PCIe 4.0 (Lên đến 64Gbps) ASRock B760M PG Lightning/D4 &nbsp;hỗ trợ 2 khe cắm&nbsp;M.2 PCIe 4.0 cho tốc độ truyền cực nhanh&nbsp;đến 64GB/s&nbsp;và cung cấp hỗ trợ NVMe SSD RAID để tăng hiệu suất đáng kinh ngạc. Tạo cấu hình RAID với thiết bị lưu trữ&nbsp;PCIe&nbsp;để tận hưởng tốc độ truyền dữ liệu nhanh nhất trên nền tảng Intel&nbsp;thế hệ mới. Dr.Mos ASRock B760M PG Lightning/D4 &nbsp;giải pháp công suất tích hợp giúp tối ưu hóa cho các ứng dụng điện áp hạ áp đồng bộ. Nó cung cấp dòng điện cao hơn một cách thông minh cho mỗi pha, do đó mang lại kết quả nhiệt được cải thiện và hiệu suất vượt trội. Gigabit LAN Cổng mạng Gigabit LAN&nbsp;được thiết kế dành riêng cho các game thủ&nbsp;yêu thích hiệu suất, giúp&nbsp;tối ưu cho các trải nghiệm nâng cao về tốc độ cho&nbsp;ứng dụng chơi game và đa phương tiện. Khe cắm PCIe 4.0 ASRock B760M PG Lightning/D4&nbsp; cải thiện tín hiệu và tối ưu hóa độ ổn định một cách đột phá với cổng PCIe 4.0 cho băng thông lên đến 128GBps, sẵn sàng giải phóng toàn bộ tiềm năng', '{"Model":"Main Asrock B760M PG Lightning D4 ( Intel B760, Socket 1700, Micro ATX, 4 khe DDR4)"}', 0, 1);
