INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1070070921', 'SP1082645', '1070070921', 'https://www.maytinhbienhoa.vn/products/ram-ddr5-16gb-dell-ecc-5600mt-s-udimm', 'RAM DDR5 16GB DELL ECC 5600MT/s UDIMM', 'ram-ddr5-16gb-dell-ecc-5600mt-s-udimm', 'brand_dell_289', 'cat_ram', 16900000, 16900000, 0, 13520000, 24, 'in_stock', 'RAM DDR5 16GB DELL ECC 5600MT/s UDIMM', '&nbsp; &nbsp; Thông số bộ nhớ RAM server được cung cấp như sau: Loại sản phẩm : RAM Server Thương hiệu : Samsung Dung lượng : 16GB Loại DIMM : ECC RDIMM (Bộ nhớ đăng ký có khả năng sửa lỗi) Giao diện DIMM : DDR5 Tốc độ DIMM : 5600 MHz Đây là một mô-đun bộ nhớ server hiệu suất cao, được thiết kế cho các hệ thống yêu cầu sửa lỗi và xử lý dữ liệu tốc độ cao, như máy chủ doanh nghiệp hoặc trung tâm dữ liệu. DDR5 cung cấp băng thông và hiệu suất tốt hơn so với các thế hệ trước, và tốc độ 5600 MHz cho thấy nó được tối ưu hóa cho các ứng dụng hiện đại, đòi hỏi khắt khe. ECC RDIMM đảm bảo tính toàn vẹn dữ liệu, rất quan trọng cho các môi trường quan trọng.', '{"Loại sản phẩm":"RAM Server","Thương hiệu":"Samsung","Dung lượng":"16GB","Loại DIMM":"ECC RDIMM (Bộ nhớ đăng ký có khả năng sửa lỗi)","Giao diện DIMM":"DDR5","Tốc độ DIMM":"5600 MHz"}', 0, 1);
