INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1076032336', 'SP1084004', '1076032336', 'https://www.maytinhbienhoa.vn/products/du-an-ram-ddr4-16gb-vsp-3200-tan-thep', 'RAM DDR4 16GB VSP 3200 TẢN THÉP', 'du-an-ram-ddr4-16gb-vsp-3200-tan-thep', 'brand_vsp_249', 'cat_ram', 2550000, 2550000, 0, 2040000, 24, 'in_stock', 'RAM DDR4 16GB VSP 3200 TẢN THÉP', 'Thông số kỹ thuật Mã sản phẩm / Model 16GB DDR4XMP3200 Thiết bị hỗ trợ Máy tính để bàn (PC Desktop) - Giao diện: 288-pin U-DIMM Tính tương thích Chuyên dụng chỉ hỗ trợ CPU Intel (Only support for Intel Processors) Loại bộ nhớ DDR4 Dung lượng 16GB Tốc độ Bus (Frequency) 3200 MHz (Hỗ trợ cấu hình XMP) Độ trễ (CAS Latency) CL19 (XMP 3200) Điện áp hoạt động 1.2V / 1.35V (Tiết kiệm điện &amp; ổn định) Tản nhiệt (Heatsink) Có (Giáp tản nhiệt nhôm nguyên khối màu đen) Môi trường hoạt động Nhiệt độ hoạt động: 0°C đến +85°C (Hoạt động ổn định liên tục) Nhiệt độ bảo quản: -20°C đến +100°C &nbsp; &nbsp; &nbsp; ếu bạn đang muốn nâng cấp chiếc máy tính để bàn sử dụng bộ vi xử lý Intel của mình để có trải nghiệm mượt mà và tối ưu hơn, thì&nbsp; Bộ Nhớ RAM VSP 16GB DDR4 3200MHz XMP Tản Nhiệt Đen (Chỉ Hỗ Trợ CPU Intel) &nbsp;chính là giải pháp hoàn hảo mà bạn không thể bỏ qua. Đây là dòng&nbsp; bộ nhớ RAM máy tính VSP &nbsp;thế hệ mới được thiết kế đặc quyền cho hệ thống phần cứng của Intel, sở hữu giáp tản nhiệt đen cá tính và xung nhịp mạnh mẽ, hứa hẹn sẽ mang đến luồng sinh khí mới cho bộ PC của bạn. &nbsp; TỐI ƯU HÓA ĐỘC QUYỀN CHO INTEL - ĐẢM BẢO TƯƠNG THÍCH HOÀN HỎA RAM VSP 16GB DDR4 3200MHz phiên bản này sở hữu vi mã độc quyền được tối ưu sâu để&nbsp; chỉ hỗ trợ CPU Intel . Sự chuyên biệt hóa này mang lại lợi ích cực kỳ to lớn khi giúp thanh RAM nhanh chóng đồng bộ và đạt được sự ổn định tuyệt đối trên các dòng bo mạch chủ sử dụng chipset Intel phổ biến hiện nay. Mọi hiện tượng xung độ', '{"Mã sản phẩm / Model":"16GB DDR4XMP3200","Thiết bị hỗ trợ":"Máy tính để bàn (PC Desktop) - Giao diện: 288-pin U-DIMM","Tính tương thích":"Chuyên dụng chỉ hỗ trợ CPU Intel (Only support for Intel Processors)","Loại bộ nhớ":"DDR4","Dung lượng":"16GB","Tốc độ Bus (Frequency)":"3200 MHz (Hỗ trợ cấu hình XMP)","Độ trễ (CAS Latency)":"CL19 (XMP 3200)","Điện áp hoạt động":"1.2V / 1.35V (Tiết kiệm điện &amp; ổn định)","Tản nhiệt (Heatsink)":"Có (Giáp tản nhiệt nhôm nguyên khối màu đen)","Môi trường hoạt động":"Nhiệt độ hoạt động: 0°C đến +85°C (Hoạt động ổn định liên tục) Nhiệt độ bảo quản: -20°C đến +100°C"}', 0, 1);
