INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1068248225', 'SP1082251', '1068248225', 'https://www.maytinhbienhoa.vn/products/ram-ddr4-16gb-colorfire-scorpio-3200mhz', 'RAM DDR4 16GB Colorfire Scorpio 3200MHz', 'ram-ddr4-16gb-colorfire-scorpio-3200mhz', 'brand_colorfire_677', 'cat_ram', 2450000, 2450000, 0, 1960000, 24, 'in_stock', 'RAM DDR4 16GB Colorfire Scorpio 3200MHz', 'THÔNG SỐ CƠ BẢN: Dòng RAM: COLORFIRE Tên sản phẩm: COLORFIRE DDR4 16G 3200 Kiểu bộ nhớ: Hynix/Micron Chuẩn áp dụng: Máy tính để bàn Dung lượng RAM: 16G Điện áp làm việc: 1.35V Hỗ trợ tản nhiệt: Có hỗ trợ &nbsp; RAM Colorfire Scorpio DDR4 16G 3200 Dung lượng và tốc độ : RAM Colorfire Scorpio DDR4 16G 3200 là một sản phẩm bộ nhớ máy tính cao cấp, mang đến hiệu năng mạnh mẽ và độ ổn định cao, rất phù hợp cho game thủ và người dùng làm việc chuyên nghiệp. Với dung lượng 16GB, sản phẩm này đáp ứng tốt nhu cầu đa nhiệm và xử lý dữ liệu lớn. Tốc độ bus 3200 MHz giúp tăng cường hiệu suất hệ thống, đảm bảo hoạt động mượt mà trong các ứng dụng yêu cầu tài nguyên cao như chơi game, đồ họa và lập trình. Hiệu năng: Được sản xuất theo công nghệ DDR4, RAM Colorfire Scorpio 16G 3200 cung cấp tốc độ truyền tải dữ liệu nhanh hơn và tiêu thụ điện năng thấp hơn so với thế hệ DDR3 trước đó. Sản phẩm này cũng hỗ trợ XMP 2.0 (Extreme Memory Profile), cho phép người dùng dễ dàng ép xung bộ nhớ để đạt hiệu suất tối ưu mà không cần điều chỉnh thủ công. Thiết kế : Thiết kế của RAM Colorfire Scorpio hiện đại và bắt mắt với tản nhiệt nhôm, giúp tăng cường khả năng tản nhiệt, giữ cho RAM luôn mát mẻ và hoạt động ổn định ngay cả khi chịu tải nặng. Kích thước tiêu chuẩn của sản phẩm dễ dàng lắp đặt trong các case máy tính khác nhau. Tính tương thích : Sản phẩm này tương thích với hầu hết các bo mạch chủ trên thị trường hiện nay, dễ dàng nâng cấp cho các hệ thống PC. Nó đặc biệt phù hợp với các cấu hình máy ', '{"Dòng RAM":"COLORFIRE","Tên sản phẩm":"COLORFIRE DDR4 16G 3200","Kiểu bộ nhớ":"Hynix/Micron","Chuẩn áp dụng":"Máy tính để bàn","Dung lượng RAM":"16G","Điện áp làm việc":"1.35V","Hỗ trợ tản nhiệt":"Có hỗ trợ"}', 0, 1);
