INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1071283089', 'SP1082871', '1071283089', 'https://www.maytinhbienhoa.vn/products/ram-ddr4-8gb-gskill-ripjaws-v-3200', 'RAM DDR4 8GB GSKILL AEGIS 3200', 'ram-ddr4-8gb-gskill-ripjaws-v-3200', 'brand_gskill_454', 'cat_ram', 1690000, 1690000, 0, 1352000, 24, 'in_stock', 'RAM DDR4 8GB GSKILL AEGIS 3200', 'THÔNG SỐ KỸ THUẬT &nbsp; Sản Phẩm Bộ nhớ trong RAM Hãng sản xuất G.Skill Model F4-3200C16S-8GIS Loại RAM DDR4 Dung lượng 8GB Bus 3200MHz Độ trễ 16-18-18-38 &nbsp; Điện áp 1.35V Tản nhiệt Có Công nghệ RAM Non-ECC &nbsp; Bộ nhớ trong &nbsp;GSKill&nbsp;được đặt tên theo chiếc khiên cứng cáp của các vị thần Hy Lạp -&nbsp;Aegis.&nbsp; Được hoàn thành với chất lượng cao nhất nhờ việc các IC được chọn kỹ càng và được thử nghiệm với quy trình xác nhận nghiêm ngặt của&nbsp;GSKILL&nbsp;trên tất cả các thương hiệu&nbsp;bo mạch chủ&nbsp;nổi tiếng và thông dụng, bộ nhớ&nbsp; RAM GSKILL &nbsp;được thiết kế đạt được sợ tương thích và ổn định nhất với các thiết bị cơ sở khác nhau. Được chế tạo với chất lượng cao nhất của các vi mạch được lựa chọn thủ công và được kiểm tra với quy trình xác nhận nghiêm ngặt của G.SKILL trên tất cả các thương hiệu bo mạch chủ hiệu suất lớn. Hiệu năng mạnh mẽ Ram Gskill 8G DDR4 bus 3200 &nbsp;là sự bổ sung mới trong hệ thống của&nbsp;GSKILL, được thiết kế để nâng cao hiệu năng đem lại sự ổn định cao cho mọi máy tính chơi game, cho dù là các tựa game FPS, MOBA hay&nbsp;MMORPG...nặng đều được vận hành trợ tru, mượt mà.&nbsp; Được thiết kế với điện áp thấp 1.2V ở tiêu chuẩn DDR4, giảm 20% yêu cầu điện áp so với bộ nhớ DDR3. Giúp cho hệ thống máy tính của người dùng vận hành nhanh hơn, cùng với công nghệ tản nhiệt được dán trực tiếp lên&nbsp;RAM&nbsp;khi chơi game, hay thực hiện nhiều tác vụ một lúc mà không lo bị quá nhiệt.&nbsp; Với tốc độ khởi đầu sẵn ', '{"Sản Phẩm":"Bộ nhớ trong RAM","Hãng sản xuất":"G.Skill","Model":"F4-3200C16S-8GIS","Loại RAM":"DDR4","Dung lượng":"8GB","Bus":"3200MHz","Độ trễ":"16-18-18-38 &nbsp;","Điện áp":"1.35V","Tản nhiệt":"Có","Công nghệ RAM":"Non-ECC"}', 0, 1);
