INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1076152039', 'SP1084049', '1076152039', 'https://www.maytinhbienhoa.vn/products/ram-ddr4-8gb-geil-buss-3200-storming-v-tan-nhiet', 'RAM DDR4 8GB BIOSTAR BUSS 3200 STORMING V TẢN NHIỆT', 'ram-ddr4-8gb-geil-buss-3200-storming-v-tan-nhiet', 'brand_biostar_532', 'cat_ram', 1490000, 1490000, 0, 1192000, 24, 'in_stock', 'RAM DDR4 8GB BIOSTAR BUSS 3200 STORMING V TẢN NHIỆT', '&nbsp; &nbsp; RAM DDR4 8GB Biostar Storming V Bus 3200MHz tản nhiệt là dòng linh kiện phổ thông từ hãng Biostar , thiết kế kèm áo giáp nhôm giúp tản nhiệt tốt và ổn định cho máy tính để bàn chạy chip Intel lẫn AMD . Thông số kỹ thuật Loại RAM: DDR4 Dung lượng: 8GB Tốc độ Bus: 3200MHz Bộ tản nhiệt: Có (giúp linh kiện mát mẻ khi tải nặng) Tương thích: Mainboard hỗ trợ DDR4 cho cả Intel và AMD Ưu điểm nổi bật Hiệu năng ổn định: Tốc độ 3200MHz đáp ứng tốt nhu cầu học tập, làm việc văn phòng và chơi game phổ thông. Hoạt động mát mẻ: Nhờ lớp tản nhiệt kim loại bọc bên ngoài, hạn chế tình trạng quá nhiệt khi dùng lâu. Dễ nâng cấp: Phù hợp để lắp thêm một thanh nữa chạy Dual Channel giúp tăng tốc độ toàn bộ hệ thống. &nbsp;', '{"Loại RAM":"DDR4","Dung lượng":"8GB","Tốc độ Bus":"3200MHz","Bộ tản nhiệt":"Có (giúp linh kiện mát mẻ khi tải nặng)","Tương thích":"Mainboard hỗ trợ DDR4 cho cả Intel và AMD","Hiệu năng ổn định":"Tốc độ 3200MHz đáp ứng tốt nhu cầu học tập, làm việc văn phòng và chơi game phổ thông.","Hoạt động mát mẻ":"Nhờ lớp tản nhiệt kim loại bọc bên ngoài, hạn chế tình trạng quá nhiệt khi dùng lâu.","Dễ nâng cấp":"Phù hợp để lắp thêm một thanh nữa chạy Dual Channel giúp tăng tốc độ toàn bộ hệ thống."}', 0, 1);
