INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1073028809', 'SP1083264', '1073028809', 'https://www.maytinhbienhoa.vn/products/ram-ddr3-8gb-teamm-elite-buss-1600', 'RAM DDR3 8GB TEAM ELITE BUSS 1600', 'ram-ddr3-8gb-teamm-elite-buss-1600', 'brand_team_295', 'cat_ram', 699000, 699000, 0, 559200, 24, 'in_stock', 'RAM DDR3 8GB TEAM ELITE BUSS 1600', 'Bộ nhớ&nbsp;Ram Team Elite 8GB DDR3 Bus 1600 TED38G1600C1101 Bộ nhớ&nbsp;Ram Team Elite 8GB DDR3 Bus 1600 TED38G1600C1101 &nbsp;thuộc dòng&nbsp;RAM&nbsp;tầm trung&nbsp;của Team gồm 1&nbsp;thanh DDR3&nbsp;có dung lượng bộ nhớ 8GB và băng thông bus 1600Mhz, tương thích tốt với cả nền tảng bo mạch chủ (mainboard) hỗ trợ RAM kênh đôi (dual-channel) và cả 4 kênh (quad-channel). Bộ nhớ&nbsp; Ram Team Elite 8GB DDR3 Bus 1600 TED38G1600C1101 &nbsp; thiết kế với điện áp thấp 1,5V DDR3 thu hút ít năng lượng và tạo ra ít nhiệt. Hình thức mỏng và kiểu dáng đẹp thiết kế phù hợp với PCB màu đen cho nó một cái nhìn tích cực. Nó cũng có điểm nổi bật là hiệu năng khá tốt, dễ dàng lắp đặt và sử dụng, dễ dàng thay đổi ở BIOS. Tương tự một số dòng RAM thiết kế cho máy tính&nbsp;phổ thông,&nbsp; bộ nhớ&nbsp;Ram Team Elite 8GB DDR3 Bus 1600 TED38G1600C1101&nbsp; không trang bị cơ chế sửa lỗi ECC (error-correcting code). Các con&nbsp;chip&nbsp;bộ nhớ được áp dụng công nghệ BGA (Ball Grid Array) có khả năng giảm đến 50% nhiệt lượng tỏa ra so với công nghệ đóng gói TSOP (Thin Small Outline Package) trước đây.', '{"Model":"RAM DDR3 8GB TEAM ELITE BUSS 1600"}', 0, 1);
