INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1038248194', 'SP105955', '1038248194', 'https://www.maytinhbienhoa.vn/products/ram-ddr5-kingston-fury-beast-kf560c40bbk2-32-32gb-2x16gb-6000mhz', 'Ram DDR5 32GB Kingston Fury Beast (2x16GB) 6000Mhz', 'ram-ddr5-kingston-fury-beast-kf560c40bbk2-32-32gb-2x16gb-6000mhz', 'brand_kingston_621', 'cat_ram', 3090000, 3090000, 0, 2472000, 24, 'out_of_stock', 'Ram DDR5 32GB Kingston Fury Beast (2x16GB) 6000Mhz', 'Kingston FURY Beast DDR5 Bộ nhớDung lượng 16GB lên đến 6000MT/s * Kingston FURY™ Beast DDR5&nbsp;bộ nhớ mang đến công nghệ đột phá mới nhất cho nền tảng chơi game thế hệ tiếp theo. Nâng cao tốc độ, dung lượng và độ tin cậy, DDR5 đi kèm với kho tính năng nâng cao như on-die ECC (ODECC) để cải thiện độ ổn định khi chạy ở tốc độ cực cao, kênh phụ 32-bit kép để nâng cao hiệu suất, cùng với mạch tích hợp quản lý nguồn (PMIC) trên mô-đun để cung cấp năng lượng cho những chỗ cần nhất. Những cải tiến tốc độ ưu việt, với băng nhớ nhân đôi từ 16 đến 32 và chiều dài truyền loạt tăng gấp đôi từ 8 đến 16, sẽ đưa bộ nhớ DDR5, trải nghiệm chơi game và tổng thể ứng dụng hệ thống đạt hiệu năng vượt trội. Cho dù bạn tìm cách bứt phá các giới hạn mới khi chơi game thông qua mức cài đặt siêu cao, livestream ở chất lượng 4K+ hay tăng cường khả năng xử lý hoạt họa và render 3D, Kingston FURY Beast DDR5 thì nâng cao bộ nhớ là điều cần thiết, song hành cùng thiết kế kết nối liền mạch và hiệu năng đỉnh cao. Ngoài ra, sản phẩm này còn sử dụng Intel® XMP 3.0, một thông số kỹ thuật ép xung mới bao gồm hai cấu hình có thể tuỳ chỉnh tốc độ và thời gian. Tính năng Hiệu năng tốt hơn từ 4800MT/s * Cải thiện độ ổn định để ép xung Nâng cao hiệu suất Tương thích với Intel® XMP 3.0 và được chứng nhận XMP Được chứng nhận bởi các nhà sản xuất bo mạch chủ hàng đầu thế giới 1 Cắm là chạy ở 4800MT/s * 2 Thiết kế bộ tản nhiệt đơn giản', '{"Model":"Ram DDR5 32GB Kingston Fury Beast (2x16GB) 6000Mhz"}', 0, 1);
