INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1052220524', 'SP109239', '1052220524', 'https://www.maytinhbienhoa.vn/products/ram-ddr5-64gb-cosair-vengeance-rgb-2x32gb-5600mhz-black-1', 'RAM DDR5 64GB COSAIR VENGEANCE RGB (2x32GB) 5600MHz Black', 'ram-ddr5-64gb-cosair-vengeance-rgb-2x32gb-5600mhz-black-1', 'brand_corsair_531', 'cat_ram', 5690000, 5690000, 0, 4552000, 24, 'out_of_stock', 'RAM DDR5 64GB COSAIR VENGEANCE RGB (2x32GB) 5600MHz Black', 'Đánh giá chi tiết RAM&nbsp;Corsair Vengeance RGB 64GB (2x32GB) 5600MHz DDR5 Vốn được biết đến với những sản phẩm bao gồm linh kiện cùng gaming gear chất lượng, Corsair là cái tên luôn nằm trong top đầu bảng xếp hạng khi được game thủ lựa chọn phụ kiện cho mình. Và cái tên&nbsp; Corsair Vengeance RGB &nbsp;chính là 1 ví dụ điển hình khi luôn nằm trong top những chiếc RAM DDR5 tốt nhất hiện nay.&nbsp; Thiết kế đẹp mắt không kém phần chắc chắn Một lớp áo cực kì đẹp mắt được khoác lên Corsair Vengeance RGB đi kèm với đó là những hoa văn đối xứng, tạo nên cái nhìn cân đối cho chiếc&nbsp;RAM Corsair. Kết hợp cùng màu đen huyền bí, xây dựng nên vẻ ngoài mạnh mẽ cần thiết cho mọi game thủ. “Bộ giáp” ấy được hoàn thiện với chất liệu nhôm, đem lại cho Corsair Vengeance RGB khả năng phát tán nhiệt tối ưu. Ngoài ra, chất liệu nhôm đã đem lại những đường nét đen nhám làm tô điểm thêm góc gaming khi xuất hiện trong&nbsp;case. Hiệu năng mạnh mẽ với chuẩn DDR5 Thuộc về loại&nbsp;RAM DDR5&nbsp;tiên tiến nhất hiện nay, Corsair Vengeance RGB đem lại hiệu năng xử lý tác vụ tuyệt vời với băng thông lớn. Đi cùng với đó là con chip bộ nhớ giúp đảm bảo hiệu suất cùng tần số xử lý tối ưu nhất cho người dùng. Intel XMP 3.0 Công nghệ đến từ một trong những “ông hoàng” trong ngành&nbsp;CPU&nbsp;- Intel, đó là Intel XMP 3.0. Được áp dụng trên nhiều kit&nbsp;RAM&nbsp;cao cấp nhất hiện nay, Intel XMP 3.0 cung cấp cho người dùng khả năng tùy biến thoải mái với từng cài đặt cho từng profile theo yêu cầu tác ', '{"Model":"RAM DDR5 64GB COSAIR VENGEANCE RGB (2x32GB) 5600MHz Black"}', 0, 1);
