INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1047035632', 'SP108197', '1047035632', 'https://www.maytinhbienhoa.vn/products/ram-ddr5-16gb-kingston-fury-beast-rgb-5200mhz-kit-8gbx2', 'RAM DDR5 16GB Kingston Fury Beast RGB 5200mHZ KIT (8GBX2)', 'ram-ddr5-16gb-kingston-fury-beast-rgb-5200mhz-kit-8gbx2', 'brand_kingston_621', 'cat_ram', 2480000, 2480000, 0, 1984000, 24, 'out_of_stock', 'RAM DDR5 16GB Kingston Fury Beast RGB 5200mHZ KIT (8GBX2)', 'RAM Kit Kingston Fury Beast RGB 16/32GB DDR5 Sức mạnh từ Kingston Fury Beast Kingston FURY™ Beast DDR5&nbsp;bộ nhớ mang đến công nghệ đột phá mới nhất cho nền tảng chơi game thế hệ tiếp theo. Nâng cao tốc độ, dung lượng và độ tin cậy, DDR5 đi kèm với kho tính năng nâng cao như on-die ECC (ODECC) để cải thiện độ ổn định khi chạy ở tốc độ cực cao, kênh phụ 32-bit kép để nâng cao hiệu suất, cùng với mạch tích hợp quản lý nguồn (PMIC) trên mô-đun để cung cấp năng lượng cho những chỗ cần nhất. Khởi động sau một cái chớp mắt Trang bị thông số cực khủng với những dòng có tốc độ&nbsp; Bus 5200/5600/6000MHz &nbsp;và sử dụng chuẩn DDR5 mới nhất hiện nay,&nbsp; Ram Kit &nbsp; Kingston Fury Beast &nbsp;giúp bạn khởi động chiếc&nbsp;PC Gaming&nbsp;nhanh vượt trội so với thanh&nbsp;RAM&nbsp;chuẩn cũ. Cải thiện khả năng ép xung Công nghệ On-die ECC (ODECC) trên&nbsp; RAM Kit Kingston Fury Beast &nbsp;giúp duy trì tính toàn vẹn dữ liệu để đảm bảo hiệu năng cao nhất khi ép xung. Hiệu suất vượt trội Với việc băng thông và chiều dài truyền loạt đều tăng gấp đôi cùng hai kênh phụ 32-bit độc lập và khả năng xử lý dữ liệu vượt trội của&nbsp; DDR5 ,&nbsp; Kingston Fury Beast &nbsp;là trợ thủ đắc lực trong những cỗ máy chiến game hay các phần mềm đòi hỏi hiệu năng cao từ dàn máy. Tương thích với Intel® XMP 3.0 và được chứng nhận XMP Thời gian, tốc độ và điện áp nâng cao, đã được tối ưu hóa trong quá trình sản xuất của Kingston Fury Beast, mang đến hiệu năng ép xung và lưu các cấu hình mới do người d', '{"Model":"RAM DDR5 16GB Kingston Fury Beast RGB 5200mHZ KIT (8GBX2)"}', 0, 1);
