INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074976296', 'SP1083718', '1074976296', 'https://www.maytinhbienhoa.vn/products/ssd-biostar-128gb-s170-sata-lll', 'SSD BIOSTAR 128GB S170 SATA lll', 'ssd-biostar-128gb-s170-sata-lll', 'brand_biostar_532', 'cat_ssd-hdd', 699000, 699000, 0, 559200, 24, 'in_stock', 'SSD BIOSTAR 128GB S170 SATA lll', 'Thông số kỹ thuật SSD BIOSTAR S170 128GB SATA III Thông số Chi tiết Model BIOSTAR S170-128G Dung lượng 128GB Chuẩn giao tiếp SATA III 6Gb/s Kích thước 2.5 inch Độ dày 7mm (Ultraslim) Loại bộ nhớ 3D NAND Flash Tốc độ đọc tuần tự Lên đến 500 MB/s Tốc độ ghi tuần tự Lên đến 400 MB/s Thiết kế Chống sốc, trọng lượng nhẹ Độ ồn Hoạt động không tiếng ồn Điện năng tiêu thụ Thấp, tiết kiệm điện Tương thích Laptop, PC hỗ trợ SATA III/SATA II &nbsp; &nbsp; &nbsp; SSD BIOSTAR S170 128GB SATA III là giải pháp nâng cấp hiệu năng hiệu quả cho máy tính để bàn và laptop với chi phí hợp lý. Sản phẩm sử dụng giao tiếp SATA III 6Gb/s cùng bộ nhớ 3D NAND Flash hiện đại, mang lại tốc độ đọc lên đến 500MB/s và ghi lên đến 400MB/s, giúp tăng tốc toàn diện hệ thống so với ổ cứng HDD truyền thống. Với thiết kế chuẩn 2.5 inch siêu mỏng chỉ 7mm, BIOSTAR S170 128GB dễ dàng lắp đặt trên hầu hết các dòng laptop và PC hiện nay. Công nghệ 3D NAND không chỉ nâng cao hiệu suất truy xuất dữ liệu mà còn giúp tăng độ bền, giảm mức tiêu thụ điện năng và đảm bảo hoạt động ổn định trong thời gian dài. &nbsp; &nbsp; &nbsp; SSD BIOSTAR S170 mang đến khả năng khởi động hệ điều hành nhanh chóng, rút ngắn thời gian mở ứng dụng, tăng tốc xử lý công việc văn phòng, học tập và giải trí hàng ngày. Thiết kế không có bộ phận cơ học giúp ổ cứng hoạt động êm ái, chống rung và chống sốc hiệu quả hơn so với HDD truyền thống. Đây là lựa chọn phù hợp cho người dùng cần nâng cấp máy tính cũ, cải thiện tốc độ làm việc và tối ưu chi phí', '{"Model":"BIOSTAR S170-128G","Dung lượng":"128GB","Chuẩn giao tiếp":"SATA III 6Gb/s","Kích thước":"2.5 inch","Độ dày":"7mm (Ultraslim)","Loại bộ nhớ":"3D NAND Flash","Tốc độ đọc tuần tự":"Lên đến 500 MB/s","Tốc độ ghi tuần tự":"Lên đến 400 MB/s","Thiết kế":"Chống sốc, trọng lượng nhẹ","Độ ồn":"Hoạt động không tiếng ồn","Điện năng tiêu thụ":"Thấp, tiết kiệm điện","Tương thích":"Laptop, PC hỗ trợ SATA III/SATA II"}', 0, 1);
