INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074528327', 'SP1083582', '1074528327', 'https://www.maytinhbienhoa.vn/products/ssd-biostar-256gb-s160-sata-iii-2-5inch', 'SSD Biostar 256GB S160 Sata III 2.5inch', 'ssd-biostar-256gb-s160-sata-iii-2-5inch', 'brand_biostar_532', 'cat_ssd-hdd', 990000, 990000, 0, 792000, 24, 'in_stock', 'SSD Biostar 256GB S160 Sata III 2.5inch', 'THÔNG SỐ KỸ THUẬT &nbsp; Mẫu sản phẩm Thương hiệu: Biostar Model: S160-256GB Mã sản phẩm: S160-256GB Loại thiết bị: Ổ cứng thể rắn SSD gắn trong Đối tượng sử dụng: Người dùng phổ thông Chi tiết sản phẩm Chuẩn kích thước: 2.5 inch Dung lượng: 256GB Loại bộ nhớ: 3D TLC Giao tiếp: SATA III Bộ điều khiển (Controller): MaxIO 1102 Hiệu năng Tốc độ đọc tuần tự tối đa: Lên đến 550MB/s Tốc độ ghi tuần tự tối đa: Lên đến 500MB/s Kích thước &amp; Trọng lượng Độ dày: 7.00mm Trọng lượng: 36g &nbsp; &nbsp; Biostar S160-256GB SSD là dòng ổ cứng SSD SATA 2.5 inch hướng đến người dùng phổ thông, mang lại tốc độ truy xuất dữ liệu nhanh, vận hành ổn định và tiết kiệm chi phí nâng cấp cho máy tính. Sản phẩm sử dụng bộ nhớ 3D TLC kết hợp giao tiếp SATA III 6Gb/s giúp cải thiện đáng kể tốc độ khởi động hệ điều hành, mở ứng dụng và sao chép dữ liệu so với ổ HDD truyền thống. &nbsp; &nbsp; &nbsp; Với tốc độ đọc tuần tự lên đến 550MB/s và ghi lên đến 500MB/s, Biostar S160-256GB đáp ứng tốt nhu cầu học tập, văn phòng, giải trí và chơi game nhẹ. Thiết kế 2.5 inch siêu mỏng 7mm giúp dễ dàng lắp đặt trên laptop và PC desktop, đồng thời cấu trúc không có bộ phận cơ học giúp ổ hoạt động êm ái, chống rung sốc tốt và tiết kiệm điện năng hơn. &nbsp; &nbsp; &nbsp; Ngoài ra, SSD Biostar S160 còn được trang bị controller MaxIO 1102 cho khả năng xử lý dữ liệu ổn định, hỗ trợ nhiều hệ điều hành như Windows, Linux và MacOS. Đây là lựa chọn phù hợp cho người dùng muốn nâng cấp hiệu năng máy tính với mức chi phí hợp ', '{"Thương hiệu":"Biostar","Model":"S160-256GB","Mã sản phẩm":"S160-256GB","Loại thiết bị":"Ổ cứng thể rắn SSD gắn trong","Đối tượng sử dụng":"Người dùng phổ thông","Chuẩn kích thước":"2.5 inch","Dung lượng":"256GB","Loại bộ nhớ":"3D TLC"}', 0, 1);
