INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1075758753', 'SP1083939', '1075758753', 'https://www.maytinhbienhoa.vn/products/ssd-movespeed-256gb-jqb256gb-sata', 'SSD MOVESPEED 256GB JQB256GB SATA', 'ssd-movespeed-256gb-jqb256gb-sata', 'brand_movespeed_680', 'cat_ssd-hdd', 990000, 990000, 0, 792000, 24, 'in_stock', 'SSD MOVESPEED 256GB JQB256GB SATA', 'SSD SATA MOVESPEED JQB 256GB Dung lượng: 256GB Chuẩn giao tiếp: SATA III 6Gb/s Chuẩn kích thước: 2.5 inch Độ dày: 7mm Loại bộ nhớ: 3D NAND Flash (TLC) Tốc độ đọc tuần tự: Lên đến 550 MB/s Tốc độ ghi tuần tự: Lên đến 480 MB/s Bảo hành: 5 năm Ưu điểm Tăng tốc khởi động Windows và ứng dụng nhanh hơn HDD truyền thống. Tiêu thụ điện năng thấp, hoạt động êm, không gây tiếng ồn. Tương thích với hầu hết PC và laptop sử dụng chuẩn SATA 2.5 inch. Phù hợp để nâng cấp các máy văn phòng, học tập, giải trí và chơi game ở mức phổ thông. Mô tả SSD SATA MOVESPEED JQB 256GB là ổ cứng thể rắn chuẩn SATA III 6Gb/s với tốc độ đọc lên đến 550MB/s , giúp tăng tốc khởi động hệ điều hành, mở ứng dụng và sao chép dữ liệu nhanh hơn nhiều so với ổ cứng HDD truyền thống. Sử dụng bộ nhớ 3D NAND Flash , thiết kế chuẩn 2.5 inch, dày 7mm , tương thích với đa số máy tính để bàn và laptop. Đây là lựa chọn phù hợp để nâng cấp hiệu năng với chi phí hợp lý.', '{"Dung lượng":"256GB","Chuẩn giao tiếp":"SATA III 6Gb/s","Chuẩn kích thước":"2.5 inch","Độ dày":"7mm","Loại bộ nhớ":"3D NAND Flash (TLC)","Tốc độ đọc tuần tự":"Lên đến 550 MB/s","Tốc độ ghi tuần tự":"Lên đến 480 MB/s","Bảo hành":"5 năm"}', 0, 1);
