INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1053901194', 'SP109726', '1053901194', 'https://www.maytinhbienhoa.vn/products/ssd-agi-256gb-ai238-nvme-m-2-gen-3x4', 'SSD AGI 256GB AI198 NVME M.2 Gen 3x4', 'ssd-agi-256gb-ai238-nvme-m-2-gen-3x4', 'brand_agi_209', 'cat_ssd-hdd', 1290000, 1290000, 0, 1032000, 24, 'in_stock', 'SSD AGI 256GB AI198 NVME M.2 Gen 3x4', 'THÔNG SỐ KỸ THUẬT ĐẶC TRƯNG &nbsp; DUNG LƯỢNG:&nbsp;256GB/512GB/1TB NAND Flash:&nbsp;3D TLC QUY CÁCH:&nbsp;M.2 2280 GIAO TIẾP:&nbsp;PCIe Gen 3x4 KÍCH THƯỚC (L x W x H):&nbsp;80 x 22 x 3.5mm TỐC ĐỘ ĐỌC / GHI (TỐI ĐA)&nbsp;: 2050 / 1650 MB/s, *Tốc độ đọc ghi có thể thay đổi tùy thuộc theo cấu hình hiệu năng hoặc phần mềm. CHÔNG SỐC:&nbsp;1500G/0.5ms NHIỆT ĐỘ HOẠT ĐỘNG:&nbsp;0°C-70°C NHIỆT ĐỘ MÔI TRƯỜNG:&nbsp;-40°C-85°C TẦN SUẤT GHI:&nbsp;600TB(1TB) TUỔI THỌ CHIP NHỚ:&nbsp;1,600,000 hours CÁC CHỨNG NHẬN TIÊU CHUẨN:&nbsp;CE, FCC, BSMI, VCCI, RoHS &nbsp; Ổ Cứng SSD NVMe AGI AI198 256GB Gen 3x4 Mới BH 36T Bạn đang tìm kiếm một giải pháp lưu trữ hiệu suất cao và tiết kiệm thời gian cho hệ thống máy tính của mình? Ổ cứng SSD NVMe AGI 256GB sẽ là sự lựa chọn hoàn hảo để nâng cấp máy tính của bạn lên một tầm cao mới. Với tốc độ truy xuất dữ liệu nhanh chóng, độ ổn định cao và khả năng tương thích linh hoạt, sản phẩm này sẽ mang lại trải nghiệm làm việc và giải trí vượt trội. 1. Tăng Hiệu Suất Vượt Trội Với giao diện NVMe (Non-Volatile Memory Express) tiên tiến, ổ cứng SSD AGI 256GB NVMe cung cấp tốc độ đọc/ghi dữ liệu nhanh chóng hơn nhiều lần so với các ổ cứng SSD truyền thống. Điều này giúp bạn khởi động hệ thống, mở ứng dụng và truy cập dữ liệu một cách nhanh chóng và mượt mà hơn bao giờ hết.&nbsp; 2. Độ Bền và Ổn Định AGI 256GB SSD NVMe không chỉ mang lại hiệu suất vượt trội mà còn đảm bảo độ bền và ổn định trong quá trình sử dụng. Với công nghệ NVMe và các linh kiện chất lượng cao', '{"Model":"SSD AGI 256GB AI198 NVME M.2 Gen 3x4"}', 0, 1);
