INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1075603331', 'SP1083893', '1075603331', 'https://www.maytinhbienhoa.vn/products/ssd-dahua-256gb-c900vn-m-2-nvme-pcie-gen-3-0-x4', 'SSD DAHUA 256GB C900VN M.2 NVMe PCIe Gen 3.0 x4', 'ssd-dahua-256gb-c900vn-m-2-nvme-pcie-gen-3-0-x4', 'brand_dahua_355', 'cat_ssd-hdd', 1290000, 1290000, 0, 1032000, 24, 'in_stock', 'SSD DAHUA 256GB C900VN M.2 NVMe PCIe Gen 3.0 x4', 'THÔNG SỐ CHI TIẾT Dung lượng 256GB Chuẩn kết nối M.2 Kích thước 2280 (22 × 80 mm) Giao tiếp PCIe 3.0 x4, NVMe 1.3 Tốc độ ghi Lên đến 1.450 MB/s Tốc độ đọc Lên đến 3.000 MB/s MTBF (Thời gian trung bình giữa hai lần hỏng) 1.500.000 giờ TBW (Tổng dung lượng dữ liệu ghi) ≤ 128TB Công nghệ - Bộ nhớ NAND Flash 3D TLC- Hỗ trợ S.M.A.R.T- Công nghệ sửa lỗi LDPC ECC- Hỗ trợ lệnh TRIM- Garbage Collection (Thu gom dữ liệu rác) Trọng lượng 0,016 kg (16g) Kích thước sản phẩm 80 × 23 × 5 mm Thương hiệu / Nhà sản xuất DAHUA Bảo hành 3 năm (bảo hành giới hạn theo chỉ số TBW) &nbsp; &nbsp; &nbsp; &nbsp; SSD DAHUA 256GB M.2 PCIe Gen3 x4 NVMe là giải pháp lưu trữ tốc độ cao dành cho máy tính để bàn, laptop và mini PC, giúp nâng cao hiệu suất hệ thống, rút ngắn thời gian khởi động Windows, mở ứng dụng và truyền tải dữ liệu. Với chuẩn giao tiếp PCIe 3.0 x4 NVMe 1.3 , ổ cứng mang lại tốc độ đọc tuần tự lên đến 3.000 MB/s và tốc độ ghi lên đến 1.450 MB/s , nhanh hơn nhiều lần so với SSD SATA truyền thống. Sản phẩm sử dụng bộ nhớ NAND Flash 3D TLC có độ bền cao, cho khả năng lưu trữ ổn định và tuổi thọ dài hơn so với nhiều dòng SSD phổ thông. Đồng thời, ổ cứng được tích hợp các công nghệ hiện đại như S.M.A.R.T giúp theo dõi tình trạng hoạt động của ổ đĩa, LDPC ECC tăng cường khả năng sửa lỗi dữ liệu, TRIM tối ưu hiệu suất sau thời gian dài sử dụng và Garbage Collection giúp quản lý bộ nhớ hiệu quả, duy trì tốc độ đọc/ghi ổn định. &nbsp; &nbsp; &nbsp; Với chuẩn M.2 2280 , SSD DAHUA 256GB tương thích v', '{"Dung lượng":"256GB","Chuẩn kết nối":"M.2","Kích thước":"2280 (22 × 80 mm)","Giao tiếp":"PCIe 3.0 x4, NVMe 1.3","Tốc độ ghi":"Lên đến 1.450 MB/s","Tốc độ đọc":"Lên đến 3.000 MB/s","MTBF (Thời gian trung bình giữa hai lần hỏng)":"1.500.000 giờ","TBW (Tổng dung lượng dữ liệu ghi)":"≤ 128TB","Công nghệ":"- Bộ nhớ NAND Flash 3D TLC- Hỗ trợ S.M.A.R.T- Công nghệ sửa lỗi LDPC ECC- Hỗ trợ lệnh TRIM- Garbage Collection (Thu gom dữ liệu rác)","Trọng lượng":"0,016 kg (16g)","Kích thước sản phẩm":"80 × 23 × 5 mm","Thương hiệu / Nhà sản xuất":"DAHUA"}', 0, 1);
