INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1077071106', 'SP1084209', '1077071106', 'https://www.maytinhbienhoa.vn/products/ssd-huadisk-256g-hyv256x3-hxy-pcie-gen3-0-x4-nvme-1-3-m-2-2280-doc-3400mb-s', 'SSD HUADISK 256G HYV256X3 (HXY) PCIe Gen3.0 x4 NVMe 1.3, M.2 2280 (Đọc 3400Mb/s)', 'ssd-huadisk-256g-hyv256x3-hxy-pcie-gen3-0-x4-nvme-1-3-m-2-2280-doc-3400mb-s', 'brand_huadisk_521', 'cat_ssd-hdd', 1290000, 1290000, 0, 1032000, 24, 'in_stock', 'SSD HUADISK 256G HYV256X3 (HXY) PCIe Gen3.0 x4 NVMe 1.3, M.2 2280 (Đọc 3400Mb/s)', 'THÔNG SỐ KỸ THUẬT &nbsp; Dung Lượng 256GB Kích Thước M.2 NVMe 2280 Tốc Độ Đọc 3400 MB/s Tốc Độ Ghi 2900 MB/s Giao Tiếp PCIe Gen3.0 x4, NVMe 1.3 &nbsp; SSD HUADISK HYVXXX (HXY) – SSD NVMe PCIe Gen 3 hiệu năng cao HUADISK HYVXXX (HXY) là dòng ổ cứng SSD NVMe PCIe Gen 3 hiệu năng cao, cung cấp tốc độ đọc lên đến 3.400 MB/s và tốc độ ghi lên đến 2.900 MB/s , được thiết kế dành cho các hệ thống máy tính yêu cầu tốc độ xử lý dữ liệu nhanh, các nhà lắp ráp PC chuyên nghiệp và thương hiệu máy tính theo yêu cầu. Thông số và đặc điểm nổi bật Giao tiếp: NVMe PCIe Gen 3 Tốc độ đọc tối đa: 3.400 MB/s Tốc độ ghi tối đa: 2.900 MB/s Kích thước: M.2 2280 Dung lượng: Từ 128 GB đến 2 TB Khả năng ứng dụng: Laptop, máy tính để bàn phục vụ công việc sáng tạo và các cấu hình PC gaming cao cấp. &nbsp; HUADISK HYVXXX (HXY) mang đến giải pháp thuận tiện cho các doanh nghiệp muốn phát triển dòng SSD hiệu năng cao mang thương hiệu riêng mà không cần đặt hàng với số lượng tối thiểu quá lớn. HUADISK HYVXXX (HXY) – Hiệu năng Gen 3 mạnh mẽ, linh hoạt tùy biến thương hiệu, tối ưu cho kinh doanh và lắp ráp PC chuyên nghiệp.', '{"Dung Lượng":"256GB","Kích Thước":"M.2 NVMe 2280","Tốc Độ Đọc":"3400 MB/s","Tốc Độ Ghi":"2900 MB/s","Giao Tiếp":"PCIe Gen3.0 x4, NVMe 1.3"}', 0, 1);
