INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1076152153', 'SP1084051', '1076152153', 'https://www.maytinhbienhoa.vn/products/ssd-biostar-512gb-s160-sata-iii-2-5inch', 'SSD Biostar 512GB S160 Sata III 2.5inch', 'ssd-biostar-512gb-s160-sata-iii-2-5inch', 'brand_biostar_532', 'cat_ssd-hdd', 1790000, 1790000, 0, 1432000, 24, 'in_stock', 'SSD Biostar 512GB S160 Sata III 2.5inch', 'SSD Biostar 512GB S160 SATA III 2.5 inch là ổ cứng thể rắn chuẩn 2.5 inch phổ thông, tốc độ đọc tối đa khoảng 550 MB/s và ghi khoảng 510 MB/s . Thiết bị giúp tăng tốc độ khởi động máy và chạy ứng dụng cho laptop hoặc máy tính bàn cũ có hỗ trợ cổng SATA III. Thông số kỹ thuật Dung lượng: 512GB Kích thước: 2.5 inch (dày 7.0mm) Giao tiếp: SATA III 6Gb/s Tốc độ đọc tối đa: Lên tới 550 MB/s Tốc độ ghi tối đa: Lên tới 510 MB/s Loại chip nhớ: 3D TLC NAND Đặc điểm nổi bật Tiết kiệm điện: Hoạt động êm ái, ít tiêu thụ điện năng. Chống sốc tốt: Thiết kế bền bỉ hơn ổ cứng cơ HDD truyền thống. Tương thích cao: Dùng tốt với các hệ điều hành phổ biến như Windows, Linux và Mac.', '{"Dung lượng":"512GB","Kích thước":"2.5 inch (dày 7.0mm)","Giao tiếp":"SATA III 6Gb/s","Tốc độ đọc tối đa":"Lên tới 550 MB/s","Tốc độ ghi tối đa":"Lên tới 510 MB/s","Loại chip nhớ":"3D TLC NAND","Tiết kiệm điện":"Hoạt động êm ái, ít tiêu thụ điện năng.","Chống sốc tốt":"Thiết kế bền bỉ hơn ổ cứng cơ HDD truyền thống."}', 0, 1);
