INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1076362420', 'SP1084102', '1076362420', 'https://www.maytinhbienhoa.vn/products/ssd-ocpc-512gb-mfl-300-m-2-nvme-gen-3x4-doc-3100mb-s', 'SSD OCPC 512GB MFL-300 M.2 NVMe Gen 3x4 (Đọc: 3100Mb/s)', 'ssd-ocpc-512gb-mfl-300-m-2-nvme-gen-3x4-doc-3100mb-s', 'brand_ocpc_293', 'cat_ssd-hdd', 2090000, 2090000, 0, 1672000, 24, 'in_stock', 'SSD OCPC 512GB MFL-300 M.2 NVMe Gen 3x4 (Đọc: 3100Mb/s)', '&nbsp; Thông số kỹ thuật &nbsp; Thông tin chung Thương hiệu OCPC Bảo hành 60 tháng (5 năm) Tình trạng Mới Ngành hàng Ổ cứng SSD Xuất xứ Mỹ Thông số kỹ thuật Độ bền (TBW) 300 TB Form factor M.2 2280 DRAM Không có DRAM Cache Tốc độ đọc ngẫu nhiên 350-000 IOPS Loại SSD M2 NVMe NAND TLC Dung lượng 512 GB Tốc độ ghi ngẫu nhiên 250-000 IOPS Tốc độ đọc tuần tự 3100 MB/s Tốc độ ghi tuần tự 2100 MB/s Chuẩn kết nối PCIe Gen 3.0 x4 NVMe &nbsp; &nbsp; &nbsp; SSD OCPC NVME 512G Gen 3x4 – Hiệu suất vượt trội, tốc độ đỉnh cao Bạn đang tìm kiếm một ổ cứng SSD tốc độ cao, ổn định và bền bỉ để nâng cấp hệ thống?&nbsp; SSD OCPC NVME 512G Gen 3x4 (MFL-300 512GB) &nbsp;là lựa chọn hoàn hảo dành cho bạn. Với tốc độ đọc lên đến&nbsp; 3100 MB/s &nbsp;và tốc độ ghi&nbsp; 2100 MB/s , sản phẩm này đảm bảo hiệu năng mạnh mẽ cho mọi nhu cầu từ làm việc, chơi game đến xử lý dữ liệu chuyên sâu. SSD OCPC NVME 512G Gen 3x4 – Giải pháp lưu trữ tốc độ cao Hiệu năng mạnh mẽ, tối ưu hóa tốc độ xử lý Với giao diện&nbsp; NVMe PCIe Gen3x4 , SSD OCPC MFL-300 512GB mang đến tốc độ truyền tải dữ liệu cực nhanh, giúp bạn giảm đáng kể thời gian tải ứng dụng, sao chép file và khởi động hệ thống. Công nghệ tiên tiến, đảm bảo độ bền cao SSD này được trang bị các công nghệ hiện đại như&nbsp; TRIM, ECC, SMART , giúp nâng cao tuổi thọ ổ cứng, bảo vệ dữ liệu an toàn và duy trì hiệu suất ổn định trong thời gian dài. Dung lượng lưu trữ tối ưu Với&nbsp; 512GB dung lượng , sản phẩm này cung cấp không gian lưu trữ rộng rãi cho hệ đ', '{"Thương hiệu":"OCPC","Bảo hành":"60 tháng (5 năm)","Tình trạng":"Mới","Ngành hàng":"Ổ cứng SSD","Xuất xứ":"Mỹ","Độ bền (TBW)":"300 TB","Form factor":"M.2 2280","DRAM":"Không có DRAM Cache","Tốc độ đọc ngẫu nhiên":"350-000 IOPS","Loại SSD":"M2 NVMe","NAND":"TLC","Dung lượng":"512 GB"}', 0, 1);
