INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1027491069', 'SP008878', '1027491069', 'https://www.maytinhbienhoa.vn/products/hdd-seagate-500gb-renew-bh-24th', 'HDD SEAGATE/WD 500GB RENEW BH 24TH', 'hdd-seagate-500gb-renew-bh-24th', 'brand_wd_155', 'cat_ssd-hdd', 650000, 599000, 0, 520000, 24, 'in_stock', 'HDD SEAGATE/WD 500GB RENEW BH 24TH', 'Seagate Technology &nbsp; là nhà cung cấp các giải pháp lưu trữ hàng đầu thế giới, đươc thành lập năm 1979 và có trụ sở tại California, Mỹ. Seagate sở hữu các thương hiệu ổ cứng quen thuộc: Seagate, LaCie, Maxtor Seagate cung cấp dải sản phẩm từ ổ cứng gắn trong đến ổ cứng gắn ngoài và cả ổ cứng cho hệ thống lưu trữ máy chủ. Các dòng sản phẩm ổ cứng gắn trong của Seagate bao gồm: Ổ cứng gắn trong HDD : Seagate BarraCuda, Seagate FireCuda, Seagate IronWolf, Seagate SkyHawk. Với các dung lượng từ 1TB đến 16TB (tuỳ theo dòng sản phẩm). Ổ cứng gắn trong SSD : Seagate BarraCuda SSD, Seagate FireCuda SSD, Seagate IronWolf SSD. Với các dung lượng từ 250GB đến 2TB (tuỳ theo dòng sản phẩm). Ổ cứng dành cho doanh nghiệp : Seagate Exos Enterprise, Seagate Nytro Enterprise, Seagate Nytro Enterprise SSD. Với các dung lượng từ 240GB đến 16TB (tuỳ theo dòng sản phẩm). Giới thiệu ổ cứng &nbsp; Seagate BarraCuda HDD : Tính năng nổi bật của sản phẩm &nbsp; Máy tính tại nhà và văn phòng: linh hoạt và đáng tin cậy cho hệ thống máy tính để bàn và máy tính xách tay Máy tính tại nhà và văn phòng với yêu cầu dung lượng cao hơn, vận hành tốt hơn và bảo hành dài hơn Hệ thống game, chỉnh sửa video, yêu cầu điện toán cao: nhanh hơn ổ cứng HDD tiêu chuẩn 5 lần, dung lượng cao hơn ổ cứng SSD Dung lượng Lên tới 4TB Lên tới 10TB Lên tới 2TB Hoạt động Nhanh Nhanh hơn Nhanh nhất Tính năng chính Linh hoạt Tối đa dung lượng và tốc độ cao hơn Tăng cường hiệu suất Flash để đạt hiệu suất cao hơn Dạng sản xuất 3.5 ', '{"&nbsp;":"Máy tính tại nhà và văn phòng: linh hoạt và đáng tin cậy cho hệ thống máy tính để bàn và máy tính xách tay","Dung lượng":"Lên tới 4TB","Hoạt động":"Nhanh","Tính năng chính":"Linh hoạt","Dạng sản xuất":"3.5 inch máy tính để bàn"}', 0, 1);
