INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1071665187', 'SP1082971', '1071665187', 'https://www.maytinhbienhoa.vn/products/vga-arktek-rx-550-4gb-2-fan', 'VGA ARKTEK RX 550 4GB 1 FAN', 'vga-arktek-rx-550-4gb-2-fan', 'brand_arktek_450', 'cat_vga', 2290000, 2290000, 0, 1832000, 24, 'in_stock', 'VGA ARKTEK RX 550 4GB 1 FAN', 'Thông số kỹ thuật Bộ xử lý đồ họa (GPU): Tên: AMD Radeon RX 550 Kiến trúc: Polaris 12 Số nhân xử lý (Stream Processors): 640 Tốc độ xử lý: 1287MHz Bộ nhớ: Dung lượng: 4GB GDDR5 Bus: 128-bit Tốc độ: 7000MHz Hỗ trợ: Khe cắm: PCI Express 3.0 DirectX: 12 OpenGL: 4.5 Cổng xuất hình: 1 x HDMI 1 x DVI (Dual Link) 1 x DisplayPort Độ phân giải tối đa: DisplayPort: 3840 x 2160@120Hz DVI: 2560 x 1600@60Hz HDMI: 3840 x 2160@60Hz API: &nbsp;DirectX 12, Shader Model 5.0 Nguồn điện: Khuyến nghị: 400W Công suất tiêu thụ: 35W Hệ điều hành hỗ trợ:&nbsp; Windows 10, 8, 7 Phụ kiện: &nbsp;1 x Đĩa CD driver, 1 x Sách hướng dẫn sử dụng &nbsp; &nbsp; Thiết kế đơn giản, phù hợp mọi loại máy Card màn hình VGA ARK RX550 4GB &nbsp;có thiết kế đơn giản, nhỏ gọn, dễ lắp vào máy tính. Thân card được làm bằng chất liệu nhựa, nhẹ nhàng, không gây khó khăn trong quá trình lắp đặt. Thiết kế không quá yêu cầu về mặt thẩm mỹ, phù hợp với những người dùng quan tâm đến hiệu năng và khả năng sử dụng hơn là vẻ ngoài bắt mắt. Vì vậy, đối với cấp&nbsp;độ màn hình&nbsp;cao của card, thiết kế này tối ưu về chi phí sản xuất, mang lại giá thành hợp lý cho người dùng tiêu điểm. Hiệu suất ổn định, xử lý đồ họa tốt Card màn hình VGA ARK RX550 4GB &nbsp;sở hữu khả năng xử lý đồ họa tốt cho những tựa game yêu cầu mức độ trung bình. Với Bộ xử lý luồng 640 và RAM 4GB GDDR5, card&nbsp;màn hình này có thể đáp ứng nhu cầu chơi game ở độ phân giải Full HD. Tuy nhiên, khả năng chơi game ở các tựa game hiện đại hay có đồ họa cao sẽ kh', '{"Tên":"AMD Radeon RX 550","Kiến trúc":"Polaris 12","Số nhân xử lý (Stream Processors)":"640","Tốc độ xử lý":"1287MHz","Dung lượng":"4GB GDDR5","Bus":"128-bit","Tốc độ":"7000MHz","Khe cắm":"PCI Express 3.0"}', 0, 1);
