INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1075590194', 'SP1083890', '1075590194', 'https://www.maytinhbienhoa.vn/products/vga-biostar-rx-580-8gb-gddr5-bh-36-thang', 'VGA BIOSTAR RX 580 8GB GDDR5 BH 36 THÁNG', 'vga-biostar-rx-580-8gb-gddr5-bh-36-thang', 'brand_biostar_532', 'cat_vga', 3290000, 3290000, 0, 2632000, 24, 'in_stock', 'VGA BIOSTAR RX 580 8GB GDDR5 BH 36 THÁNG', 'THÔNG SỐ KỸ THUẬT &nbsp; GPU Radeon RX580 2048SP Memory Clock 7 Gbps Engine Clock 1284 MHz Memory Type GDDR5 Memory Size 8 GB Memory Bus 256-bit Interface Support PCI-E 3.0 Output 1 x DVI 3 x Display Port 1.4a 1 x HDMI® 2.0b Accessories 1 x Quick Guide OS Support Windows 7 - 32-Bit Edition Windows 7 - 64-Bit Edition Ubuntu x86 64-Bit Linux x86_64 Windows 10 - 64-Bit Edition &nbsp; &nbsp; &nbsp; VGA BIOSTAR Radeon RX 580 8GB GDDR5 – Card đồ họa chiến game Full HD mạnh mẽ BIOSTAR Radeon RX 580 8GB GDDR5 là card đồ họa tầm trung sở hữu hiệu năng mạnh mẽ, phù hợp cho game thủ, người làm đồ họa và dựng video cơ bản. Được trang bị 8GB bộ nhớ GDDR5 cùng kiến trúc AMD Polaris , RX 580 mang đến khả năng xử lý đồ họa ổn định, đáp ứng tốt nhu cầu chơi game ở độ phân giải Full HD, chỉnh sửa hình ảnh, dựng video và làm việc với các phần mềm thiết kế phổ biến. Card sử dụng 2304 Stream Processors , giao tiếp bộ nhớ 256-bit và xung nhịp GPU cao, mang lại băng thông lớn, giúp xử lý mượt mà các tựa game eSports như Liên Minh Huyền Thoại, Valorant, CS2, Dota 2 cũng như nhiều tựa game AAA ở mức thiết lập đồ họa Medium đến High. Dung lượng VRAM 8GB GDDR5 giúp tối ưu hiệu suất khi chơi game, làm việc với texture độ phân giải cao và chạy nhiều ứng dụng đồ họa cùng lúc. BIOSTAR RX 580 được trang bị hệ thống tản nhiệt với 2 quạt làm mát , giúp duy trì nhiệt độ ổn định trong quá trình hoạt động liên tục. Thiết kế chắc chắn, vận hành bền bỉ và tương thích với hầu hết các bo mạch chủ hỗ trợ chuẩn PCI Ex', '{"GPU":"Radeon RX580 2048SP","Memory Clock":"7 Gbps","Engine Clock":"1284 MHz","Memory Type":"GDDR5","Memory Size":"8 GB","Memory Bus":"256-bit","Interface":"Support PCI-E 3.0","Output":"1 x DVI 3 x Display Port 1.4a 1 x HDMI® 2.0b","Accessories":"1 x Quick Guide","OS Support":"Windows 7 - 32-Bit Edition Windows 7 - 64-Bit Edition Ubuntu x86 64-Bit Linux x86_64 Windows 10 - 64-Bit Edition"}', 0, 1);
