INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1054198233', 'SP1079927', '1054198233', 'https://www.maytinhbienhoa.vn/products/vga-asus-rtx-3050-dual-edition-6gb-gddr6', 'VGA ASUS RTX 3050 DUAL Edition 6GB GDDR6', 'vga-asus-rtx-3050-dual-edition-6gb-gddr6', 'brand_asus_316', 'cat_vga', 5650000, 5650000, 0, 4520000, 24, 'in_stock', 'VGA ASUS RTX 3050 DUAL Edition 6GB GDDR6', 'Thông số kỹ thuật &nbsp; THƯƠNG HIỆU Asus BẢO HÀNH 36 tháng GPU GeForce RTX 3050 XUNG NHÂN OC mode : 1537 MHz (Boost Clock) Default mode : 1507 MHz (Boost Clock) QUẠT TẢN NHIỆT 2 Fan CHUẨN BUS PCI Express 4.0 CUDA CORE 2304 ĐẦU CẤP NGUỒN Đang cập nhật BỘ NHỚ 6GB THẾ HỆ BỘ NHỚ GDDR6 TỐC ĐỘ BỘ NHỚ 14 Gbps GIAO DIỆN BỘ NHỚ 96-bit CỔNG KẾT NỐI 1 x HDMI 2.1, 1 x DisplayPort 1.4a, 1 x DVI-D HỖ TRỢ HIỂN THỊ TỐI ĐA 3 NGUỒN ĐỀ XUẤT 550W KÍCH THƯỚC 201 x 120 x 37 mm &nbsp; ĐẶC ĐIỂM NỔI BẬT Card màn hình ASUS Dual GeForce RTX 3050 OC Edition 6GB GDDR6 Bộ xử lý đa luồng phát trực tuyến NVIDIA Ampere: &nbsp;Ampere SM hoàn toàn mới mang lại thông lượng FP32 gấp 2 lần và cải thiện hiệu quả sử dụng năng lượng. Lõi RT thế hệ 2: &nbsp;Trải nghiệm thông lượng gấp 2 lần so với Lõi RT thế hệ 1, cộng với RT và đổ bóng đồng thời để đạt được hiệu suất dò tia ở cấp độ hoàn toàn mới. Lõi Tensor thế hệ thứ 3: &nbsp;Tăng thông lượng lên gấp 2 lần nhờ độ thưa thớt về cấu trúc và các thuật toán AI tiên tiến như DLSS.&nbsp;Những lõi này giúp tăng đáng kể hiệu suất trò chơi và các khả năng AI hoàn toàn mới. Phiên bản OC: Xung Boost 1537&nbsp; MHz (Chế độ OC)/&nbsp; 1507 MHz (Chế độ mặc định) Khả năng chống bụi IP5X &nbsp;giúp bảo vệ khỏi sự xâm nhập của các hạt để có độ bền tốt hơn. Thiết&nbsp; kế 2 khe cắm &nbsp;tối đa hóa khả năng tương thích và hiệu quả làm mát để mang lại hiệu năng vượt trội trong khung máy nhỏ. Giá&nbsp; đỡ bằng thép không gỉ &nbsp;cứng hơn và có khả năng chống ăn mòn cao hơn. Công ', '{"2304":"Đang cập nhật","Asus":"36 tháng","GeForce RTX 3050":"OC mode : 1537 MHz (Boost Clock) Default mode : 1507 MHz (Boost Clock)","2 Fan":"PCI Express 4.0","6GB":"GDDR6","14 Gbps":"96-bit","1 x HDMI 2.1, 1 x DisplayPort 1.4a, 1 x DVI-D":"3","550W":"201 x 120 x 37 mm"}', 0, 1);
