INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1053287916', 'SP109579', '1053287916', 'https://www.maytinhbienhoa.vn/products/vga-asus-rtx-3050-dual-oc-edition-6gb-gddr6', 'VGA ASUS RTX 3050 DUAL OC Edition 6GB GDDR6', 'vga-asus-rtx-3050-dual-oc-edition-6gb-gddr6', 'brand_asus_316', 'cat_vga', 5690000, 5690000, 0, 4552000, 24, 'in_stock', 'VGA ASUS RTX 3050 DUAL OC Edition 6GB GDDR6', 'Thông số kỹ thuật: Nhân đồ họa&nbsp; NVIDIA® GeForce RTX™ 3050 Bus tiêu chuẩn PCI Express 4.0 Bộ nhớ 6GB GDDR6 Xung nhịp OC mode: 1537 MHz(Boost Clock) Default mode: 1507 MHz(Boost Clock) Nhân CUDA 2304 Tốc độ bộ nhớ 14 Gbps Giao thức bộ nhớ 96-bit Độ phân giải Độ phân giải tối đa 7680 x 4320 Giao thức Có x 1 Native DVI-D Có x 1&nbsp;Native HDMI 2.1 Có x 1&nbsp;Native DisplayPort 1.4a &nbsp;HDCP Support Yes (2.3) Số lượng màn hình tối đa hỗ trợ 3 Hỗ trợ NVlink/ Crossfire&nbsp; Không Kích thước 201 x 120 x 37 mm 7.91 x 4.72 x 1.46 inches PSU&nbsp;kiến nghị 550W Kết nối nguồn Không Khe cắm 2 &nbsp; RTX 3050 OC tăng cường tản nhiệt với 2 quạt Với kiến trúc NVIDI Ampere mới nhất, Asus Dual GeForce RTX 3050 OC kết hợp hiệu suất nhiệt tối ưu với khả năng tương thích cao. Các giải pháp làm mát tiên tiến từ các card đồ họa hàng đầu — bao gồm hai quạt công nghệ hướng trục Axial để tối đa hóa luồng khí đến tản nhiệt — được tích hợp trong một card kích thước 2 khe dài 20 cm, cung cấp nhiều luồng khí trong không gian nhỏ hơn. Những cải tiến này khiến Asus Dual trở thành sự lựa chọn hoàn hảo cho những game thủ muốn có hiệu suất đồ họa mạnh trong một cấu hình nhỏ gọn. &nbsp; Thiết kế quạt tốt hơn, nhanh hơn và mạnh hơn Card màn hình với hai quạt công nghệ Axial đã được thử nghiệm và với thiết kế thống nhất giữa các cánh quạt dài cùng vòng kết nối giữa các cánh giúp tăng áp suất không khí đi xuống card. Công nghệ Auto-Extreme Sản xuất tự động chính xác RTX 3050 OC được trang bị công nghệ Au', '{"Nhân đồ họa&nbsp;":"NVIDIA® GeForce RTX™ 3050","Bus tiêu chuẩn":"PCI Express 4.0","Bộ nhớ":"6GB GDDR6","Xung nhịp":"OC mode: 1537 MHz(Boost Clock) Default mode: 1507 MHz(Boost Clock)","Nhân CUDA":"2304","Tốc độ bộ nhớ":"14 Gbps","Giao thức bộ nhớ":"96-bit","Độ phân giải":"Độ phân giải tối đa 7680 x 4320","Giao thức":"Có x 1 Native DVI-D Có x 1&nbsp;Native HDMI 2.1 Có x 1&nbsp;Native DisplayPort 1.4a &nbsp;HDCP Support Yes (2.3)","Số lượng màn hình tối đa hỗ trợ":"3","Hỗ trợ NVlink/ Crossfire&nbsp;":"Không","Kích thước":"201 x 120 x 37 mm 7.91 x 4.72 x 1.46 inches"}', 0, 1);
