INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1066979820', 'SP1081893', '1066979820', 'https://www.maytinhbienhoa.vn/products/vga-giga-rtx-3060-12g-windforce-oc', 'VGA Gigabyte RTX 3060 12G WINDFORCE OC', 'vga-giga-rtx-3060-12g-windforce-oc', 'brand_gigabyte_588', 'cat_vga', 10290000, 10290000, 0, 8232000, 24, 'in_stock', 'VGA Gigabyte RTX 3060 12G WINDFORCE OC', 'THÔNG SỐ KỸ THUẬT &nbsp; Sản phẩm Card đồ họa VGA Hãng sản xuất GIGABYTE Engine đồ họa GeForce RTX™ 3060 Bộ nhớ 1‎2GB&nbsp;GDDR6 Engine Clock 1792 MHz (Reference Card: 1777 MHz) Lõi CUDA 3‎584 Clock bộ nhớ 1‎5000 MHz Giao diện bộ nhớ 1‎92 bit Độ phân giải 7‎680x4320 Card Bus PCI-E 4.0 x 16 Kết nối DisplayPort 1.4a *2 HDMI 2.1 *2 Kích thước L=198 W=121 H=39 mm PSU đề nghị 5‎50W Power Connectors 8‎ pin*1 &nbsp; VGA Gigabyte GeForce RTX 3060 WINDFORCE OC 12GB (N3060WF2OC -12GD)&nbsp; Sản phẩm&nbsp; VGA Gigabyte GeForce RTX 3060 WINDFORCE OC 12GB &nbsp;là một lựa chọn xuất sắc cho các game thủ và những người đam mê công nghệ. Với dung lượng bộ nhớ lớn lên đến 12GB GDDR6, core clock mạnh mẽ lên tới&nbsp; 1777 MHz , và băng thông 192-bit,&nbsp; card đồ họa &nbsp;này hứa hẹn mang đến trải nghiệm gaming tuyệt vời cùng với hiệu năng ấn tượng. &nbsp; Thiết kế ấn tượng VGA Gigabyte GeForce RTX 3060 WINDFORCE OC 12GB có thiết kế đẹp mắt với hệ thống tản nhiệt WINDFORCE 3X, bao gồm ba quạt làm mát với các lá láng nhôm đồng để giảm nhiệt độ và đảm bảo hoạt động yên tĩnh. Kích thước của sản phẩm là vừa vặn với nhiều case máy tính, giúp bạn dễ dàng lắp đặt vào hệ thống của mình mà không cần lo lắng về không gian. &nbsp; Tăng tốc FPS và Chất lượng tối ưu NVIDIA DLSS sử dụng trí tuệ nhân tạo (AI) để tăng tốc độ khung hình lên ít nhất 1,5 lần mà vẫn duy trì chất lượng hình ảnh xuất sắc. Với sức mạnh của Nhân Tensor xử lý AI chuyên dụng trên GeForce RTX, bạn có thể tận hưởng hiệu suất vượt trội ', '{"Sản phẩm":"Card đồ họa VGA","Hãng sản xuất":"GIGABYTE","Engine đồ họa":"GeForce RTX™ 3060","Bộ nhớ":"1‎2GB&nbsp;GDDR6","Engine Clock":"1792 MHz (Reference Card: 1777 MHz)","Lõi CUDA":"3‎584","Clock bộ nhớ":"1‎5000 MHz","Giao diện bộ nhớ":"1‎92 bit","Độ phân giải":"7‎680x4320","Card Bus":"PCI-E 4.0 x 16","Kết nối":"DisplayPort 1.4a *2 HDMI 2.1 *2","Kích thước":"L=198 W=121 H=39 mm"}', 0, 1);
