INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1037724570', 'SP105676', '1037724570', 'https://www.maytinhbienhoa.vn/products/vga-msi-rtx-3060-ventus-2x-oc-12-gb', 'VGA MSI RTX 3060 VENTUS 2X OC 12GB', 'vga-msi-rtx-3060-ventus-2x-oc-12-gb', 'brand_msi_233', 'cat_vga', 10390000, 7689000, 0, 8312000, 24, 'in_stock', 'VGA MSI RTX 3060 VENTUS 2X OC 12GB', '&nbsp; &nbsp; Card màn hình MSI RTX 3060 VENTUS 2X OC 12 GB (12GB GDDR6, 192-bit, HDMI +DP, 1x8-pin) &nbsp; Sản phẩm VGA - Card đồ họa Tên Hãng MSI Model RTX 3060 VENTUS 2X OC Engine đồ họa NVIDIA® GeForce RTX™3060 Bộ nhớ trong 12GB Kiểu bộ nhớ GDDR6 Bus 192-Bit Core Clocks 1807 MHz Cuda Cores 3584 Memory Speed 15Gbps Chuẩn khe cắm PCI Express 4.0 x 16 Độ phân giải 7680x4320 Cổng giao tiếp DisplayPort 1.4a x 3HDMI 2.1 x 1 Hỗ trợ màn hình 4 Công suất nguồn yêu cầu 550W Kêt nối nguồn 1 x 8-pin Kích thước 23.5 x 12.4 x 4.2 centimet DIRECTX hỗ trợ 12 API OPENGL hỗ trợ 4.6 Số màn hình tối đa 4 Hỗ trợ VR Có G-SYNC® Có &nbsp; &nbsp; &nbsp; Hiệu năng của Card màn hình MSI RTX 3060 VENTUS 2X OC 12 GB &nbsp; Được trang bị nhân đồ họa Nvidia RTX 3060, Card màn hình MSI RTX 3060 VENTUS 2X OC 12 GB có hiệu năng tốt hơn RTX 2060 và chơi tốt tất cả những game khủng hiện nay ở độ phân giải 2K và setting đặt ở mức cao.&nbsp; Đặc điểm nổi bật Xung nhịp GPU: 1777 Mhz 12GB GDDR6 VRAM Backplate phay xước TORX Fan 3.0 MSI Dragon Center Kiến trúc Nvidia Ampere&nbsp; Bao gồm nhân RT thế hệ 2, nhân Tensor thế hệ 3 giúp hiệu năng tăng vượt trội so với người tiền nhiệm.&nbsp; &nbsp; &nbsp; TORX Fan 3.0 Tăng 50% sức gió ép trực tiếp xuống bề mặt tản nhiệt so với quạt tản nhiệt thông thường &nbsp; &nbsp; &nbsp; Phần mềm Dragon Center Kiểm soát 100% card đồ họa với chỉ 1 click với phần mềm Dragon Center được tinh chỉnh kỹ càng từ MSI.&nbsp;', '{"Sản phẩm":"VGA - Card đồ họa","Tên Hãng":"MSI","Model":"RTX 3060 VENTUS 2X OC","Engine đồ họa":"NVIDIA® GeForce RTX™3060","Bộ nhớ trong":"12GB","Kiểu bộ nhớ":"GDDR6","Bus":"192-Bit","Core Clocks":"1807 MHz","Cuda Cores":"3584","Memory Speed":"15Gbps","Chuẩn khe cắm":"PCI Express 4.0 x 16","Độ phân giải":"7680x4320"}', 0, 1);
