INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1067730994', 'SP1082102', '1067730994', 'https://www.maytinhbienhoa.vn/products/vga-msi-rtx-5060-8g-ventus-2x-oc', 'VGA MSI RTX 5060 8G VENTUS 2X OC', 'vga-msi-rtx-5060-8g-ventus-2x-oc', 'brand_msi_233', 'cat_vga', 13790000, 13790000, 0, 11032000, 24, 'in_stock', 'VGA MSI RTX 5060 8G VENTUS 2X OC', 'Thông số kỹ thuật &nbsp; TÊN SẢN PHẨM GeForce RTX™ 5060 8G VENTUS 2X OC TÊN MODEL G5060-8V2C Graphics Processing Unit (NHÂN ĐỒ HỌA) NVIDIA® GeForce RTX™ 5060 CHUẨN GIAO TIẾP PCI Express® Gen 5 x16 (uses x8) XUNG NHÂN Extreme Performance: 2535 MHz (MSI Center), Boost: 2527 MHz CUDA® CORES 3840 Units TỐC ĐỘ BỘ NHỚ 28 Gbps DUNG LƯỢNG BỘ NHỚ 8GB GDDR7 GIAO TIẾP BỘ NHỚ 128-bit CỔNG XUẤT HÌNH DisplayPort x 3 (v2.1b), HDMI™ x 1 (HDMI™ 2.1b: up to 4K 480Hz or 8K 120Hz with DSC, Gaming VRR, HDR) HỖ TRỢ HDCP&nbsp; CÓ TỔNG CÔNG SUẤT 145 W ĐẦU KẾT NỐI NGUỒN 8-pin x1 YÊU CẦU NGUỒN TỐI THIỂU 550 W KÍCH THƯỚC (mm) 197 x 120 x 41 mm TRỌNG LƯỢNG (Card / Package) 511 g / 829 g PHIÊN BẢN DirectX 12 Ultimate PHIÊN BẢN OpenGL 4.6 KẾT NỐI TỐI ĐA 4 MÀN HÌNH CÔNG NGHÊ G-SYNC® CÓ ĐỘ PHÂN GIẢI KỸ THUẬT SỐ TỐI ĐA 7680 x 4320 &nbsp; &nbsp; MSI RTX 5060 VENTUS 2X OC &nbsp;mang phong cách thiết kế đơn giản, cứng cáp và đậm chất thực dụng – đặc trưng của dòng VENTUS. Với&nbsp; thiết kế hai quạt nhỏ gọn , card dễ dàng tương thích với nhiều loại case từ Mini-ITX đến Mid Tower, đặc biệt phù hợp với những người dùng muốn nâng cấp cấu hình mà không cần thay đổi toàn bộ hệ thống. Hiệu năng ấn tượng với kiến trúc NVIDIA Ada Lovelace và GDDR7 Trang bị GPU RTX 5060 kiến trúc Ada Lovelace mới nhất, MSI VENTUS 2X OC mang lại hiệu suất đáng kinh ngạc cho các tác vụ gaming và đồ họa. Thông số kỹ thuật nổi bật: Dung lượng bộ nhớ: 8GB GDDR7 &nbsp;– chuẩn bộ nhớ mới, nhanh hơn, tiết kiệm điện hơn Boost clock đạt 2527 MHz ', '{"TÊN SẢN PHẨM":"GeForce RTX™ 5060 8G VENTUS 2X OC","TÊN MODEL":"G5060-8V2C","Graphics Processing Unit (NHÂN ĐỒ HỌA)":"NVIDIA® GeForce RTX™ 5060","CHUẨN GIAO TIẾP":"PCI Express® Gen 5 x16 (uses x8)","XUNG NHÂN":"Extreme Performance: 2535 MHz (MSI Center), Boost: 2527 MHz","CUDA® CORES":"3840 Units","TỐC ĐỘ BỘ NHỚ":"28 Gbps","DUNG LƯỢNG BỘ NHỚ":"8GB GDDR7","GIAO TIẾP BỘ NHỚ":"128-bit","CỔNG XUẤT HÌNH":"DisplayPort x 3 (v2.1b), HDMI™ x 1 (HDMI™ 2.1b: up to 4K 480Hz or 8K 120Hz with DSC, Gaming VRR, HDR)","HỖ TRỢ HDCP&nbsp;":"CÓ","TỔNG CÔNG SUẤT":"145 W"}', 0, 1);
