INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1046478878', 'SP108008', '1046478878', 'https://www.maytinhbienhoa.vn/products/vga-gigabyte-rtx-4070-eagle-12gb-oc-12gd', 'VGA Gigabyte RTX 4070 EAGLE 12GB OC-12GD', 'vga-gigabyte-rtx-4070-eagle-12gb-oc-12gd', 'brand_gigabyte_588', 'cat_vga', 17890000, 17890000, 0, 14312000, 24, 'out_of_stock', 'VGA Gigabyte RTX 4070 EAGLE 12GB OC-12GD', 'VGA Gigabyte&nbsp;RTX 4070 Eagle OC 12GB (N4070EAGLE OC-12GD) Card đồ họa Gigabyte RTX 4070 EAGLE OC12GB là một sản phẩm cao cấp, được thiết kế đáp ứng nhu cầu về hiệu suất đồ họa của game thủ và những người làm việc cần đến sự mạnh mẽ của card đồ họa. VGA này sử dụng engine đồ họa GeForce RTX™ 4070 và chuẩn Bus PCI-E 4.0. Với thiết kế nhỏ gọn, đây là lựa chọn hoàn hảo cho bộ PC Gaming mà các game thủ đã mong đợi từ lâu. Card đồ họa Gigabyte RTX 4070 EAGLE OC sử dụng bộ nhớ 12GB GDDR6X giúp tăng tốc độ xử lý đồ họa một cách nhanh chóng và mượt mà. Tốc độ xung nhân của card đạt 2505 MHz, cao hơn so với Reference Card 2475 MHz, giúp cải thiện hiệu suất của sản phẩm. Sản phẩm có lõi CUDA 5888 giúp tăng tốc độ xử lý đồ họa. Với tốc độ Clock bộ nhớ 21 Gbps, Gigabyte RTX 4070 EAGLE OC12GB sử dụng giao diện bộ nhớ 192 bit để đảm bảo tốc độ truyền dữ liệu nhanh và ổn định. Hệ thống làm mát WINDFORCE có ba quạt cánh quạt độc đáo 80 mm, quay xen kẽ, 4 ống dẫn nhiệt bằng đồng tổng hợp chạm trực tiếp vào GPU, quạt hoạt động 3D và Quạt 3D Active cung cấp khả năng làm mát bán thụ động và các quạt này sẽ vẫn tắt khi GPU ở chế độ tải thấp hoặc trò chơi tiêu thụ điện năng thấp Với 16,7 triệu tùy chọn màu có thể tùy chỉnh và nhiều hiệu ứng ánh sáng, bạn có thể chọn bất kỳ hiệu ứng ánh sáng nào hoặc đồng bộ hóa với các thiết bị khác trong GIGABYTE CONTROL CENTER. Tấm lưng kim loại không chỉ mang lại hình dáng thẩm mỹ mà còn tăng cường cấu trúc của card đồ họa để mang lại sự bảo vệ hoàn toàn. Cà', '{"Model":"VGA Gigabyte RTX 4070 EAGLE 12GB OC-12GD"}', 0, 1);
