INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1046478884', 'SP108010', '1046478884', 'https://www.maytinhbienhoa.vn/products/vga-msi-rtx-4070-gaming-x-trio-12gb', 'VGA MSI RTX 4070 GAMING X TRIO 12GB', 'vga-msi-rtx-4070-gaming-x-trio-12gb', 'brand_msi_233', 'cat_vga', 17980000, 17980000, 0, 14384000, 24, 'out_of_stock', 'VGA MSI RTX 4070 GAMING X TRIO 12GB', 'Thông số kỹ thuật: Nhân đồ họa NVIDIA® GeForce RTX™ 4070 Ti Giao thức kết nối PCI Express® Gen 4 Xung nhịp Extreme Performance: 2760 MHz (MSI Center) Boost: 2745 MHz (GAMING &amp; SILENT Mode) Nhân CUDA 7680 đơn vị Tốc độ bộ nhớ 21 Gbps Bộ nhớ 12GB GDDR6X Bus bộ nhớ 192-bit Cổng xuất hình DisplayPort x 3 (v1.4a) HDMI x 1 (Hỗ trợ 4K@120Hz HDR, 8K@60Hz HDR và ​​Tốc độ làm mới có thể thay đổi như được chỉ định trong HDMI 2.1a) Hỗ trợ HDCP Có Kết nối nguồn 16-pin x 1 PSU&nbsp;kiến nghị 700 W Kích thước 337 x 140 x 62 mm Trọng lượng&nbsp; 1613 g / 2522 g Phiên bản DirectX hỗ trợ 12 Ultimate OpenGL 4.6 Hỗ trợ màn hình tối đa 4 Công nghệ G-Sync Có Độ phân giải tối đa 7680 x 4320 Đánh giá chi tiết VGA&nbsp;MSI GeForce RTX 4070 Ti GAMING X TRIO 12G Là “người thay thế” cho model&nbsp;RTX 4080&nbsp;12GB và là nâng cấp của&nbsp;RTX 4070,&nbsp;RTX 4070 Ti&nbsp;trở lại với một sức nguồn sức mạnh nguyên thủy đã làm nên tên tuổi của dòng GPU cao cấp trước đây. Tự tin là một trong những ông lớn trong ngành sản xuất VGA, MSI đã tiếp nhận và ngay lập tức cho ra mắt chiếc card RTX 4070 Ti thuộc về series GAMING X TRIO với tên đầy đủ,&nbsp; MSI GeForce RTX 4070 Ti GAMING X TRIO . Ngoại hình bắt mắt, đậm chất GAMING X TRIO Nếu để có thể kể tên một series sản phẩm dành cho gaming từ MSI thì GAMING X TRIO xứng đáng là một trong những cái tên top đầu. Không những sở hữu những thành phẩm chất lượng mà ngoại hình của dòng GAMING X TRIO vốn đã ghi điểm trong mắt người dùng. MSI GeForce RTX 4070 Ti GAMIN', '{"Nhân đồ họa":"NVIDIA® GeForce RTX™ 4070 Ti","Giao thức kết nối":"PCI Express® Gen 4","Xung nhịp":"Extreme Performance: 2760 MHz (MSI Center) Boost: 2745 MHz (GAMING &amp; SILENT Mode)","Nhân CUDA":"7680 đơn vị","Tốc độ bộ nhớ":"21 Gbps","Bộ nhớ":"12GB GDDR6X","Bus bộ nhớ":"192-bit","Cổng xuất hình":"DisplayPort x 3 (v1.4a) HDMI x 1 (Hỗ trợ 4K@120Hz HDR, 8K@60Hz HDR và ​​Tốc độ làm mới có thể thay đổi như được chỉ định trong HDMI 2.1a)","Hỗ trợ HDCP":"Có","Kết nối nguồn":"16-pin x 1","PSU&nbsp;kiến nghị":"700 W","Kích thước":"337 x 140 x 62 mm"}', 0, 1);
