INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1046478928', 'SP108013', '1046478928', 'https://www.maytinhbienhoa.vn/products/vga-colorful-rtx-4070-igame-vulcan-oc-v-12gb', 'VGA Colorful RTX 4070 iGame Vulcan OC-V 12GB', 'vga-colorful-rtx-4070-igame-vulcan-oc-v-12gb', 'brand_colorful_614', 'cat_vga', 22890000, 22890000, 0, 18312000, 24, 'out_of_stock', 'VGA Colorful RTX 4070 iGame Vulcan OC-V 12GB', 'VGA Colorful iGame GeForce RTX 4070 TI 12G Vulcan OC-V &nbsp; VGA Colorful iGame GeForce RTX 4070 TI 12G Vulcan OC-V mang kiến trúc Ada thể hiện toàn bộ những gì tinh túy nhất của tính năng dò tia. Với sức mạnh của RTX 40 Series và RT Cores thế hệ thứ ba của linh kiện máy tính này, bạn có thể trải nghiệm thế giới ảo chi tiết hơn bao giờ hết! Thiết kế ấn tượng với hệ thống RGB rực rỡ Nếu bạn là người yêu thích sự nổi bật, muốn tạo cho không gian làm việc đa sắc thì VGA - Card màn hình VGA Colorful iGame GeForce RTX 4070 TI 12G Vulcan OC-V sẽ là sự lựa chọn hàng đầu dành cho bạn. Mặc dù thiết kế vẫn là kiểu dáng Hurricane Scythe Blade – vẫn là màu bạc ánh kim trên nền đen, nhưng dòng card đồ họa này đã được trang bị hai dải đèn LED RGB chạy dọc ở hai cạnh và có thể tùy chỉnh màu sắc thông qua phần mềm độc quyền iGame Center. Bạn hoàn toàn có thể tạo ra các sắc màu mà mình yêu thích để bàn làm việc luôn rực rỡ, sống động. Ngoài ra, VGA Colorful iGame GeForce RTX 4070 TI 12G Vulcan OC-V còn sở hữu thiết kế cánh quạt cải tiến. Điều này giúp tạo ra nhiều luồng gió hơn với độ ồn thấp hơn so với thiết kế quạt Storm Chaser ở thế hệ trước. Màn hình iGame Smart LCD VGA Colorful iGame GeForce RTX 4070 TI 12G Vulcan OC-V mới có màn hình iGame Smart LCD hoàn toàn mới. Mặc định, iGame Smart LCD được cài đặt sẵn trên card đồ họa Vulcan và có thể được lắp theo chiều dọc hoặc chiều ngang. Màn hình này có thể tháo rời để đặc trên một đến màn hình đi kèm. iGame Smart LCD được kết nối qua USB với', '{"Model":"VGA Colorful RTX 4070 iGame Vulcan OC-V 12GB"}', 1, 1);
