INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1046478880', 'SP108009', '1046478880', 'https://www.maytinhbienhoa.vn/products/vga-msi-rtx-4070-ventus-3x-12g-oc', 'VGA MSI RTX 4070 VENTUS 3X 12G OC', 'vga-msi-rtx-4070-ventus-3x-12g-oc', 'brand_msi_233', 'cat_vga', 16290000, 16290000, 0, 13032000, 24, 'out_of_stock', 'VGA MSI RTX 4070 VENTUS 3X 12G OC', 'Thông số kỹ thuật: Nhân đồ họa NVIDIA® GeForce&nbsp;RTX™ 4070 Giao thức kết nối PCI Express® Gen 4 Xung nhịp Extreme Performance: 2520 MHz (MSI Center) Boost: 2505 MHz (GAMING &amp; SILENT Mode) Nhân CUDA 5888 đơn vị Tốc độ bộ nhớ 21 Gbps Bộ nhớ 12GB GDDR6X Bus bộ nhớ 192-bit Cổng xuất hình DisplayPort x 3 (v1.4a) HDMI x 1 (Hỗ trợ 4K@120Hz HDR, 8K@60Hz HDR và ​​Tốc độ làm mới có thể thay đổi như được chỉ định trong HDMI 2.1a) Hỗ trợ HDCP Có Kết nối nguồn 8-pin x 1 PSU&nbsp;kiến nghị 650W Kích thước 308 x 120 x 43 mm Trọng lượng&nbsp; 811 g / 1152 g Phiên bản DirectX hỗ trợ 12 Ultimate OpenGL 4.6 Hỗ trợ màn hình tối đa 4 Công nghệ G-Sync Có Độ phân giải tối đa 7680 x 4320 Đánh giá chi tiết VGA&nbsp;MSI GeForce RTX 4070 VENTUS 3X 12G OC RTX 4070 chính thức ra mắt cùng nhiều biến thể đến từ những thương hiệu nổi tiếng trên toàn thế giới và MSI tự tin là một trong những phiên bản uy tín dành cho GPU của thế hệ RTX 40 Series này. Chào mừng bạn đến với sức mạnh của &nbsp;MSI GeForce RTX 4070 VENTUS 3X 12G OC &nbsp;ngay sau đây ! Thiết kế hiện đại, đầy sắc sảo Vẫn đề cao tôn chỉ của những phiên bản VENTUS đã xuất hiện trên&nbsp;GTX 1650&nbsp;hay&nbsp;RTX 2060, MSI GeForce RTX 4070 VENTUS 3X 12G OC sở hữu cho mình bộ khung toát lên sự cứng cáp dành cho&nbsp;card màn hình. Những chi tiết thể hiện nên khả năng bảo vệ mạnh mẽ cho chính sức mạnh xử lý đồ họa đến từ GPU RTX 40 Series biến nó trở thành món cỗ máy cực kì hiệu quả trong mọi tác vụ như chơi game, làm việc. Đây sẽ là một lựa c', '{"Nhân đồ họa":"NVIDIA® GeForce&nbsp;RTX™ 4070","Giao thức kết nối":"PCI Express® Gen 4","Xung nhịp":"Extreme Performance: 2520 MHz (MSI Center) Boost: 2505 MHz (GAMING &amp; SILENT Mode)","Nhân CUDA":"5888 đơn vị","Tốc độ bộ nhớ":"21 Gbps","Bộ nhớ":"12GB GDDR6X","Bus bộ nhớ":"192-bit","Cổng xuất hình":"DisplayPort x 3 (v1.4a) HDMI x 1 (Hỗ trợ 4K@120Hz HDR, 8K@60Hz HDR và ​​Tốc độ làm mới có thể thay đổi như được chỉ định trong HDMI 2.1a)","Hỗ trợ HDCP":"Có","Kết nối nguồn":"8-pin x 1","PSU&nbsp;kiến nghị":"650W","Kích thước":"308 x 120 x 43 mm"}', 0, 1);
