INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1046478925', 'SP108012', '1046478925', 'https://www.maytinhbienhoa.vn/products/vga-colorful-rtx-4070-igame-neptune-12gb-l-v', 'VGA Colorful RTX 4070 iGame Neptune 12GB L-V', 'vga-colorful-rtx-4070-igame-neptune-12gb-l-v', 'brand_colorful_614', 'cat_vga', 23490000, 23490000, 0, 18792000, 24, 'out_of_stock', 'VGA Colorful RTX 4070 iGame Neptune 12GB L-V', 'VGA Colorful RTX 4070 Neptune OC-V Tên sản phẩm: &nbsp;VGA Colorful RTX 4070 Neptune OC-V Card xử lý đồ họa :&nbsp;GeForce RTX™ 4070 Dung lượng bộ nhớ: &nbsp;12GB Loại bộ nhớ: &nbsp;GDDR6X - 192-bit Boost Clock: &nbsp;2640&nbsp;MHz Game Clock: &nbsp;1920&nbsp;MHz Nguồn cấp: &nbsp;650W – 16-pin x1 Nhân CUDA: &nbsp;5888 Hỗ trợ xuất hình: &nbsp;DisplayPort x 3 (v1.4a). HDMI x 1 Kích thước Card: &nbsp;253.5&nbsp;x 170&nbsp;x 431.5 mm Giao diện kết nối: &nbsp;PCI Express 4.0 &nbsp; VGA Colorful RTX 4070 Neptune OC-V Nvidia RTX 40 Series được trang bị hàng loạt công nghệ máy tính mới nhất giúp khả năng xử lý, render… được nâng lên tầm cao mới. Kết hợp với tích hợp AI càng giúp cho 40 Series trở nên mạnh mẽ và ổn định khi hoạt động với cường độ cao. Giờ đây Nvidia RTX 40 Series không chỉ dành cho việc chơi game nặng mà còn đáp ứng đủ nhu cầu cho việc thiết kế đồ họa mà không lo về hiệu năng cũng như chất lượng. DLSS 3 là một bước trong nhũng bước&nbsp;đột phá trong đồ họa do AI cung cấp để gia tăng hiệu suất. Được hỗ trợ bởi công nghệ lõi Tensor thuộc&nbsp;thế hệ thứ 4&nbsp;mới nhất. Từ đó trình tăng tốc trên GPU GeForce RTX 40 Series cụ thể là&nbsp; RTX 4070 , DLSS 3 sử dụng AI để tạo thêm các khung hình chất lượng cao. Thông số kỹ thuật Tên sản phẩm: &nbsp;VGA Colorful RTX 4070 Neptune OC-V Card xử lý đồ họa :&nbsp;GeForce RTX™ 4070 Dung lượng bộ nhớ: &nbsp;12GB Loại bộ nhớ: &nbsp;GDDR6X - 192-bit Boost Clock: &nbsp;2640&nbsp;MHz Game Clock: &nbsp;1920&nbsp;MHz Nguồn cấp: &nbsp;65', '{"Tên sản phẩm":"&nbsp;VGA Colorful RTX 4070 Neptune OC-V","Card xử lý đồ họa":"&nbsp;GeForce RTX™ 4070","Dung lượng bộ nhớ":"&nbsp;12GB","Loại bộ nhớ":"&nbsp;GDDR6X - 192-bit","Boost Clock":"&nbsp;2640&nbsp;MHz","Game Clock":"&nbsp;1920&nbsp;MHz","Nguồn cấp":"&nbsp;650W – 16-pin x1","Nhân CUDA":"&nbsp;5888"}', 1, 1);
