INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1046478969', 'SP108018', '1046478969', 'https://www.maytinhbienhoa.vn/products/vga-asus-rtx-4070-tuf-12g-gddr6x', 'VGA Asus RTX 4070 TUF 12G GDDR6X', 'vga-asus-rtx-4070-tuf-12g-gddr6x', 'brand_asus_316', 'cat_vga', 17890000, 17890000, 0, 14312000, 24, 'out_of_stock', 'VGA Asus RTX 4070 TUF 12G GDDR6X', 'Thông số kĩ thuật Nhà sản xuất Asus Model TUF-RTX4070TI-12G-GAMING Graphic Engine NVIDIA GeForce RTX 4070 Ti OpenGL OpenGL 4.6 Bộ nhớ 12GB GDDR6X Bus Standard PCI Express 4.0 Engine Clock OC Mode - 2640&nbsp;MHz (Boost Clock) Default Mode&nbsp;- 2610 MHz (Boost Clock) CUDA Core 7680 Tốc độ bộ nhớ 21 Gbps Giao diện bộ nhớ 192-bit Độ phân giải Digital Max Resolution 7680 x 4320 Hỗ trợ giao diện tối đa 4 Giao diện 3 x&nbsp;DisplayPort 1.4a 2 x&nbsp;HDMI 2.1a Hỗ trợ HDCP (2.3) Nguồn khuyến cáo 750W Kích thước 305 x 138 x 65 mm Kết nối nguồn 1 x 16-pin Slot 3.25 Bảo hành 3 năm&nbsp;(Không bảo hành Coin) VGA Asus TUF Gaming GeForce RTX 4070 Ti 12GB GDDR6X Tích hợp TUF TUF Gaming GeForce RTX&nbsp;4070 Ti&nbsp; được thiết kế hoàn toàn mới nhằm cung cấp sức mạnh và khả năng làm mát vượt trội hơn. Phần vỏ bên ngoài hoàn toàn bằng kim loại với ba quạt công nghệ Axial mạnh mẽ sử dụng ổ trục vòng bi kép bền bỉ. Vòng quay của quạt đã được tối ưu để đảm bảo độ ổn định và một chế độ dừng sẽ tạm dừng cả ba quạt ở nhiệt độ thấp. Các bộ tản nhiệt độc lập cho GPU và bộ nhớ sẽ giúp kiểm soát nhiệt độ chặt chẽ. Lõi Tensor thế hệ mới TUF Gaming GeForce&nbsp;RTX 4070 Ti&nbsp; được trang bị lõi Tensor thế hệ thứ mới giúp tăng hiệu suất AI lên&nbsp;gấp 2 lần. Sử dụng NVIDIA Tensor Cores để&nbsp;tăng tốc các công nghệ AI và tốc độ khung hình mới nhân DLSS 3 đem lại cho game thủ những khung hình mượt mà hơn, tốc độ hơn với những tựa game AAA yêu thích. Thiết kế độc đáo VGA Asus TUF Gaming GeForce RTX 40', '{"Thông số kĩ thuật":"Nhà sản xuất","Model":"TUF-RTX4070TI-12G-GAMING","Graphic Engine":"NVIDIA GeForce RTX 4070 Ti","OpenGL":"OpenGL 4.6","Bộ nhớ":"12GB GDDR6X","Bus Standard":"PCI Express 4.0","Engine Clock":"OC Mode - 2640&nbsp;MHz (Boost Clock) Default Mode&nbsp;- 2610 MHz (Boost Clock)","CUDA Core":"7680","Tốc độ bộ nhớ":"21 Gbps","Giao diện bộ nhớ":"192-bit","Độ phân giải":"Digital Max Resolution 7680 x 4320","Hỗ trợ giao diện tối đa":"4"}', 0, 1);
