INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1046478933', 'SP108014', '1046478933', 'https://www.maytinhbienhoa.vn/products/vga-colorful-rtx-4070-igame-ultra-w-oc-12gb-l-v', 'VGA Colorful RTX 4070 iGame Ultra White OC 12GB L-V', 'vga-colorful-rtx-4070-igame-ultra-w-oc-12gb-l-v', 'brand_colorful_614', 'cat_vga', 16490000, 16190000, 0, 13192000, 24, 'out_of_stock', 'VGA Colorful RTX 4070 iGame Ultra White OC 12GB L-V', 'VGA Colorful Igame RTX 4070 Ultra White OC 12GB L-V RTX 4070 đã được sử dụng chip AD104 giống như RTX 4070 Ti mà nvidia đã ra mắt vào đầu năm nay, mặc dù đã bị cắt giảm nhiều. Nó chỉ có 46 trong số 60 bộ xử lý phát trực tuyến (SM), có nghĩa là nó có 5.888 lõi CUDA, 184 lõi Tensor, 46 lõi RT, 184 TMU và 64 ROP khi chạm. Bộ nhớ không bị ảnh hưởng từ Ti, bạn vẫn nhận được 12 GB bộ nhớ GDDR6X 21 Gbps trên bus bộ nhớ 192 bit của chip. Thiết kế bắt mắt với phong cách nghệ thuật POP Art Thiết kế tổng thể của phiên bản 4070 mới này vẫn mang giữ lại những nét đặc trưng của dòng sản phẩm Ultra W với khung vỏ, tấm kim loại mặt sau và quạt tản nhiệt đều mang màu trắng chủ đạo.&nbsp; Họa tiết mang phong cách nghệ thuật đại chóng POP Art, kết hợp lớp phủ màu phản quang mang đến nhiều sắc màu khác nhau tùy theo góc nhìn cùng màn hình LED RGB với hiệu ứng LED Retro. Tất cả mang đến cho card đồ họa iGame GeForce RTX 4070 Ultra W OC V2-V một vẻ ngoài bắt mắt và cuốn hút mọi ánh nhìn khi hoạt động. Nâng cấp sáng giá trong thiết kế tổng thể của iGame GeForce RTX 4070 Ultra W OC V2-V chính là hệ thống tản nhiệt 3 quạt ULTRA Cooling 110mm có độ dày chỉ 51,2mm. Điều này cũng đồng nghĩa phiên bản Ultra W OC V2-V là card đồ họa mỏng nhất trong dòng GeForce RTX 4070 trang bị tản nhiệt khí của COLORFUL. Dòng GeForce RTX 4070 - BEYOND FAST Trang bị với Card đồ họa NVIDIA® GeForce RTX 4070 Ti và RTX™ 4070 cho sáng tạo và chơi game đỉnh cao. Chúng được xây dựng với kiến trúc NVIDIA Ada Lovelace cực kỳ hiệ', '{"Bộ đa xử lý phát trực tiếp mới":"Hiệu suất và khả năng tiết kiệm điện năng gấp tới 2 lần","Nhân Tensor thế hệ thứ tư":"Hiệu suất gấp tới 4 lần nhờ DLSS 3 so với render brute force","Nhân Dò tia thế hệ thứ ba":"Hiệu suất dò tia nhanh gấp tới 2 lần"}', 0, 1);
