INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1069783644', 'SP1082557', '1069783644', 'https://www.maytinhbienhoa.vn/products/nguon-mik-e350-300w', 'Nguồn MIK E350 300W', 'nguon-mik-e350-300w', 'brand_mik_225', 'cat_psu', 339000, 339000, 0, 271200, 24, 'in_stock', 'Nguồn MIK E350 300W', 'Thông số kỹ thuật &nbsp; Công suất toàn tải 300W Chuẩn thiết kế ATX Cáp kết nối ​​​​1x 20 + 4 pin MB (520mm)&nbsp; 1x 6&nbsp;pin PCI-E (500mm)&nbsp; 1x 4+4 pin CPU&nbsp;(520mm)&nbsp; 2x SATA (400mm) 1x SATA (150mm) 2x ATA (150mm) Tản nhiệt&nbsp; 120mm Nguồn điện vào 200 - 240V Dòng điện vào&nbsp; 5A Dải tần vào 50Hz - 60Hz Bảo vệ ACTIVE PFC Nhiệt độ hoạt động 0 - 60 độ C Nguồn MIK E350 – Nền Tảng Bền Bỉ Cho Hệ Thống Máy Tính Của Bạn Khi xây dựng một bộ máy tính mới hay nâng cấp một hệ thống văn phòng, học tập, việc lựa chọn một bộ nguồn (PSU) ổn định và đáng tin cậy là yếu tố tiên quyết. Nguồn máy tính MIK E350 thuộc E-Series được ra mắt để đáp ứng hoàn hảo nhu cầu đó, mang đến một giải pháp năng lượng hiệu quả, bền bỉ với những tính năng vượt trội trong phân khúc, là sự khởi đầu lý tưởng cho mọi hệ thống PC cơ bản. Hiệu Suất Ổn Định với Công Nghệ Active PFC Trái tim của MIK E350 là một mạch công suất được thiết kế kỹ lưỡng, cung cấp mức công suất thực ổn định 250W và có thể đạt tổng công suất tối đa lên đến 300W. Bộ nguồn được trang bị đường +12V single-rail mạnh mẽ, có khả năng cung cấp tới 240W, đảm bảo dòng điện ổn định và đủ đầy cho các linh kiện quan trọng nhất như CPU và card đồ họa rời. Một trong những ưu điểm sáng giá của E350 là việc tích hợp công nghệ điều chỉnh hệ số công suất chủ động&nbsp; Active PFC . Công nghệ tiên tiến này giúp bộ nguồn hoạt động hiệu quả hơn, ổn định dòng điện đầu vào và giảm thiểu hao phí điện năng, từ đó giúp tiết kiệm chi phí và thân thiệ', '{"Công suất toàn tải":"300W","Chuẩn thiết kế":"ATX","Cáp kết nối":"​​​​1x 20 + 4 pin MB (520mm)&nbsp; 1x 6&nbsp;pin PCI-E (500mm)&nbsp; 1x 4+4 pin CPU&nbsp;(520mm)&nbsp; 2x SATA (400mm) 1x SATA (150mm) 2x ATA (150mm)","Tản nhiệt&nbsp;":"120mm","Nguồn điện vào":"200 - 240V","Dòng điện vào&nbsp;":"5A","Dải tần vào":"50Hz - 60Hz","Bảo vệ":"ACTIVE PFC","Nhiệt độ hoạt động":"0 - 60 độ C"}', 0, 1);
