INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074966870', 'SP1083713', '1074966870', 'https://www.maytinhbienhoa.vn/products/nguon-ocypus-beta-p600s-500w', 'Nguồn Ocypus 600w Beta P600S', 'nguon-ocypus-beta-p600s-500w', 'brand_ocypus_483', 'cat_psu', 679000, 679000, 0, 543200, 24, 'in_stock', 'Nguồn Ocypus 600w Beta P600S', 'Thông số kỹ thuật Thông tin chung Bảo hành 36 tháng (3 năm) Tên sản phẩm NGUỒN OCYPUS BETA P600S 600W (P/N BETA-P500S-NDHBK026X-EU) / BH 36T - ĐEN Hãng OCYPUS Ngành hàng Nguồn Tình trạng Mới Tản nhiệt &amp; Quạt Kích thước quạt 120mm Điều khiển quạt Kiểm soát nhiệt độ (Thermal Control) Thông tin hàng hóa Kích thước 150 × 140 × 86 mm (W × L × H) Thông số kỹ thuật Điện áp đầu vào 220-240VAC / 6.3A / 50Hz Kích cỡ ATX 2.31 Công suất 600W Kiểu dây Non-modular (Cáp liền) Công nghệ &amp; Tính năng Tính năng bảo vệ OPP / OVP / SCP &nbsp; &nbsp; Mô tả &nbsp; OCYPUS Beta P600S 500W Non Modular là bộ nguồn máy tính công suất thực 500W, được thiết kế dành cho các cấu hình PC văn phòng, học tập, đồ họa và gaming tầm trung. Sản phẩm sử dụng kiến trúc Double Forward + DC to DC , giúp cung cấp nguồn điện ổn định, tăng hiệu suất chuyển đổi điện năng và đảm bảo độ bền lâu dài cho hệ thống. Với thiết kế Non-Modular , dây nguồn được tích hợp sẵn giúp lắp đặt nhanh chóng và tối ưu chi phí cho người dùng. &nbsp; &nbsp; &nbsp; Bộ nguồn được trang bị quạt làm mát 120mm điều khiển nhiệt độ thông minh (Thermal Control) , tự động điều chỉnh tốc độ quay theo tải hoạt động nhằm cân bằng giữa hiệu quả tản nhiệt và độ ồn thấp. Ngoài ra, OCYPUS Beta P600S còn tích hợp các cơ chế bảo vệ quan trọng như OPP (chống quá tải), OVP (chống quá áp) và SCP (chống ngắn mạch) giúp bảo vệ linh kiện PC an toàn trong quá trình sử dụng. Với kích thước chuẩn ATX, khả năng tương thích cao cùng mức giá hợp lý, OCYPUS Beta P60', '{"Bảo hành":"36 tháng (3 năm)","Tên sản phẩm":"NGUỒN OCYPUS BETA P600S 600W (P/N BETA-P500S-NDHBK026X-EU) / BH 36T - ĐEN","Hãng":"OCYPUS","Ngành hàng":"Nguồn","Tình trạng":"Mới","Kích thước quạt":"120mm","Điều khiển quạt":"Kiểm soát nhiệt độ (Thermal Control)","Kích thước":"150 × 140 × 86 mm (W × L × H)","Điện áp đầu vào":"220-240VAC / 6.3A / 50Hz","Kích cỡ":"ATX 2.31","Công suất":"600W","Kiểu dây":"Non-modular (Cáp liền)"}', 0, 1);
