INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1067466250', 'SP1082052', '1067466250', 'https://www.maytinhbienhoa.vn/products/nguon-mik-c550b-80-efficiency', 'Nguồn MIK C550B 550W 80% Efficiency', 'nguon-mik-c550b-80-efficiency', 'brand_kh-c_503', 'cat_psu', 690000, 690000, 0, 552000, 24, 'in_stock', 'Nguồn MIK C550B 550W 80% Efficiency', '&nbsp; &nbsp; Thông số kỹ thuật Công suất&nbsp; 550W Chứng nhận 80%&nbsp;Efficiency Chuẩn thiết kế ATX Cáp kết nối ​​​​1x 20 + 4 pin MB (550mm)&nbsp; 2x 8(6+2) pin PCI-E (500mm)&nbsp; 1x 4+4 pin CPU&nbsp;(550mm)&nbsp; 2x SATA+SATA+PATA(450mm) Tản nhiệt&nbsp; 120mm Nguồn điện vào 200 - 240V Dòng điện vào&nbsp; 8A Dải tần vào 47Hz - 60Hz Bảo vệ OCP/ OVP /SCP Nhiệt độ hoạt động 0 - 40 độ C &nbsp; MÔ TẢ SẢN PHẨM &nbsp; Nguồn Máy Tính MIK C550B - Sức Mạnh Ổn Định Cho Hệ Thống Của Bạn Thương hiệu&nbsp; MIK &nbsp;vừa chính thức ra mắt dòng sản phẩm nguồn máy tính mới nhất -&nbsp; MIK C550B , mang đến giải pháp tối ưu cho các hệ thống PC từ cơ bản đến tầm trung. Với công suất thực&nbsp; 550W&nbsp; cùng mức 80% Efficiency, MIK C550B hứa hẹn đáp ứng tốt nhu cầu của người dùng phổ thông, từ học tập, làm việc đến chơi game nhẹ nhàng, đồng thời đảm bảo sự ổn định và bền bỉ trong thời gian dài. MIK C550B &nbsp;được thiết kế với tiêu chí đơn giản nhưng hiệu quả. Sản phẩm sở hữu quạt làm mát 120mm hoạt động êm ái, giúp duy trì nhiệt độ lý tưởng ngay cả khi hệ thống vận hành ở cường độ cao. Hệ thống dây cáp dài và linh hoạt hỗ trợ lắp đặt dễ dàng trên nhiều loại case, từ mini tower đến mid tower, mang lại sự tiện lợi tối đa cho người dùng. Đặc biệt, nguồn được trang bị các linh kiện chất lượng cao, đảm bảo cung cấp điện năng ổn định cho CPU, GPU và các thiết bị ngoại vi khác. Một điểm nhấn của&nbsp; MIK C550B &nbsp;là khả năng tương thích vượt trội với các cấu hình phổ thông hiện nay. Dù bạn ', '{"Công suất&nbsp;":"550W","Chứng nhận":"80%&nbsp;Efficiency","Chuẩn thiết kế":"ATX","Cáp kết nối":"​​​​1x 20 + 4 pin MB (550mm)&nbsp; 2x 8(6+2) pin PCI-E (500mm)&nbsp; 1x 4+4 pin CPU&nbsp;(550mm)&nbsp; 2x SATA+SATA+PATA(450mm)","Tản nhiệt&nbsp;":"120mm","Nguồn điện vào":"200 - 240V","Dòng điện vào&nbsp;":"8A","Dải tần vào":"47Hz - 60Hz","Bảo vệ":"OCP/ OVP /SCP","Nhiệt độ hoạt động":"0 - 40 độ C"}', 0, 1);
