INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1076606934', 'SP1084147', '1076606934', 'https://www.maytinhbienhoa.vn/products/nguon-may-tinh-1stplayer-600w-dkpm-brz-600-den-80-plus-bronze', 'NGUỒN MÁY TÍNH 1STPLAYER 600W DKPM-BRZ-600 ĐEN (80 PLUS BRONZE)', 'nguon-may-tinh-1stplayer-600w-dkpm-brz-600-den-80-plus-bronze', 'brand_1st-player_709', 'cat_psu', 990000, 990000, 0, 792000, 24, 'in_stock', 'NGUỒN MÁY TÍNH 1STPLAYER 600W DKPM-BRZ-600 ĐEN (80 PLUS BRONZE)', 'Thông tin khác Mô tả khác 1 dây nguồn chuẩn EU + 4 ốc bắt nguồn + 4 cable tie(dây rút) + Sách hướng dẫn sử dụng Thông tin chung Chuẩn nguồn 80 Plus Bronze Công suất danh định 600W Đầu cấp điện cho main 20+4pins Đầu cấp điện cho hệ thống 24 pin x 1/ CPU 4+4pin x 1/ PCI-E 6+2pin x 1/ SATA IDE x 3 Quạt làm mát Fan 12cm Phụ kiện kèm theo cáp nguồn Màu sắc Đen Kích cỡ nguồn ATX Kiểu cáp nguồn Non-Modular (Dây liền toàn bộ) &nbsp; &nbsp; NGUỒN MÁY TÍNH FIRST PLAYER (1STPLAYER) DKPM-BRZ-600 600W ĐEN (80 PLUS BRONZE) Nguồn máy tính First Player (1stPlayer) DKPM-BRZ-600 600W Đen &nbsp;là một sản phẩm thuộc dòng DK Premium của First Player, được thiết kế để cung cấp năng lượng ổn định và hiệu quả cho các hệ thống PC tầm trung. Với chứng nhận 80 PLUS Bronze và công suất mạnh mẽ, đây là lựa chọn lý tưởng cho game thủ và người dùng muốn xây dựng một dàn PC hiệu suất cao với mức chi phí hợp lý. Hiệu suất và thông số kỹ thuật DKPM-BRZ-600 có công suất định mức&nbsp; 600W , đủ sức hỗ trợ các cấu hình sử dụng CPU như Intel Core i5/i7 hoặc AMD Ryzen 5, kết hợp với card đồ họa tầm trung như RTX 2060 hoặc RX 6600. Nguồn đạt chứng nhận&nbsp; 80 PLUS Bronze , với hiệu suất lên đến 90% ở tải tiêu chuẩn, giúp tiết kiệm điện năng và giảm nhiệt lượng tỏa ra trong quá trình hoạt động. Đường +12V single rail cung cấp dòng điện chính mạnh mẽ (thường khoảng 45-50A), đảm bảo năng lượng ổn định cho CPU và GPU. Sản phẩm hỗ trợ điện áp đầu vào rộng từ 100-240V, phù hợp với nhiều khu vực sử dụng điện. Hệ thống', '{"Thông tin khác":"Mô tả khác","Thông tin chung":"Chuẩn nguồn","Công suất danh định":"600W","Đầu cấp điện cho main":"20+4pins","Đầu cấp điện cho hệ thống":"24 pin x 1/ CPU 4+4pin x 1/ PCI-E 6+2pin x 1/ SATA IDE x 3","Quạt làm mát":"Fan 12cm","Phụ kiện kèm theo":"cáp nguồn","Màu sắc":"Đen","Kích cỡ nguồn":"ATX","Kiểu cáp nguồn":"Non-Modular (Dây liền toàn bộ)"}', 0, 1);
