INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074872011', 'SP1083689', '1074872011', 'https://www.maytinhbienhoa.vn/products/nguon-nzxt-c750w-bronze-atx-3-1-pa-7b3bb-us', 'NGUỒN NZXT 750w C750W BRONZE ATX 3.1 (PA-7B3BB-US)', 'nguon-nzxt-c750w-bronze-atx-3-1-pa-7b3bb-us', 'brand_nzxt_340', 'cat_psu', 1650000, 1650000, 0, 1320000, 24, 'in_stock', 'NGUỒN NZXT 750w C750W BRONZE ATX 3.1 (PA-7B3BB-US)', 'THÔNG SỐ KỸ THUẬT &nbsp; Kích thước 150 x 140 x 86mm Vật liệu Thép, PCB và nhựa Thông số kỹ thuật của quạt Kích thước&nbsp;:&nbsp;135 x 135 x 25 mm Kích thước : 120 x 120 x 25 (mm) Tốc độ : 2400 ±10% vòng/phút Luồng khí : 64,4 CFM (Tpy.) Độ ồn : tối đa 39,92 dBA Vòng bi : FDB (Vòng bi động lực chất lỏng) Chứng nhận 80 Plus Bronze kết nối đầu ra 24-pin ATX Power:1 4+4-pin CPU power:2 6+2-pin PCIe power:2 SATA Power:4 Peripherals:4 Cáp 24-pin ATX power:600mm, Nylon sleeving 4+4-pin CPU power:700mm, Nylon sleeving 6+2-pin PCIe power:650 + 150mm, Nylon sleeving SATA power:500 + 150 mm Peripherals:500 + 150 mm DC OUTPUT RATING +3.3V:20A (120W) +5V:20A (120W) +12V:62.5A (750W) -12V:0.3A (3.6W) 5Vsb:2.5A (12.5W) Total:750W AC INPUT RATING 100 - 240Vac:10A-5A 50Hz-60Hz &nbsp; Nguồn máy tính NZXT C750W BRONZE - Non Modular Nguồn máy tính NZXT C750W BRONZE - Non Modular là một PSU đáng tin cậy với nguồn điện dồi dào và hiệu suất bền bỉ để hoạt động, rất phù hợp với hệ thống PC gaming và những dòng máy tính cấu hình mạnh&nbsp; &nbsp; Với mức công suất là 750W, Nguồn máy tính NZXT C750W BRONZE tự tin cung cấp nguồn điện liên tục và phù hợp đối với hệ thống PC gaming, cũng như máy tính cấu hình mạnh. Không chỉ vậy, bộ nguồn đạt chuẩn 80Plus Bronze - một trong những điều kiện chứng minh cho hiệu suất sử dụng điện năng tối ưu. &nbsp; Dòng nguồn máy tính NZXT này đã được thiết kế theo nhu cầu sử dụng của người dùng khi cung cấp đầy đủ các cổng kết nối bao gồm nguồn ATX 24 chân: 1; nguồn CPU ', '{"Kích thước":"150 x 140 x 86mm","Vật liệu":"Thép, PCB và nhựa","Thông số kỹ thuật của quạt":"Kích thước&nbsp;:&nbsp;135 x 135 x 25 mm Kích thước : 120 x 120 x 25 (mm) Tốc độ : 2400 ±10% vòng/phút Luồng khí : 64,4 CFM (Tpy.) Độ ồn : tối đa 39,92 dBA Vòng bi : FDB (Vòng bi động lực chất lỏng)","Chứng nhận":"80 Plus Bronze","kết nối đầu ra":"24-pin ATX Power:1 4+4-pin CPU power:2 6+2-pin PCIe power:2 SATA Power:4 Peripherals:4","Cáp":"24-pin ATX power:600mm, Nylon sleeving 4+4-pin CPU power:700mm, Nylon sleeving 6+2-pin PCIe power:650 + 150mm, Nylon sleeving SATA power:500 + 150 mm Peripherals:500 + 150 mm","DC OUTPUT RATING":"+3.3V:20A (120W) +5V:20A (120W) +12V:62.5A (750W) -12V:0.3A (3.6W) 5Vsb:2.5A (12.5W) Total:750W","AC INPUT RATING":"100 - 240Vac:10A-5A 50Hz-60Hz"}', 0, 1);
