INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1070291192', 'SP1082699', '1070291192', 'https://www.maytinhbienhoa.vn/products/nguon-asus-750w-prime-750b-80-plus-bronze-non-modular-6-nam-bao-hanh', 'Nguồn ASUS 750W PRIME 750B (80 Plus Bronze, Non-modular, 6 năm bảo hành)', 'nguon-asus-750w-prime-750b-80-plus-bronze-non-modular-6-nam-bao-hanh', 'brand_asus_316', 'cat_psu', 1690000, 1690000, 0, 1352000, 24, 'in_stock', 'Nguồn ASUS 750W PRIME 750B (80 Plus Bronze, Non-modular, 6 năm bảo hành)', 'THÔNG SỐ KỸ THUẬT &nbsp; Thương hiệu Asus Bảo hành 72 tháng Công suất tối đa 750W Kiểu dây nguồn Non Modular Hiệu suất 80 Plus Bronze Màu sắc Đen Kích thước nguồn 150 x 150 x 86 mm Điện áp vào 100-240Vac Điện áp ra +3.3V +5V +12V -12V +5Vsb Tiêu chuẩn OPP/OVP/UVP/SCP/OCP/OTP Cổng kết nối Mainboard: 1 x 24/20-pin CPU: 2 x 4+4-pin PCI-E: 3 x 8-pin (dùng cho card đồ họa) SATA: 6 cổng (hỗ trợ ổ cứng, SSD, thiết bị lưu trữ) Peripheral (Molex): 3 cổng (hỗ trợ quạt, thiết bị cũ) Trọng lượng PSU : 2.2KG Product Weight (with packing) : 3.067KG &nbsp; ASUS PRIME 750B &nbsp;là bộ nguồn phổ thông đáng tin cậy đến từ thương hiệu ASUS, đáp ứng tốt nhu cầu sử dụng cho các cấu hình máy tính tầm trung. Với&nbsp; công suất 750W ,&nbsp; chuẩn hiệu suất 80 Plus Bronze , thiết kế&nbsp; non-modular đơn giản , cùng thời gian&nbsp; bảo hành 6 năm chính hãng , đây là lựa chọn lý tưởng cho người dùng muốn sở hữu một bộ nguồn ổn định, bền bỉ với chi phí hợp lý. Công suất 750W – Đáp ứng tốt các cấu hình gaming hoặc làm việc tầm trung Với mức công suất danh định&nbsp; 750W , PRIME 750B dễ dàng cấp nguồn cho các hệ thống gồm: VGA tầm trung đến cao &nbsp;như RTX 4060, 3060Ti hoặc RX 6700 XT, CPU Intel Core i5/i7 hoặc AMD Ryzen 5/7 , Các linh kiện phụ trợ như SSD, HDD, tản nhiệt khí, quạt LED... Điện áp đầu ra đầy đủ:&nbsp; +3.3V, +5V, +12V, -12V, +5Vsb , đảm bảo cung cấp điện ổn định cho các thành phần trong suốt quá trình vận hành. Chứng nhận 80 Plus Bronze – Hiệu suất ổn định, tiết kiệm điện Nguồn đạ', '{"Asus":"72 tháng","750W":"Non Modular","80 Plus Bronze":"Đen","150 x 150 x 86 mm":"100-240Vac","+3.3V +5V +12V -12V +5Vsb":"OPP/OVP/UVP/SCP/OCP/OTP"}', 0, 1);
