INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074838602', 'SP1083670', '1074838602', 'https://www.maytinhbienhoa.vn/products/nguon-asus-750w-tuf-gaming-750b-evo-plus-bronze', 'NGUỒN ASUS 750W TUF GAMING 750B EVO PLUS BRONZE', 'nguon-asus-750w-tuf-gaming-750b-evo-plus-bronze', 'brand_asus_316', 'cat_psu', 1750000, 1750000, 0, 1400000, 24, 'in_stock', 'NGUỒN ASUS 750W TUF GAMING 750B EVO PLUS BRONZE', 'THÔNG SỐ KỸ THUẬT &nbsp; Thương hiệu Asus Bảo hành 72 tháng Công suất tối đa 750W Kiểu dây nguồn Full Modular Hiệu suất 80 Plus Bronze Màu sắc Đen Kích thước nguồn 140 x 150 x 86 mm Hệ thống bảo vệ OPP / OVP / UVP / SCP / OCP / OTP Cổng kết nối MB 24/20-pin x 1 CPU 4+4-pin x 2 PCI-E 6+2-pin x 3 SATA x 4 PERIPHERAL x 2 Trọng lượng 1.411 KG (Single PSU) Nguồn máy tính ASUS TUF Gaming 750W Bronze EVO (TUF-GAMING-750B-EVO) – Hiệu suất ổn định, độ bền chuẩn TUF ASUS TUF Gaming 750W Bronze EVO (TUF-GAMING-750B-EVO) &nbsp;là bộ nguồn máy tính được thiết kế dành cho các hệ thống PC gaming và workstation yêu cầu nguồn điện ổn định, bền bỉ. Thuộc dòng TUF Gaming nổi tiếng của ASUS, sản phẩm tập trung vào độ ổn định lâu dài, khả năng bảo vệ toàn diện và hiệu suất tối ưu cho hệ thống. Với công suất thực 750W cùng chứng nhận 80 Plus Bronze, đây là lựa chọn phù hợp cho các cấu hình sử dụng card đồ họa rời và nhiều thiết bị phần cứng hiện đại. Hiệu suất ổn định với chuẩn 80 Plus Bronze Nguồn ASUS TUF Gaming 750W Bronze EVO đạt chứng nhận&nbsp; 80 Plus Bronze , giúp tối ưu hiệu suất chuyển đổi điện năng và giảm hao phí điện. Điều này không chỉ giúp hệ thống hoạt động ổn định mà còn góp phần giảm nhiệt lượng và tiết kiệm điện năng trong quá trình sử dụng lâu dài. Bộ nguồn sử dụng&nbsp; Active PFC (Power Factor Correction) , giúp ổn định dòng điện đầu vào và tối ưu khả năng cung cấp điện cho toàn bộ hệ thống. Dải điện áp đầu vào rộng&nbsp; 100 – 240V &nbsp;cho phép nguồn hoạt động ổn định ', '{"Asus":"72 tháng","750W":"Full Modular","80 Plus Bronze":"Đen","140 x 150 x 86 mm":"OPP / OVP / UVP / SCP / OCP / OTP"}', 0, 1);
