INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1072894166', 'SP1083237', '1072894166', 'https://www.maytinhbienhoa.vn/products/nguon-1st-player-850w-ack-gld-850-den-80-plus-gold', 'NGUỒN 1ST PLAYER 850w ACK-GLD-850 ĐEN (80 PLUS GOLD)', 'nguon-1st-player-850w-ack-gld-850-den-80-plus-gold', 'brand_1st-player_709', 'cat_psu', 2390000, 2890000, 17, 1912000, 24, 'in_stock', 'NGUỒN 1ST PLAYER 850w ACK-GLD-850 ĐEN (80 PLUS GOLD)', 'THÔNG SỐ KỸ THUẬT - Công suất: 850W - Hiệu suất: 91.42% ở mức tải điển hình - Chứng nhận: 80 PLUS GOLD, Cybenetics Gold, PPLP Gold - Đạt tiêu chuẩn ATX 3.1 &amp; PCIe 5.1 - Độ bền: 50.000 giờ - Quạt: FDB, đường kính 140mm - Chuẩn kích thước: ATX - Loại cáp: Dây cáp dập nổi bền bỉ - Kết nối: 24PINx1/ P8(4+4)x2/ 12V (12+4PIN)x1/PCl-E P8(6+2)x3/ (SATA+SATA+IDE)x2 - Kích thước: 145 x 150 x 86 mm - Phụ kiện đi kèm: 1 dây nguồn chuẩn EU + 4 ốc bắt nguồn + 10 cable tie(dây rút) + 4 dây dán velcro + 1 sách hướng dẫn sử dụng &nbsp; NGUỒN 1ST PLAYER ACK-GLD-850 850W ĐEN (80 PLUS GOLD) | Full Modular | ATX 3.1 | PCIe 5.1 | Fan FDB 140mm Nâng cấp hệ thống PC Gaming và Workstation với nguồn 1ST PLAYER ACK-GLD-850 850W sở hữu chứng nhận 80 PLUS Gold , mang lại hiệu suất chuyển đổi điện năng lên đến hơn 91%, giúp tiết kiệm điện và vận hành ổn định. Thiết kế Full Modular giúp tối ưu việc đi dây, tăng tính thẩm mỹ và cải thiện luồng gió trong thùng máy. Sản phẩm hỗ trợ ATX 3.1 và PCIe 5.1 , sẵn sàng cấp nguồn cho các dòng card đồ họa thế hệ mới thông qua đầu cấp nguồn 12V-2x6 (12VHPWR) . Bên cạnh đó, mạch nguồn LLC + DC-DC , tụ điện Teapo , quạt FDB 140mm hoạt động êm ái cùng đầy đủ các cơ chế bảo vệ như OVP, OPP, SCP, OCP, OTP, UVP giúp hệ thống vận hành bền bỉ và an toàn trong thời gian dài. Ưu điểm nổi bật: Công suất thực 850W , đáp ứng cấu hình Gaming và Workstation cao cấp. Chứng nhận 80 PLUS Gold , hiệu suất trên 91% ở mức tải điển hình. Full Modular , dễ dàng quản lý dây cáp và tối ưu ', '{"Tích hợp đầy đủ các tính năng bảo vệ":"OVP / OPP / SCP / OCP / OTP / UVP."}', 0, 1);
