INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1071123977', 'SP1082831', '1071123977', 'https://www.maytinhbienhoa.vn/products/case-mik-g8-nova-x-atx-tran-kinh-no-fan', 'CASE MIK G8 Nova X (F-ATX) Trần Kính (NO Fan)', 'case-mik-g8-nova-x-atx-tran-kinh-no-fan', 'brand_mik_225', 'cat_case', 1049000, 1049000, 0, 839200, 24, 'in_stock', 'CASE MIK G8 Nova X (F-ATX) Trần Kính (NO Fan)', 'Thông số kỹ thuật &nbsp; Cạnh trước Kính cường lực Cạnh trái Kính cường lực Cạnh phải Thép Màu sắc Đen EAN Code 8938529122410 Cổng cắm 1x USB 3.0 1x USB 2.0 1x Cổng âm thanh HD Audio 1x Cổng Microphone Phía trên Kính cường lực Vị trí nguồn - kích thước Hộc riêng - ATX 160mm Kích thước Motherboard hỗ trợ ATX / M-ATX / ITX Quạt Phía dưới: 2x 120mm Phía hông: 3x 120mm Phía sau: 1x 120mm Hỗ trợ ổ cứng 1x 3.5" 2x 2.5" Kích thước 339 x 275 x 394mm (D*W*H) Radiator support: Cạnh hông: 240mm Max.VGA Card: 330mm Max. CPU Cooler: 155mm Max.PSU length: 160mm &nbsp; MIK G8 NOVA X – Không Gian Toàn Cảnh Mở Rộng Cho Hệ Thống ATX Đỉnh Cao Đáp lại sự mong đợi của cộng đồng yêu công nghệ, MIK tự hào giới thiệu G8 NOVA X – phiên bản ATX kế thừa và nâng tầm thiết kế "bể cá" trứ danh từ người anh em G8 NOVA M. Với kích thước lớn hơn, không gian nội thất vượt trội và khả năng tản nhiệt được tăng cường, G8 NOVA X chính là khung vẽ hoàn hảo cho những ai muốn xây dựng một hệ thống ATX mạnh mẽ mà không phải hy sinh bất kỳ yếu tố thẩm mỹ nào. Sân Khấu Trình Diễn Hoành Tráng Cho Linh Kiện ATX MIK G8 NOVA X vẫn giữ nguyên DNA thiết kế đã làm nên thành công của dòng sản phẩm: cấu trúc ba mặt kính cường lực trong suốt ở mặt trước, mặt hông và nóc case. Tuy nhiên, với kích thước được mở rộng lên 339 x 275 x 394mm, không gian trưng bày giờ đây trở nên hoành tráng và ấn tượng hơn bao giờ hết. Toàn bộ vẻ đẹp của bo mạch chủ ATX full-size, những card đồ họa hàng đầu hay các hệ thống tản nhiệt nước custom phức ', '{"Cạnh trước":"Kính cường lực","Cạnh trái":"Kính cường lực","Cạnh phải":"Thép","Màu sắc":"Đen","EAN Code":"8938529122410","Cổng cắm":"1x USB 3.0 1x USB 2.0 1x Cổng âm thanh HD Audio 1x Cổng Microphone","Phía trên":"Kính cường lực","Vị trí nguồn - kích thước":"Hộc riêng - ATX 160mm","Kích thước Motherboard hỗ trợ":"ATX / M-ATX / ITX","Quạt":"Phía dưới: 2x 120mm Phía hông: 3x 120mm Phía sau: 1x 120mm","Hỗ trợ ổ cứng":"1x 3.5\\" 2x 2.5\\"","Kích thước":"339 x 275 x 394mm (D*W*H)"}', 0, 1);
