INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1073417618', 'SP1083355', '1073417618', 'https://www.maytinhbienhoa.vn/products/bo-tan-nhiet-nuoc-id-cooling-fx360-td-argb', 'BỘ TẢN NHIỆT NƯỚC ID-COOLING FX360 TD ARGB', 'bo-tan-nhiet-nuoc-id-cooling-fx360-td-argb', 'brand_id-cooling_709', 'cat_cooling', 1690000, 1690000, 0, 1352000, 24, 'in_stock', 'BỘ TẢN NHIỆT NƯỚC ID-COOLING FX360 TD ARGB', 'THÔNG SỐ KỸ THUẬT &nbsp; Thông số Chi tiết Tương thích Intel LGA1851 / 1700 / 1200 / 115XAMD AM5 / AM4 TDP hỗ trợ 350W Kích thước Radiator 396 × 120 × 27 mm Chất liệu Radiator Nhôm Chất liệu ống dẫn Ống bọc lưới cao cấp (Premium Sleeved Tubing) Chiều dài ống 420 mm Kích thước Waterblock 73 × 69 × 57 mm Chất liệu đế tiếp xúc Đồng Dòng điện bơm Tối đa 0.45A Tốc độ bơm 2900 RPM ±10% (PWM) Vòng bi bơm Ceramic Bearing (vòng bi gốm) Tuổi thọ bơm 50.000 giờ Độ ồn bơm 25 dB(A) Model quạt AS-120-ARGB V2 Kích thước quạt 120 × 120 × 25 mm Số lượng quạt đi kèm 3 cái Tốc độ quạt 300 ~ 2000 RPM ±10% Lưu lượng gió tối đa 58 CFM Áp suất tĩnh tối đa 1.94 mmH2O Độ ồn quạt Tối đa 27.2 dB(A) Điện áp định mức 12VDC Điện áp hoạt động 10.8 ~ 13.2VDC Điện áp khởi động 7VDC Dòng điện định mức 0.15A Công suất tiêu thụ 1.8W Loại vòng bi quạt Hydraulic Bearing (vòng bi thủy lực) Đầu kết nối 7-pin (4-pin PWM + 5V 3-pin ARGB) &nbsp; &nbsp; Trong những năm gần đây, nhu cầu build PC gaming và workstation hiệu năng cao ngày càng tăng mạnh, kéo theo yêu cầu khắt khe hơn về hệ thống làm mát. CPU thế hệ mới từ Intel và AMD có mức tiêu thụ điện năng lớn, sinh nhiệt cao khi hoạt động ở cường độ tối đa. Chính vì vậy, việc lựa chọn một bộ tản nhiệt nước 360mm chất lượng là yếu tố quan trọng giúp duy trì hiệu suất ổn định lâu dài.&nbsp;Tản nhiệt nước ID-COOLING FX360 TD Black&nbsp;là giải pháp làm mát toàn diện, kết hợp giữa hiệu năng mạnh mẽ, thiết kế ARGB hiện đại và khả năng tương thích đa nền tảng. &nbsp; Tản Nh', '{"Tương thích":"Intel LGA1851 / 1700 / 1200 / 115XAMD AM5 / AM4","TDP hỗ trợ":"350W","Kích thước Radiator":"396 × 120 × 27 mm","Chất liệu Radiator":"Nhôm","Chất liệu ống dẫn":"Ống bọc lưới cao cấp (Premium Sleeved Tubing)","Chiều dài ống":"420 mm","Kích thước Waterblock":"73 × 69 × 57 mm","Chất liệu đế tiếp xúc":"Đồng","Dòng điện bơm":"Tối đa 0.45A","Tốc độ bơm":"2900 RPM ±10% (PWM)","Vòng bi bơm":"Ceramic Bearing (vòng bi gốm)","Tuổi thọ bơm":"50.000 giờ"}', 0, 1);
