INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1071449513', 'SP1082922', '1071449513', 'https://www.maytinhbienhoa.vn/products/tan-nhiet-nuoc-leopard-pro-flow-360-argb-lcd-den', 'Tản nhiệt nước Leopard Pro Flow 360 ARGB LCD | Đen', 'tan-nhiet-nuoc-leopard-pro-flow-360-argb-lcd-den', 'brand_jungle-leopard_1004', 'cat_cooling', 2690000, 2690000, 0, 2152000, 24, 'in_stock', 'Tản nhiệt nước Leopard Pro Flow 360 ARGB LCD | Đen', 'THÔNG SỐ KỸ THUẬT Màn hình LCD: 5.5 inch HD, độ phân giải 960×480&nbsp; Xoay màn hình 270° (các góc 90°/180°/270°), thích hợp mọi case&nbsp; Tốc độ quạt: 800 – 2000 RPM ±10%&nbsp; Tốc dộ bơm: 2700 RPM ±10%&nbsp; Công suất tản nhiệt TDP lên tới 320W&nbsp; Socket hỗ trợ Intel: LGA 115X / 1700 / 1851 – AMD: AM4 / AM5&nbsp; Phần mềm điều khiển Tùy chỉnh ảnh, video, gif, logo, theo dõi nhiệt độ, RGB&nbsp; Thiết kế đèn bơm RGB vòng kép trong suốt – màu sắc tinh tế, đồng bộ&nbsp; Quạt đi kèm 3x 120mm với viền RGB hình tam giác vô cực Bảo hành 12 Tháng Tản Nhiệt Nước Leopard Pro Flow 360 Black Tản nhiệt nước Leopard Pro Flow 360 là một giải pháp làm mát hiệu quả và hiện đại, mang lại sự ổn định và hiệu năng vượt trội cho hệ thống PC của bạn. Thiết kế ấn tượng Trang bị radiator kích thước &nbsp; 360mm, Leopard Pro Flow 360 mang lại khả năng tản nhiệt vượt trội, phù hợp cho các bộ vi xử lý cao cấp thường xuyên hoạt động ở mức tải nặng. Hệ thống ống dẫn nước chất lượng cao đảm bảo lưu thông ổn định, giữ nhiệt độ CPU luôn ở mức tối ưu ngay cả khi ép xung. Điểm nhấn độc đáo của &nbsp; Tản nước Leopard Pro Flow 360 LED RGB màn hình LCD Black chính là màn hình LCD được tích hợp ngay trên bơm. Màn hình này cho phép hiển thị thông tin quan trọng như nhiệt độ CPU, tốc độ quạt hoặc logo và hình ảnh tùy chỉnh. Đây là tính năng cao cấp, mang lại sự hiện đại và cá nhân hóa cho hệ thống. Sản phẩm sử dụng bơm thế hệ mới với độ ồn thấp, đảm bảo hoạt động êm ái ngay cả khi hệ thống vận hành ở mức tải ', '{"Màn hình LCD":"5.5 inch HD, độ phân giải 960×480&nbsp;","Tốc độ quạt":"800 – 2000 RPM ±10%&nbsp;","Tốc dộ bơm":"2700 RPM ±10%&nbsp;","Socket hỗ trợ Intel":"LGA 115X / 1700 / 1851 – AMD: AM4 / AM5&nbsp;"}', 0, 1);
