INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1069762727', 'SP1082552', '1069762727', 'https://www.maytinhbienhoa.vn/products/tan-nhiet-nuoc-jonsbo-th-360-aio-black-argb-hien-thi-nhiet-do', 'Tản Nhiệt Nước Jonsbo TH-360 AIO Black (ARGB, Hiển Thị Nhiệt Độ)', 'tan-nhiet-nuoc-jonsbo-th-360-aio-black-argb-hien-thi-nhiet-do', 'brand_jonsbo_459', 'cat_cooling', 1790000, 1790000, 0, 1432000, 24, 'in_stock', 'Tản Nhiệt Nước Jonsbo TH-360 AIO Black (ARGB, Hiển Thị Nhiệt Độ)', 'Jonsbo TH-360 Black &nbsp;là dòng&nbsp;tản nhiệt nước AIO&nbsp;mạnh mẽ được thiết kế để đáp ứng nhu cầu làm mát tối đa cho các hệ thống PC hiệu năng cao. Với bộ tản nhiệt kích thước lớn, quạt hiệu suất cao và khả năng vận hành êm ái, mẫu&nbsp;tản nhiệt nước Jonsbo&nbsp;này giúp CPU luôn giữ ở nhiệt độ ổn định ngay cả trong những tác vụ nặng nhất. Hiệu suất làm mát mạnh mẽ Jonsbo TH-360 Black &nbsp;sở hữu bộ tản nhiệt lớn với kích thước 393mm x 120mm x 27mm, kết hợp cùng ba quạt mạnh mẽ kích thước 362mm x 123mm x 28mm. Tốc độ quạt từ 700-2400 vòng/phút (±10%), mang lại khả năng làm mát vượt trội với lưu lượng gió đạt 21.46-62.40 CFM mỗi quạt. Vòng bi thủy lực giúp quạt hoạt động êm ái và bền bỉ theo thời gian. Độ ồn thấp từ 21.3 đến 37.3 dB(A) giúp bạn làm việc và giải trí trong môi trường yên tĩnh. Bơm tốc độ cao 2400 vòng/phút (±10%) giữ cho luồng nước lưu thông ổn định, đảm bảo khả năng tản nhiệt tối ưu với độ ồn của bơm dưới 30 dB(A). Thiết kế đen huyền bí và chắc chắn Sở hữu thiết kế tông màu đen mạnh mẽ,&nbsp; Jonsbo TH-360 Black &nbsp;mang đến vẻ ngoài hiện đại và chuyên nghiệp cho mọi dàn PC. Bộ bơm nhỏ gọn với kích thước 72mm x 85.3mm x 57.5mm phù hợp với nhiều kiểu case khác nhau, dễ dàng lắp đặt và sắp xếp. Điều chỉnh thông minh và tối ưu hóa luồng khí Tản nhiệt nước này được trang bị đầu nối 4-pin PWM, cho phép bạn điều chỉnh tốc độ quạt linh hoạt để cân bằng giữa hiệu suất làm mát và độ yên tĩnh. Khả năng tương thích đa dạng Jonsbo TH-360 Black &nbsp;hỗ trợ nhiều ', '{"Intel":"LGA 1200, 115X, 17XX, 1851","AMD":"AM4, AM5"}', 0, 1);
