INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1020788468', 'SP005903', '1020788468', 'https://www.maytinhbienhoa.vn/products/tan-nhiet-nuoc-id-cooling-dashflow-360-led-rgb-premium-design-water-cooler-super-performance-360mm-radiator-df-fan-intel-amd', 'TẢN NHIỆT NƯỚC ID-COOLING DASHFLOW 360 ( Led RGB, Premium Design Water Cooler, Super Performance, 360mm Radiator, DF Fan, Intel&AMD )', 'tan-nhiet-nuoc-id-cooling-dashflow-360-led-rgb-premium-design-water-cooler-super-performance-360mm-radiator-df-fan-intel-amd', 'brand_idcooling_664', 'cat_cooling', 3490000, 3690000, 5, 2792000, 24, 'out_of_stock', 'TẢN NHIỆT NƯỚC ID-COOLING DASHFLOW 360 ( Led RGB, Premium Design Water Cooler, Super Performance, 360mm Radiator, DF Fan, Intel&AMD )', 'ĐẶC ĐIỂM NỔI BẬT ✔️&nbsp; Đồng bộ led &nbsp; R G B &nbsp; với main board bằng phần mềm: &nbsp; AURA SYNC, MYSTIC LIGHT SYNC, RGB FUSION ✔️&nbsp; Trang bị đèn led&nbsp; R G B&nbsp; ở cả PUMB và FAN ✔️&nbsp; Ống đồng tản nhiệt tối ưu nhất ✔️&nbsp; Máy bơm công suất cao, tối ưu cho việc lưu thông dòng chảy ✔️&nbsp; Ống dẫn được bọc dù bền bỉ theo thời gian ✔️&nbsp; Hỗ trợ đa dạng socket CPU từ &nbsp; INTEL &nbsp; và &nbsp; AMD THÔNG SỐ KỸ THUẬT Socket tương thích &nbsp;Intel LGA2066/2011-3/2011/1366/1151/1150/1155/1156 &nbsp;AMD TR4/AM4/FM2+/FM2/FM1/AM3+/AM3/AM2+/AM2 &nbsp;Điện áp &nbsp;350W &nbsp;Kích thước radiator&nbsp; &nbsp;396×120×27mm &nbsp;Chất liệu Radiator &nbsp;Nhôm &nbsp;Chất liệu ống dẫn &nbsp;Bọc dù cao cấp &nbsp;Chiều dài ống &nbsp;465mm &nbsp;Kích thước Waterblock &nbsp;84×84×46.5mm &nbsp;Chất liệu Cold Plate &nbsp;Đồng &nbsp;Điện áp máy bơm &nbsp;0.45A &nbsp;Tốc độ máy bơm &nbsp;2400RPM &nbsp;Chất liệu vòng bi &nbsp;Gốm &nbsp;Tuổi thọ ống bơm &nbsp;50,000 Hrs &nbsp;Độ ồn &nbsp;25dB(A) &nbsp;Kích thước fan &nbsp;120×120×25mm &nbsp;Số fan hỗ trợ &nbsp;3pcs &nbsp;Tốc độ quạt &nbsp;900～2000RPM &nbsp;Lượng gió lưu thông tố đa &nbsp;56.5CFM(1 Fan) &nbsp;Áp suất nước tối đa &nbsp;1.99mmH2O &nbsp;Độ ồn &nbsp;16～31.5dB(A) &nbsp;Điện áp định mức &nbsp;12VDC &nbsp;Điện áp hoạt động &nbsp;10.8～13.2VDC Điện áp bắt đầu &nbsp;7VDC &nbsp;Rated Current &nbsp;0.25A &nbsp;Nguồn đầu vào &nbsp;3W', '{"Socket tương thích":"&nbsp;Intel LGA2066/2011-3/2011/1366/1151/1150/1155/1156","&nbsp;AMD TR4/AM4/FM2+/FM2/FM1/AM3+/AM3/AM2+/AM2":"&nbsp;Điện áp","&nbsp;Kích thước radiator&nbsp;":"&nbsp;396×120×27mm","&nbsp;Chất liệu Radiator":"&nbsp;Nhôm","&nbsp;Chất liệu ống dẫn":"&nbsp;Bọc dù cao cấp","&nbsp;Chiều dài ống":"&nbsp;465mm","&nbsp;Kích thước Waterblock":"&nbsp;84×84×46.5mm","&nbsp;Chất liệu Cold Plate":"&nbsp;Đồng","&nbsp;Điện áp máy bơm":"&nbsp;0.45A","&nbsp;Tốc độ máy bơm":"&nbsp;2400RPM","&nbsp;Chất liệu vòng bi":"&nbsp;Gốm","&nbsp;Tuổi thọ ống bơm":"&nbsp;50,000 Hrs"}', 0, 1);
