INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1023625890', 'SP007541', '1023625890', 'https://www.maytinhbienhoa.vn/products/tan-nhiet-nuoc-id-cooling-zoomflow-360x-snow', 'TẢN NHIỆT NƯỚC ID-COOLING ZOOMFLOW 360X SNOW', 'tan-nhiet-nuoc-id-cooling-zoomflow-360x-snow', 'brand_id-cooling_709', 'cat_cooling', 2790000, 2990000, 7, 2232000, 24, 'out_of_stock', 'TẢN NHIỆT NƯỚC ID-COOLING ZOOMFLOW 360X SNOW', 'Chỉ 1,890,000đ khi Build kèm máy bộ bất kỳ (hoặc mua từ 3 thành phần trở lên: Case, Main, CPU,...) &nbsp; -&nbsp; Đồng bộ led&nbsp; ARGB &nbsp;với main board bằng phần mềm:&nbsp; AURA SYNC, MYSTIC LIGHT SYNC, RGB FUSION… -&nbsp; Trang bị đèn led&nbsp; A RGB&nbsp; ở cả PUMB và FAN -&nbsp; Bề mặt&nbsp;đồng tản nhiệt tối ưu nhất -&nbsp; Máy bơm 7 cánh 3 pha công suất mạnh&nbsp; áp lực nước đến 1.8m -&nbsp; Ống dẫn được bọc dù tăng cường thêm lớp phủ bảo vệ bền bỉ theo thời gian -&nbsp; Hỗ trợ đa dạng socket CPU từ&nbsp;INTEL&nbsp;và&nbsp;AMD Thông số tản :&nbsp; TẢN NHIỆT NƯỚC ID-COOLING ZOOMFLOW 360X SNOW đến từ thương hiệu&nbsp; TẢN NHIỆT ID-COOLING Tương thích &nbsp;Intel LGA2066/2011/1366/1151/1150/1155/1156 &nbsp;AMD TR4/AM4/FM2+/FM2/FM1/AM3+/AM3/AM2+/AM2 &nbsp;TDP &nbsp;350W &nbsp;kích thước Rad &nbsp;397×120×27mm &nbsp;Chất liệu Rad &nbsp;Aluminum &nbsp;Chất liệu ống &nbsp;Premium Sleeved Tubing &nbsp;Độ dài ống &nbsp;465mm &nbsp;Kích thước block nước &nbsp;72x72x52mm &nbsp;C hất liệ u&nbsp; Cold Plate&nbsp; &nbsp;Copper &nbsp;Điện áp Pump &nbsp;0.36A &nbsp;Tốc độ Pump &nbsp;2100±10%RPM &nbsp; Chất liệu vòng bi &nbsp;Ceramic Bearing &nbsp; Tuổi thọ Pump &nbsp;50,000 Hrs &nbsp; Độ ồn Pump &nbsp;25dB(A) &nbsp;Kích thước quạt &nbsp;120×120×25mm &nbsp;Quạt bao gồm &nbsp;3pcs &nbsp; Tốc độ quạt &nbsp;700～1500±10%RPM &nbsp;Max luồn khí &nbsp;62CFM &nbsp;Max&nbsp; áp suất không khí &nbsp;1.78mmH2O &nbsp;Độ ồn &nbsp;18～26.4dB(A) &nbsp;Điện áp định mức &nbsp;12VDC &nbsp;Điện áp ho', '{"Tương thích":"&nbsp;Intel LGA2066/2011/1366/1151/1150/1155/1156","&nbsp;AMD TR4/AM4/FM2+/FM2/FM1/AM3+/AM3/AM2+/AM2":"&nbsp;TDP","&nbsp;kích thước Rad":"&nbsp;397×120×27mm","&nbsp;Chất liệu Rad":"&nbsp;Aluminum","&nbsp;Chất liệu ống":"&nbsp;Premium Sleeved Tubing","&nbsp;Độ dài ống":"&nbsp;465mm","&nbsp;Kích thước block nước":"&nbsp;72x72x52mm","&nbsp;C hất liệ u&nbsp; Cold Plate&nbsp;":"&nbsp;Copper","&nbsp;Điện áp Pump":"&nbsp;0.36A","&nbsp;Tốc độ Pump":"&nbsp;2100±10%RPM","&nbsp; Chất liệu vòng bi":"&nbsp;Ceramic Bearing","&nbsp; Tuổi thọ Pump":"&nbsp;50,000 Hrs"}', 0, 1);
