INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1073522468', 'SP1083396', '1073522468', 'https://www.maytinhbienhoa.vn/products/man-hinh-vsp-ip2408sg-24-fhd-120hz-ips-vien-sieu-mong', 'MÀN HÌNH VSP IP2408SG 24" FHD 120Hz IPS VIỀN SIÊU MỎNG', 'man-hinh-vsp-ip2408sg-24-fhd-120hz-ips-vien-sieu-mong', 'brand_vsp_249', 'cat_monitors', 1649000, 2450000, 33, 1319200, 24, 'in_stock', 'MÀN HÌNH VSP IP2408SG 24" FHD 120Hz IPS VIỀN SIÊU MỎNG', 'Thông số kỹ thuật Mã sản phẩm IP2408SG Màu sắc Đen (Black) Kích cỡ màn hình 23.8 inch (Phẳng) Độ phân giải Full HD (1920 x 1080 px) Tần số quét 120Hz Tấm nền IPS Độ sáng 300 cd/m² (Max) Độ tương phản 1000:1 Màu sắc hiển thị 16.7 Triệu màu Độ phủ màu (Gamut) 103% sRGB Góc nhìn 178° (H) / 178° (V) Tốc độ phản hồi 1ms (MPRT) Cổng kết nối HDMI 2.0 x 1 VGA x 1 Góc nghiêng (Tilt) -5° ~ +15° Chuẩn gắn VESA 75 x 75 mm Nguồn cấp DC 12V - 2.5A Kích thước 540 x 145 x 413 mm Trọng lượng Net: &nbsp;2.6 Kg Gross: &nbsp;3.7 Kg Bảo hành 3 Năm Tính năng đặc biệt 1. HDR Support 2. FreeSync / AdaptiveSync 3. Shadow Boost (Chống bóng mờ) 4. E-book Mode &amp; ECO Mode 5. Flicker-Free (Chống nháy) &nbsp; &nbsp; MÔ TẢ SẢN PHẨM &nbsp; &nbsp; VSP IP2408SG – Màn hình gaming phổ thông hướng đến trải nghiệm mượt mà và dễ tiếp cận VSP IP2408SG là mẫu màn hình gaming 24 inch được định vị cho người dùng phổ thông cần hình ảnh rõ ràng, chuyển động mượt và mức chi phí hợp lý. Sản phẩm tập trung vào những yếu tố quan trọng trong trải nghiệm chơi game hằng ngày như tần số quét cao, phản hồi nhanh và màu sắc dễ nhìn. Với thiết kế phẳng gọn gàng và thông số cân đối, IP2408SG phù hợp cho cả gaming lẫn sử dụng máy tính đa mục đích. &nbsp; &nbsp; &nbsp; Độ phân giải Full HD hiển thị rõ ràng và dễ quan sát Màn hình Gaming VSP IP2408SG sở hữu độ phân giải Full HD 1920 x 1080, phù hợp với kích thước 23.8 inch để đảm bảo hình ảnh hiển thị sắc nét và không bị rỗ điểm ảnh. Nội dung trong game, văn bản và giao diện hệ điề', '{"Mã sản phẩm":"IP2408SG","Màu sắc":"Đen (Black)","Kích cỡ màn hình":"23.8 inch (Phẳng)","Độ phân giải":"Full HD (1920 x 1080 px)","Tần số quét":"120Hz","Tấm nền":"IPS","Độ sáng":"300 cd/m² (Max)","Độ tương phản":"1000:1","Màu sắc hiển thị":"16.7 Triệu màu","Độ phủ màu (Gamut)":"103% sRGB","Góc nhìn":"178° (H) / 178° (V)","Tốc độ phản hồi":"1ms (MPRT)"}', 0, 1);
