INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1076653114', 'SP1084163', '1076653114', 'https://www.maytinhbienhoa.vn/products/man-hinh-edra-egm24f120h-24-fhd-ips-120hz-1ms-vien-sieu-mong', 'MÀN HÌNH EDRA EGM24F120H 24" FHD IPS 120Hz 1ms VIỀN SIÊU MỎNG', 'man-hinh-edra-egm24f120h-24-fhd-ips-120hz-1ms-vien-sieu-mong', 'brand_e-dra_329', 'cat_monitors', 1650000, 1650000, 0, 1320000, 24, 'in_stock', 'MÀN HÌNH EDRA EGM24F120H 24" FHD IPS 120Hz 1ms VIỀN SIÊU MỎNG', 'THÔNG SỐ KỸ THUẬT Thương hiệu EDra Bảo hành 24 tháng Kích cỡ 23.8 inch Kiểu màn hình Màn hình phẳng Độ phân giải FHD (1920 x 1080) Tỷ lệ khung hình 16:9 Tấm nền IPS Màu sắc màn hình 16.7M Độ sáng màn hình 280 Nits Độ tương phản 1300:1 Tần số quét 120Hz Thời gian phản hồi 1 ms Cổng kết nối màn hình 1 x HDMI, 1 x VGA Vesa 100 x 100 mm Phân loại màn hình Gaming &nbsp; &nbsp; Mô tả Màn hình E-Dra EGM24F120H 23.8 inch FHD IPS 120Hz 1ms – Mượt mà, sắc nét và đa dụng cho mọi nhu cầu E-Dra EGM24F120H là mẫu màn hình được thiết kế để mang lại trải nghiệm hình ảnh vượt trội trong cả công việc và giải trí. Sở hữu kích thước 23.8 inch , độ phân giải Full HD (1920 x 1080) cùng tấm nền IPS cao cấp , sản phẩm không chỉ hiển thị sắc nét mà còn tái tạo màu sắc trung thực, mang đến khung hình sống động ở mọi góc nhìn. 1. Chất lượng hiển thị ấn tượng với tấm nền IPS Màn hình IPS của E-Dra EGM24F120H mang đến khả năng hiển thị 16.7 triệu màu , đảm bảo độ chính xác và độ sâu màu sắc cao. Góc nhìn rộng 178° cho phép bạn quan sát rõ ràng từ mọi vị trí mà không lo hiện tượng biến màu. Độ sáng 280 nits kết hợp độ tương phản 1300:1 giúp hình ảnh rõ rệt và nổi bật, ngay cả khi sử dụng trong môi trường có ánh sáng phức tạp. 2. Tốc độ mượt mà với 120Hz và 1ms Điểm mạnh của E-Dra EGM24F120H nằm ở tần số quét 120Hz cùng thời gian phản hồi 1ms , giúp loại bỏ hiện tượng giật lag và bóng mờ, mang lại trải nghiệm hình ảnh mượt mà khi xem video, lướt web hoặc chơi game. Đặc biệt, tốc độ phản hồi siêu nhan', '{"EDra":"24 tháng","23.8 inch":"Màn hình phẳng","FHD (1920 x 1080)":"16:9","IPS":"16.7M","280 Nits":"1300:1","120Hz":"1 ms","1 x HDMI, 1 x VGA":"100 x 100 mm"}', 0, 1);
