INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1070042712', 'SP1082637', '1070042712', 'https://www.maytinhbienhoa.vn/products/man-hinh-edra-egm24f120s-24-fhd-ips-120hz-1ms-vien-mong', 'MÀN HÌNH EDRA EGM24F120S 24" FHD IPS 120Hz 1ms VIỀN MỎNG', 'man-hinh-edra-egm24f120s-24-fhd-ips-120hz-1ms-vien-mong', 'brand_edra_412', 'cat_monitors', 1650000, 1650000, 0, 1320000, 24, 'in_stock', 'MÀN HÌNH EDRA EGM24F120S 24" FHD IPS 120Hz 1ms VIỀN MỎNG', 'Thông số kỹ thuật Model E-Dra EGM24F120S Kích thước màn hình 23.8 inch, phẳng Độ phân giải Full HD (1920×1080) Tấm nền IPS, hiển thị 16.7 triệu màu Độ sáng 280 nits Độ tương phản 1300:1 Tần số quét 120Hz Thời gian phản hồi 1ms &nbsp; &nbsp; Màn hình E-Dra EGM24F120S 24 inch FHD IPS 120Hz 1ms | Giá rẻ, Hiển thị mượt mà Màn hình E-Dra EGM24F120S&nbsp; là mẫu màn hình phẳng&nbsp; 24 inch Full HD IPS , thiết kế hiện đại, viền mỏng, mang lại trải nghiệm hiển thị mượt mà cho cả&nbsp; công việc, giải trí và chơi game . Với&nbsp; tần số quét 120Hz, thời gian phản hồi 1ms &nbsp;cùng tấm nền IPS cao cấp, màn hình cho chất lượng hình ảnh sắc nét, màu sắc sống động và chuyển động cực kỳ mượt mà. Ưu điểm Màn hình E-Dra EGM24F120S Hiển thị sắc nét – trung thực : Độ phân giải Full HD 1920×1080, tấm nền IPS hiển thị 16.7 triệu màu, góc nhìn rộng 178°. Mượt mà vượt trội : Tần số quét 120Hz, thời gian phản hồi chỉ 1ms, loại bỏ hiện tượng giật lag và bóng mờ. Thiết kế hiện đại : Viền mỏng tinh tế, phù hợp mọi không gian làm việc và giải trí. Kết nối đa dạng : Trang bị cổng HDMI và VGA, dễ dàng kết nối PC, laptop, đầu phát. Tối ưu không gian : Hỗ trợ chuẩn VESA 100×100 mm, cho phép treo tường hoặc gắn arm màn hình. Thông số Màn hình E-Dra EGM24F120S Thông số Chi tiết Model E-Dra EGM24F120S Kích thước màn hình 23.8 inch, phẳng Độ phân giải Full HD (1920×1080) Tấm nền IPS, hiển thị 16.7 triệu màu Độ sáng 280 nits Độ tương phản 1300:1 Tần số quét 120Hz Thời gian phản hồi 1ms Góc nhìn 178° (ngang/dọ', '{"Model":"E-Dra EGM24F120S","Kích thước màn hình":"23.8 inch, phẳng","Độ phân giải":"Full HD (1920×1080)","Tấm nền":"IPS, hiển thị 16.7 triệu màu","Độ sáng":"280 nits","Độ tương phản":"1300:1","Tần số quét":"120Hz","Thời gian phản hồi":"1ms"}', 0, 1);
