INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1076719114', 'SP1084178', '1076719114', 'https://www.maytinhbienhoa.vn/products/man-hinh-vsp-ip2510w1-25-fhd-ips-100hz-hdmi-vga', 'MÀN HÌNH VSP IP2510W1 25" FHD IPS 100Hz HDMI+VGA', 'man-hinh-vsp-ip2510w1-25-fhd-ips-100hz-hdmi-vga', 'brand_vsp_249', 'cat_monitors', 1690000, 1690000, 0, 1352000, 24, 'in_stock', 'MÀN HÌNH VSP IP2510W1 25" FHD IPS 100Hz HDMI+VGA', 'THÔNG SỐ KỸ THUẬT &nbsp; Mã sản phẩm IP2510W1 Màu sắc Đen (Black) Kích cỡ màn hình 24.5 inch Loại màn hình Phẳng (Flat) Độ phân giải Full HD (1920 x 1080 px) Tấm nền IPS (ADS Liquid Crystal) Tần số quét 100Hz Tốc độ phản hồi 5ms (OD) Độ sáng 280 cd/m² Độ tương phản 1000:1 Màu sắc hiển thị 16.7 Triệu màu Độ phủ màu (Gamut) 100% sRGB / 97% DCI-P3 / 90% Adobe RGB / 88% NTSC Góc nhìn 178° (H) / 178° (V) Tính năng đặc biệt - Hỗ trợ GamePlus &amp; DCR - Chế độ tiết kiệm năng lượng (ECO Mode) - Kiểm soát ánh sáng xanh (Low Blue Light) Góc nghiêng (Tilt) -4° ~ +17° Chuẩn gắn VESA 75 x 75 mm Kích thước 557 x 421 x 149 mm Trọng lượng Tịnh (Net): 3.3 Kg Tổng (Gross): 4.45 Kg Nguồn cấp DC 12V - 3A Phụ kiện kèm theo Adapter nguồn, Chân đế, Dây HDMI Bảo hành 3 năm &nbsp; &nbsp; VSP IP2510W1 đem đến cho bạn trải nghiệm chơi game một cách chân thực đến từng khung hình từ sự kết hợp hoàn hảo giữa công nghệ Adaptive Sync, GamePlus. Hình ảnh sắc nét và chế độ hiển thị màu vượt trội nhờ tấm nền Fast IPS, trong khi đó với tốc độ phản hồi nhanh 5ms (OD)&nbsp;giúp cho hình ảnh mượt mà hơn. &nbsp; QUÁ TRÌNH CHƠI GAME LIỀN MẠCH &nbsp; Sự kết hợp giữa công nghệ Adaptive Sync và GamePlus đem đến cho bạn hiệu quả sử dụng tuyệt vời, không những vậy với công nghệ chống xé hình và chống bóng mờ giúp bạn tận hưởng trải nghiệm chơi game không bị giật hình, đem đến hình ảnh sắc nét ngay khi chơi các trò chơi có tiết tấu nhanh. &nbsp; &nbsp; HÌNH ẢNH MƯỢT MÀ VỚI TẦN SỐ QUÉT 100Hz &nbsp; Với tần số quét&nbsp;lê', '{"Mã sản phẩm":"IP2510W1","Màu sắc":"Đen (Black)","Kích cỡ màn hình":"24.5 inch","Loại màn hình":"Phẳng (Flat)","Độ phân giải":"Full HD (1920 x 1080 px)","Tấm nền":"IPS (ADS Liquid Crystal)","Tần số quét":"100Hz","Tốc độ phản hồi":"5ms (OD)","Độ sáng":"280 cd/m²","Độ tương phản":"1000:1","Màu sắc hiển thị":"16.7 Triệu màu","Độ phủ màu (Gamut)":"100% sRGB / 97% DCI-P3 / 90% Adobe RGB / 88% NTSC"}', 0, 1);
