INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1077202337', 'SP1084222', '1077202337', 'https://www.maytinhbienhoa.vn/products/man-hinh-edra-egm24f144pv-24-fhd-ips-144hz-chuyen-game', 'MÀN HÌNH E-DRA EGM24F144PV 24" FHD IPS 144Hz CHUYÊN GAME', 'man-hinh-edra-egm24f144pv-24-fhd-ips-144hz-chuyen-game', 'brand_e-dra_329', 'cat_monitors', 1690000, 1690000, 0, 1352000, 24, 'in_stock', 'MÀN HÌNH E-DRA EGM24F144PV 24" FHD IPS 144Hz CHUYÊN GAME', 'THÔNG SỐ KỸ THUẬT &nbsp; Nhu cầu Màn hình gaming Kích thước màn hình 24Inch Độ phân giải Full HD (1920x1080) Thời gian đáp ứng 1ms Tần số quét 144Hz Độ sáng 250cd/m2 Tỷ lệ tương phản 1000:1 Góc nhìn 178°(H)/178°(V) Tấm nền IPS Kết nối Loa tích hợp Không Cổng giao tiếp 1xHDMI + 1xD-Sub + DC Phụ kiện kèm theo Cáp nguồn, Cáp HDMI Thông tin khác Tính năng khác - 99%sRGB - VESA: 75x75mm Xuất xứ Chính hãng &nbsp; &nbsp; Màn hình gaming E-Dra EGM24F144PV (24nch/ Full HD/ 1ms/ 144Hz/ 250cd/m2/ IPS)&nbsp; Tối ưu trải nghiệm game với màn hình chuyên dụng Trong kỷ nguyên của eSports và giải trí số, việc sở hữu một màn hình gaming chất lượng cao không chỉ giúp nâng cao hiệu suất thi đấu mà còn đem lại trải nghiệm thị giác sống động, trung thực đến từng chi tiết. Với thiết kế mạnh mẽ, tốc độ làm mới vượt trội và khả năng hiển thị màu sắc ấn tượng, màn hình gaming EDRA EGM24F144PV 24 inch FullHD 144Hz là lựa chọn lý tưởng cho các game thủ đang tìm kiếm một thiết bị hiển thị chất lượng trong tầm giá hợp lý. &nbsp; Thiết kế tối giản, chắc chắn cho không gian gaming hiện đại Ngay từ cái nhìn đầu tiên, EDRA EGM24F144PV tạo ấn tượng với thiết kế màn hình&nbsp;phẳng, viền mỏng, màu đen mạnh mẽ, phù hợp với mọi không gian làm việc hay góc chơi game. Chân đế cố định chắc chắn, đảm bảo sự ổn định trong quá trình sử dụng, ngay cả khi bạn thao tác mạnh tay trên bàn phím hoặc điều khiển chuột tốc độ cao. Kích thước tổng thể của sản phẩm (602 x 110 x 400mm, tính theo vỏ hộp) cho phép dễ dàng lắp đặt tr', '{"THÔNG SỐ KỸ THUẬT &nbsp;":"Nhu cầu","Kích thước màn hình":"24Inch","Độ phân giải":"Full HD (1920x1080)","Thời gian đáp ứng":"1ms","Tần số quét":"144Hz","Độ sáng":"250cd/m2","Tỷ lệ tương phản":"1000:1","Góc nhìn":"178°(H)/178°(V)","Tấm nền":"IPS","Kết nối":"Loa tích hợp","Cổng giao tiếp":"1xHDMI + 1xD-Sub + DC","Phụ kiện kèm theo":"Cáp nguồn, Cáp HDMI"}', 0, 1);
