INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1072153592', 'SP1083077', '1072153592', 'https://www.maytinhbienhoa.vn/products/man-hinh-msi-pro-mp242l-23-8-ps-100hz-fhd-1ms', 'MÀN HÌNH MSI PRO MP242L 23.8" PS 100Hz FHD 1MS', 'man-hinh-msi-pro-mp242l-23-8-ps-100hz-fhd-1ms', 'brand_msi_233', 'cat_monitors', 1890000, 1890000, 0, 1512000, 24, 'in_stock', 'MÀN HÌNH MSI PRO MP242L 23.8" PS 100Hz FHD 1MS', 'Màn hình Nhu cầu Màn hình văn phòng Kích thước màn hình 23.8Inch Độ phân giải Full HD (1920x1080) Thời gian đáp ứng 1ms Tần số quét 100HZ Độ sáng 250cd/m2 Tỷ lệ tương phản 4000:1 Góc nhìn 178°(H)/178°(V) Tấm nền IPS Kết nối Loa tích hợp Không Cổng giao tiếp 1x HDMI™ 1.4b (FHD@100Hz) 1x DisplayPort 1.2a Phụ kiện kèm theo Cáp nguồn, dây HDMI Thông tin khác Tính năng khác • Chứng chỉ hiển thị TÜV bảo vệ mắt và giúp cho mắt luôn khỏe mạnh • Công nghệ chống chớp hình và giảm ánh sáng xanh bảo vệ mắt khỏi khô và mỏi Xuất xứ Chính hãng &nbsp; &nbsp; Màn Hình MSI&nbsp;PRO MP242L Trong thời đại hiện nay, màn hình máy tính không chỉ là công cụ hỗ trợ công việc mà còn đóng vai trò quan trọng trong học tập, giải trí và chăm sóc sức khỏe người dùng. MSI PRO MP242L là một sản phẩm nổi bật trong phân khúc màn hình văn phòng và học tập, mang đến sự kết hợp hoàn hảo giữa thiết kế tinh tế, hiệu năng vượt trội và các tính năng bảo vệ mắt tiên tiến. Với mức giá hợp lý, màn hình này trở thành lựa chọn lý tưởng cho học sinh, sinh viên, nhân viên văn phòng và cả người dùng gia đình. &nbsp; 1. Thiết Kế Thẩm Mỹ Tối Giản MSI PRO MP242L sở hữu thiết kế tối giản nhưng không kém phần hiện đại, phù hợp với nhiều không gian sử dụng khác nhau. Viền màn hình mỏng ở ba cạnh không chỉ mang lại cảm giác thanh lịch mà còn giúp tối ưu hóa không gian hiển thị, đặc biệt hữu ích khi sử dụng đa màn hình. Với kích thước 23.8 inch, màn hình này vừa đủ lớn để mang lại trải nghiệm hình ảnh thoải mái mà không chiếm quá nh', '{"Màn hình":"Nhu cầu","Kích thước màn hình":"23.8Inch","Độ phân giải":"Full HD (1920x1080)","Thời gian đáp ứng":"1ms","Tần số quét":"100HZ","Độ sáng":"250cd/m2","Tỷ lệ tương phản":"4000:1","Góc nhìn":"178°(H)/178°(V)","Tấm nền":"IPS","Kết nối":"Loa tích hợp","Cổng giao tiếp":"1x HDMI™ 1.4b (FHD@100Hz) 1x DisplayPort 1.2a","Phụ kiện kèm theo":"Cáp nguồn, dây HDMI"}', 0, 1);
