INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074778181', 'SP1083643', '1074778181', 'https://www.maytinhbienhoa.vn/products/man-hinh-vsp-ip2706sg-27-fhd-ips-120hz-hdmi-vga-vien-sieu-mong', 'MÀN HÌNH VSP IP2706SG 27" FHD IPS 120Hz HDMI+VGA VIỀN SIÊU MỎNG', 'man-hinh-vsp-ip2706sg-27-fhd-ips-120hz-hdmi-vga-vien-sieu-mong', 'brand_vsp_249', 'cat_monitors', 2049000, 2049000, 0, 1639200, 24, 'in_stock', 'MÀN HÌNH VSP IP2706SG 27" FHD IPS 120Hz HDMI+VGA VIỀN SIÊU MỎNG', 'Khám Phá Màn Hình VSP IP2706SG 27" IPS 120Hz VSP IP2706SG là mẫu màn hình 27 inch hướng đến người dùng cần không gian hiển thị rộng rãi cùng trải nghiệm mượt mà hơn các dòng màn hình phổ thông thông thường. Sản phẩm sở hữu tấm nền IPS Full HD kết hợp tần số quét 120Hz, đáp ứng tốt nhu cầu làm việc văn phòng, học online, xem phim hay chơi game giải trí mỗi ngày. Với thiết kế hiện đại và khả năng hiển thị ổn định, đây là lựa chọn phù hợp cho cả học tập lẫn giải trí tại nhà. Thiết Kế 27 Inch IPS Full HD Hiển Thị Rộng Rãi VSP IP2706SG được trang bị màn hình 27 inch cùng tấm nền IPS chất lượng cao, mang lại góc nhìn rộng lên đến 178 độ và khả năng hiển thị màu sắc ổn định ở nhiều góc quan sát khác nhau. Độ phân giải Full HD giúp hình ảnh rõ nét, phù hợp cho các nhu cầu làm việc văn phòng, học tập trực tuyến và giải trí đa phương tiện. Kích thước màn hình lớn còn hỗ trợ thao tác đa nhiệm hiệu quả hơn, cho phép mở nhiều cửa sổ cùng lúc mà vẫn đảm bảo không gian hiển thị thoải mái. &nbsp; Độ Sáng 300 Nits Và Khả Năng Tái Tạo Màu Ấn Tượng Màn hình sở hữu độ sáng 300 cd/m² kết hợp tỷ lệ tương phản 1000:1, giúp hình ảnh hiển thị rõ ràng và có chiều sâu hơn trong nhiều điều kiện ánh sáng khác nhau. Ngoài ra, VSP IP2706SG còn hỗ trợ hiển thị 16.7 triệu màu với độ phủ màu khá tốt trong phân khúc như: sRGB 93% Adobe RGB 67% NTSC khoảng 62% Nhờ đó, các nội dung hình ảnh, video hay thiết kế đồ họa cơ bản đều trở nên sống động và bắt mắt hơn. Tần Số Quét 120Hz Cho Trải Nghiệm Mượt Mà Một trong', '{"Model":"MÀN HÌNH VSP IP2706SG 27\\" FHD IPS 120Hz HDMI+VGA VIỀN SIÊU MỎNG"}', 0, 1);
