INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074778190', 'SP1083644', '1074778190', 'https://www.maytinhbienhoa.vn/products/man-hinh-vsp-ip2709sg-27-fhd-144hz-ips-hdmi-vga-chuyen-game', 'MÀN HÌNH VSP IP2709SG 27" FHD 144Hz IPS HDMI+VGA CHUYÊN GAME', 'man-hinh-vsp-ip2709sg-27-fhd-144hz-ips-hdmi-vga-chuyen-game', 'brand_vsp_249', 'cat_monitors', 2149000, 2149000, 0, 1719200, 24, 'in_stock', 'MÀN HÌNH VSP IP2709SG 27" FHD 144Hz IPS HDMI+VGA CHUYÊN GAME', 'Khám phá màn hình VSP IP2709SG 27" IPS 144Hz – Mượt mà cho cả làm việc lẫn gaming &nbsp; &nbsp; VSP IP2709SG là mẫu màn hình 27 inch được thiết kế hướng đến người dùng cần không gian hiển thị rộng, hình ảnh đẹp và trải nghiệm sử dụng mượt mà hơn các dòng màn hình phổ thông. Sở hữu tấm nền IPS chất lượng cùng tần số quét 144Hz, sản phẩm đáp ứng tốt từ nhu cầu học tập, làm việc văn phòng cho đến chơi game online giải trí mỗi ngày. Thiết kế viền mỏng hiện đại cũng giúp chiếc màn hình này dễ dàng hòa hợp với các góc setup gaming hoặc làm việc đa màn hình. Không gian hiển thị lớn với tấm nền IPS sắc nét &nbsp; VSP IP2709SG được trang bị kích thước 27 inch cùng độ phân giải Full HD (1920 x 1080), mang lại không gian hiển thị rộng rãi cho công việc và giải trí. Tỷ lệ 16:9 quen thuộc giúp tối ưu trải nghiệm xem phim, chơi game và làm việc đa nhiệm. Tấm nền IPS cho góc nhìn rộng lên đến 178 độ, giữ màu sắc ổn định khi quan sát từ nhiều hướng khác nhau. Ngoài ra, màn hình sử dụng lớp phủ chống chói dạng nhám kết hợp độ cứng bề mặt 3H, hỗ trợ hạn chế phản xạ ánh sáng và giảm trầy xước nhẹ trong quá trình sử dụng hằng ngày. &nbsp; Hiển thị màu sắc sống động, độ sáng ổn định &nbsp; Màn hình sở hữu độ sáng 300 nits cùng độ tương phản tĩnh 1000:1, đáp ứng tốt nhu cầu sử dụng trong môi trường văn phòng, học tập hoặc góc gaming trong nhà. Về khả năng hiển thị màu, VSP IP2709SG hỗ trợ 16.7 triệu màu với độ phủ màu khá ấn tượng trong phân khúc, bao gồm sRGB ≥ 110%, NTSC ≥ 72%, DCI-P3 ≥ 80% và A', '{"Model":"MÀN HÌNH VSP IP2709SG 27\\" FHD 144Hz IPS HDMI+VGA CHUYÊN GAME"}', 0, 1);
