INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1077207617', 'SP1084224', '1077207617', 'https://www.maytinhbienhoa.vn/products/man-hinh-e-dra-egm27f180pvs-27-fhd-ips-180hz-chuyen-game', 'MÀN HÌNH E-DRA EGM27F180PVS 27" FHD IPS 180Hz CHUYÊN GAME', 'man-hinh-e-dra-egm27f180pvs-27-fhd-ips-180hz-chuyen-game', 'brand_e-dra_329', 'cat_monitors', 2380000, 2380000, 0, 1904000, 24, 'in_stock', 'MÀN HÌNH E-DRA EGM27F180PVS 27" FHD IPS 180Hz CHUYÊN GAME', '&nbsp; &nbsp; &nbsp; THÔNG SỐ KỸ THUẬT Thương hiệu EDra Bảo hành 24 tháng Kích cỡ 27 inch Độ phân giải FHD (1920 x 1080) Tỷ lệ khung hình 16:9 Tấm nền IPS Độ sáng màn hình 250cd/m2 Độ tương phản Đang cập nhật Kiểu màn hình Màn hình phẳng Thời gian phản hồi 0.5 ms Tần số quét 180Hz Cổng kết nối 1 x HDMI, 1 DP + DC Phân loại màn hình Gaming Vesa 100x100mm Kích thước 602*110*400mm (Vỏ hộp) Trọng lượng 4.1kg &nbsp; Màn hình Edra EGM27F180PVS – Trải nghiệm Gaming Đỉnh Cao Màn hình Edra EGM27F180PVS là sự lựa chọn lý tưởng cho game thủ chuyên nghiệp và người dùng yêu thích trải nghiệm hình ảnh mượt mà, sắc nét. Với kích thước lớn 27 inch, tấm nền IPS hiện đại cùng tốc độ làm mới vượt trội lên đến 180Hz, sản phẩm mang đến chất lượng hình ảnh tuyệt đẹp, hiệu suất vượt trội và khả năng đáp ứng nhanh chóng trong mọi tác vụ. Hiệu Năng Vượt Trội Cho Game Thủ Tốc độ làm mới 180Hz: Gấp ba lần so với các màn hình thông thường, mang đến trải nghiệm chơi game mượt mà và không bị giật hình, đặc biệt trong các tựa game đòi hỏi tốc độ cao như FPS, MOBA hoặc đua xe. Thời gian phản hồi 0.5ms MPRT: Loại bỏ hiện tượng bóng ma và mờ hình, giúp mọi chuyển động trở nên rõ ràng và sắc nét hơn, mang lại lợi thế trong các tình huống đối đầu khốc liệt. Tấm nền IPS: Cung cấp góc nhìn rộng, chất lượng màu sắc ổn định và trung thực, đồng thời giảm thiểu hiện tượng biến dạng màu khi nhìn từ các góc khác nhau. Hình Ảnh Sắc Nét, Màu Sắc Sống Động Độ phân giải Full HD (1920×1080): Đem lại hình ảnh chi tiết,', '{"EDra":"24 tháng","27 inch":"FHD (1920 x 1080)","16:9":"IPS","250cd/m2":"Đang cập nhật","Màn hình phẳng":"0.5 ms","180Hz":"1 x HDMI, 1 DP + DC","Gaming":"100x100mm","602*110*400mm (Vỏ hộp)":"4.1kg"}', 0, 1);
