INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1066618278', 'SP1081790', '1066618278', 'https://www.maytinhbienhoa.vn/products/man-hinh-viewsonic-vx2758a-2k-pro-4-27-2k-ips-180hz-137-srgb-hdmi-dp-chuyen-game', 'MÀN HÌNH VIEWSONIC VX2758A-2K-PRO-4 27" 2K IPS 180Hz 1ms 137% sRGB HDMI+DP CHUYÊN GAME', 'man-hinh-viewsonic-vx2758a-2k-pro-4-27-2k-ips-180hz-137-srgb-hdmi-dp-chuyen-game', 'brand_viewsonic_951', 'cat_monitors', 4589000, 5990000, 23, 3671200, 24, 'in_stock', 'MÀN HÌNH VIEWSONIC VX2758A-2K-PRO-4 27" 2K IPS 180Hz 1ms 137% sRGB HDMI+DP CHUYÊN GAME', '&nbsp; Thông số kỹ thuật Màn hình Kích thước 27 inch Tấm nền IPS Độ tương phản 1000:1 Công nghệ AMD FreeSync Premium Flicker-Free Motion Blur Reduction Low Blue Light Độ phân giải 2560 x 1440 Pixels Điện áp 100 - 240 V / 50 - 60 Hz Thời gian phản hồi 1ms Tần số quét 180hz&nbsp; Tỉ lệ 16:9 Độ sáng 350 nits Xuất xứ Mỹ Thương hiệu VIEWSONIC Thông tin hàng hóa Kiểu chân đế Công thái học Màu sắc Đen Kích thước 720 x 450 x 140 mm Trọng lượng 4.6 kg Giao tiếp và kết nối Cổng kết nối DisplayPort HDMI Giới Thiệu Màn Hình ViewSonic VX2758A-2K-PRO-4 ( 27inch/ 2k /IPS /180HZ/1MS/ HDMI + DP / chân công thái học ) TỔNG QUAN Trải nghiệm giải trí nhập vai với màn hình chơi game ViewSonic VX2758A-2K-PRO-4. Tốc độ làm mới 180Hz cao đảm bảo hình ảnh động cực kỳ mượt mà, trong khi thời gian phản hồi MPRT 1ms nhanh chóng mang lại hình ảnh mượt mà và độ trễ đầu vào tối thiểu, khiến nó trở nên hoàn hảo cho trò chơi tốc độ cao. Được trang bị công nghệ AMD FreeSync™ để loại bỏ hiện tượng rách màn hình và giật hình để có trải nghiệm chơi game liền mạch, màn hình này cũng tự hào có các cài đặt trước ViewMode™ độc quyền của ViewSonic, mang đến hình ảnh tuyệt đẹp được tối ưu hóa cho trò chơi gay cấn, giải trí hấp dẫn, chỉnh sửa sáng tạo và hơn thế nữa. Màn hình được trang bị đầy đủ các tùy chọn kết nối đa dạng, có DisplayPort và hai đầu vào HDMI. &nbsp; Chơi game không bị chói với SuperClear® IPS Trải nghiệm hình ảnh hấp dẫn với màn hình VX2758A-2K-PRO-4. Với công nghệ tấm nền SuperClear® IPS, màn hình đ', '{"Kích thước":"27 inch","Tấm nền":"IPS","Độ tương phản":"1000:1","Công nghệ":"AMD FreeSync Premium Flicker-Free Motion Blur Reduction Low Blue Light","Độ phân giải":"2560 x 1440 Pixels","Điện áp":"100 - 240 V / 50 - 60 Hz","Thời gian phản hồi":"1ms","Tần số quét":"180hz&nbsp;","Tỉ lệ":"16:9","Độ sáng":"350 nits","Xuất xứ":"Mỹ","Thương hiệu":"VIEWSONIC"}', 0, 1);
