INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1022332377', 'SP006784', '1022332377', 'https://www.maytinhbienhoa.vn/products/lcd-msi-27-inch-cong-optix-g27c4-1ms-165hz', 'MÀN HÌNH LCD MSI CONG OPTIX G27C4 27" 165HZ 1MS CHUYÊN GAME', 'lcd-msi-27-inch-cong-optix-g27c4-1ms-165hz', 'brand_msi_233', 'cat_monitors', 6990000, 6690000, 0, 5592000, 24, 'out_of_stock', 'MÀN HÌNH LCD MSI CONG OPTIX G27C4 27" 165HZ 1MS CHUYÊN GAME', '&nbsp; ĐẶC ĐIỂM NỔI BẬT ✔️ Đỗ trễ 1ms ✔️ Tần số quét 165hz ✔️ Viền màn hình siêu mỏng ✔️ Màn cong 1500R ✔️ Hỗ trợ AMD FREESYNC THÔNG SỐ KỸ THUẬT Màn hình máy tính&nbsp;LCD MSI 27 INCH CONG OPTIX G27C4 &nbsp;đến từ thương hiệu màn hình máy tính MSI Panel Type &amp; Backlight VA / W-LED, edge array Screen Size, Aspect Ratio &amp; Curve Radius 27 inches / 16:9, Curve radius: 1500mm Max Resolution &amp; Refresh Rate 1920 x 1080 @ 165Hz, FreeSync 48-165Hz Native Color Depth &amp; Gamut 8-bit / DCI-P3 Response Time (GTG) 1ms Brightness 250 nits Contrast 3,000:1 Speakers None Video Inputs 1x DisplayPort 1.2, 2x HDMI 1.4 Audio 3.5mm headphone output USB Ports None Power Consumption 19.5w, brightness @ 200 nits Panel Dimensions WxHxD w/base 24.1 x 18.2 x 8.9 inches (612 x 462 x 226mm) Panel Thickness 2.4 inches (60mm) Bezel Width Top/sides: 0.3 inch (8mm), Bottom: 1.1 inches (27mm) Weight 11.9 pounds (5.4kg) Warranty 3 years Với thiết kế gọn gàng, đẹp mắt, hiệu năng ổn trong tầm giá cùng "món quà" mang tên AMD Adaptive Sync, MSI Optix G27C4 sẽ là một sự lựa chọn mà game thủ khó có thể bỏ qua. &nbsp; &nbsp;Trong thế giới của những tựa game bắn súng FPS, nơi mà những màn hình Gaming như MSI G27C4 sinh ra để thuộc về, tốc độ là thứ quyết định tất cả. Kết quả của trận đấu có thể được định đoạt chỉ trong một khoảnh khắc. Và dù bạn có rèn luyện bản thân như thế nào đi chăng nữa, nhưng cuối cùng, nếu màn hình của bạn không có tần số quét đủ nhanh, hay chuột của bạn gửi tín hiệu quá chậm, bạn', '{"Panel Type &amp; Backlight":"VA / W-LED, edge array","Screen Size, Aspect Ratio &amp; Curve Radius":"27 inches / 16:9, Curve radius: 1500mm","Max Resolution &amp; Refresh Rate":"1920 x 1080 @ 165Hz, FreeSync 48-165Hz","Native Color Depth &amp; Gamut":"8-bit / DCI-P3","Response Time (GTG)":"1ms","Brightness":"250 nits","Contrast":"3,000:1","Speakers":"None","Video Inputs":"1x DisplayPort 1.2, 2x HDMI 1.4","Audio":"3.5mm headphone output","USB Ports":"None","Power Consumption":"19.5w, brightness @ 200 nits"}', 0, 1);
