INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1022929482', 'SP007182', '1022929482', 'https://www.maytinhbienhoa.vn/products/lcd-asus-27-inch-tuf-gaming-vg279qm-overclockable-280hz-above-240hz-144hz-1ms-chuyen-game', 'MÀN HÌNH LCD ASUS TUF GAMING VG279QM 27" FHD FAST IPS 280HZ OC 1MS HDR400 GSYNC COMPATIBLE CHUYÊN GAME', 'lcd-asus-27-inch-tuf-gaming-vg279qm-overclockable-280hz-above-240hz-144hz-1ms-chuyen-game', 'brand_asus_316', 'cat_monitors', 6590000, 12990000, 49, 5272000, 24, 'out_of_stock', 'MÀN HÌNH LCD ASUS TUF GAMING VG279QM 27" FHD FAST IPS 280HZ OC 1MS HDR400 GSYNC COMPATIBLE CHUYÊN GAME', 'THÔNG SỐ KỸ THUẬT Độ phân giải Full HD 1920x1080 Tấm nền IPS Tần số quét 280Hz(overclocking)&nbsp; &nbsp;(Above 240Hz, 144Hz)&nbsp; Thời gian phản hồi 1ms (Gray to Gray) Kiểu màn hình Phẳng Độ sáng 400 cd/㎡ Góc nhìn 178°(H)/178°(V) Khả năng hiển thị màu sắc 16.7 Triệu màu Độ tương phản tĩnh 1000 : 1 Độ tương phản động 100.000.000 : 1 Cổng xuất hình HDMI(v2.0) x2, DisplayPort 1.2 3.5mm Mini-Jack Tính năng đặc biệt G-Sync COMPATIBLE Khối lượng ~&nbsp;8.2 kg Kích thước chuẩn 619.4x(376.73~506.73)x211.37 mm Phụ kiện đi kèm Dây cáp nguồn Bộ chuyển nguồn (Adapter) Dây HDMI (Có thể có) Dây Display Port (Có thể có) Tài liệu hướng dẫn sử dụng Thẻ bảo hành &nbsp; Màn hình nhanh nhất thế giới&nbsp;27 inch, Fast IPS, Full HD Tốc độ làm mới 280 Hz có thể ép xung đáng kinh ngạc, hình ảnh nhanh gần gấp đôi so với màn hình 144 Hz thông thường. Bạn sẽ trải nghiệm hình ảnh chơi game cực kỳ mượt mà, giúp bạn chiếm ưu thế trong các tựa game nhập vai thực tế. ASUS Fast IPS Display cho phép các thành phần tinh thể lỏng của màn hình chuyển đổi nhanh hơn 4 lần so với các tấm nền IPS thông thường. Hiện tượng nhòe và mờ khi chuyển động gần như được loại bỏ. Màn hình cung cấp dải màu DCI-P3 đạt mức 95% và tỷ lệ tương phản 1.000:1 đáng kinh ngạc. Góc nhìn rộng 178 độ đảm bảo giảm thiểu độ méo và khả năng đổi màu ngay cả khi bạn đang quan sát từ những vị trí khó khăn nhất. Công nghệ biến thiên tần số làm mới (VRR) được mặc định kích hoạt, đảm bảo giúp bạn đạt được trải nghiệm chơi game liền mạch, không x', '{"Độ phân giải":"Full HD 1920x1080","Tấm nền":"IPS","Tần số quét":"280Hz(overclocking)&nbsp; &nbsp;(Above 240Hz, 144Hz)&nbsp;","Thời gian phản hồi":"1ms (Gray to Gray)","Kiểu màn hình":"Phẳng","Độ sáng":"400 cd/㎡","Góc nhìn":"178°(H)/178°(V)","Khả năng hiển thị màu sắc":"16.7 Triệu màu","Độ tương phản tĩnh":"1000 : 1","Độ tương phản động":"100.000.000 : 1","Cổng xuất hình":"HDMI(v2.0) x2, DisplayPort 1.2 3.5mm Mini-Jack","Tính năng đặc biệt":"G-Sync COMPATIBLE"}', 0, 1);
