INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1026113384', 'SP008459', '1026113384', 'https://www.maytinhbienhoa.vn/products/man-hinh-asus-35-xg35vq-uwqhd-100hz-freesync', 'MÀN HÌNH ASUS 35" XG35VQ UWQHD 100Hz FreeSync CHUYÊN GAME', 'man-hinh-asus-35-xg35vq-uwqhd-100hz-freesync', 'brand_asus_316', 'cat_monitors', 20800000, 21990000, 5, 16640000, 24, 'in_stock', 'MÀN HÌNH ASUS 35" XG35VQ UWQHD 100Hz FreeSync CHUYÊN GAME', 'Tính năng nổi bật ●&nbsp; Màn hình cong chuyên game có kích thước 35 inch, độ cong 1800R với tần số quét 100Hz được thiết kế dành riêng cho các game thủ chuyên nghiệp để mang lại trải nghiệm chơi game đắm chìm. ● Công nghệ Extreme Low Motion Blur (Độ nhòe chuyển động siêu thấp) đảm bảo các phần tử đồ họa không bao giờ bị nhòe và công nghệ Adaptive-Sync (FreeSync) đảm bảo hình ảnh không xuất hiện hiện tượng xé hình. ● Các màn hình chuyên game dòng ROG Strix XG Series có hệ thống đèn ASUS Aura Sync ở mặt sau và tính năng tạo hình chiếu ánh sáng tùy chỉnh để tạo cảm hứng chơi game cuồng nhiệt. ●&nbsp; Sản phẩm có một giá đỡ được thiết kế công thái học cho khả năng điều chỉnh xoay trái phải, nghiêng lên xuống và chiều cao toàn diện. Thông số kĩ thuật:&nbsp; ROG Strix XG35VQ 35 Inch Màn hình cong chuyên game, UWQHD, 100Hz, FreeSync™, Extreme Low Motion Blur Màn hình Kích thước panel: Màn hình siêu rộng 35” (88.98cm) 21:9 Độ bão hòa màu: 100%(sRGB) Kiểu Panel : VA Độ phân giải thực: 3440x1440 Khu vực Hiển thị (HxV) : 819.4 x 345.9 mm Pixel: 0.155mm Độ sáng (tối đa): 300 cd/㎡ Bề mặt Hiển thị Chống lóa Góc nhìn (CR ≧ 10): 178°(H)/178°(V) Thời gian phản hồi: 4ms (Gray to Gray) Màu sắc hiển thị: 16.7 triệu màu Contrast Ratio (Max) : 2500 :1 Không chớp Tấm nền cong : 1800R Tính năng video Công nghệ không để lại dấu trace free: Có Các lựa chọn nhiệt độ màu: 4 chế độ GamePlus (chế độ) : Có (Ngắm/Hẹn giờ/Bộ đếm FPS/Màn hình hiển thị dạng lưới) Hỗ trợ HDCP Tần suất Ánh sáng Xanh Thấp : Có G', '{"Độ bão hòa màu: 100%(sRGB)":"Kiểu Panel : VA","Độ phân giải thực: 3440x1440":"Khu vực Hiển thị (HxV) : 819.4 x 345.9 mm","Pixel: 0.155mm":"Độ sáng (tối đa): 300 cd/㎡","Bề mặt Hiển thị Chống lóa":"Góc nhìn (CR ≧ 10): 178°(H)/178°(V)","Thời gian phản hồi: 4ms (Gray to Gray)":"Màu sắc hiển thị: 16.7 triệu màu","Contrast Ratio (Max) : 2500 :1":"Không chớp","Tấm nền cong : 1800R":"Tính năng video","Các lựa chọn nhiệt độ màu: 4 chế độ":"GamePlus (chế độ) : Có (Ngắm/Hẹn giờ/Bộ đếm FPS/Màn hình hiển thị dạng lưới)","Hỗ trợ HDCP":"Tần suất Ánh sáng Xanh Thấp : Có","Phần mềm Display Widget":"Extreme Low Motion Blur","Công nghệ GameFast Input":"Phím nóng thuận tiện","Cần Điều hướng 5 Chiều Trên Màn hình":"GameVisual"}', 1, 1);
