INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1024543380', 'SP008140', '1024543380', 'https://www.maytinhbienhoa.vn/products/man-hinh-aoc-27-27g2-ips-144hz-gsync-compatible-chuyen-game', 'MÀN HÌNH LCD AOC 27G2/74 27" IPS 144Hz CHUYÊN GAME', 'man-hinh-aoc-27-27g2-ips-144hz-gsync-compatible-chuyen-game', 'brand_aoc_211', 'cat_monitors', 4689000, 7299000, 36, 3751200, 24, 'out_of_stock', 'MÀN HÌNH LCD AOC 27G2/74 27" IPS 144Hz CHUYÊN GAME', 'THÔNG SỐ KỸ THUẬT Thương hiệu AOC Bảo hành 36 Tháng Kích thước 27 inch Độ phân giải 1920 x 1080 @ 144Hz – DisplayPort, HDMI 1920 x 1080 @ 60Hz – VGA Tấm nền IPS Tần số quét 144Hz Thời gian phản hồi 1ms Kiểu màn hình ( phẳng / cong ) Phẳng&nbsp; Độ sáng 250 cd/m2 Góc nhìn 178 ° (H) / 178 ° (V) (CR&gt; 10) Khả năng hiển thị màu sắc 16,7 triệu ,&nbsp;NTSC 104% (CIE1976) / sRGB 118% (CIE1931) / DCI-P3 95% (CIE1976) Độ tương phản tĩnh 1000 : 1&nbsp; Độ tương phản động 80.000.000 : 1&nbsp; Cổng xuất hình VGA x 1, HDMI 1.4 x 2, DisplayPort 1.2 x 1 Chứng nhận&nbsp; BSMI / KC / KCC / e-Standby / RCM / MEPS / CE / CB / FCC Khối lượng Sản phẩm không có chân đế (kg): 3.7 Sản phẩm có chân đế (kg): 5.1 Tiêu thụ điện Nguồn điện: 100 - 240V ～ 1.5A, 50 / 60Hz Công suất tiêu thụ (điển hình): 28W Kích thước chuẩn Sản phẩm không có chân đế (mm): 363 (H) × 612,1 (W) × 46 (D) Sản phẩm có chân đế (mm): 395,9 ~ 525,9 (H) × 612,1 (W) × 227,4 (D) &nbsp; &nbsp; Màn hình 27 inch IPS, G-Sync Compatible, 1ms, 144Hz, Adaptive Sync Sở hữu công nghệ G-Sync Compatible, màn hình gaming 27G2 còn được tích hợp công nghệ Adaptive-Sync giúp ổn định tần số quét của màn hình, đem lại trải nghiệm gaming chuẩn E-Sports chuyên nghiệp. Tấm nền IPS còn đem lại góc nhìn rộng, trong khi HDMI và DisplayPort giúp bạn dễ dàng kết nối các thiết bị ngoại vi. Màn hình Gaming 27G2 là màn hình chính thức cho giải đấu GeForce Cup Pacific 2019. Giải Pháp Chống Xé Hình Toàn Cầu Màn hình bị xé hình không ch', '{"Thương hiệu":"AOC","Bảo hành":"36 Tháng","Kích thước":"27 inch","Độ phân giải":"1920 x 1080 @ 144Hz – DisplayPort, HDMI 1920 x 1080 @ 60Hz – VGA","Tấm nền":"IPS","Tần số quét":"144Hz","Thời gian phản hồi":"1ms","Kiểu màn hình ( phẳng / cong )":"Phẳng&nbsp;","Độ sáng":"250 cd/m2","Góc nhìn":"178 ° (H) / 178 ° (V) (CR&gt; 10)","Khả năng hiển thị màu sắc":"16,7 triệu ,&nbsp;NTSC 104% (CIE1976) / sRGB 118% (CIE1931) / DCI-P3 95% (CIE1976)","Độ tương phản tĩnh":"1000 : 1&nbsp;"}', 0, 1);
