INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1063425737', 'SP1081445', '1063425737', 'https://www.maytinhbienhoa.vn/products/ban-phim-co-zadez-gt-021k-gaming-black', 'Bàn Phím Cơ ZADEZ GT-021K Gaming Black', 'ban-phim-co-zadez-gt-021k-gaming-black', 'brand_zadez_382', 'cat_keyboards', 469000, 890000, 47, 375200, 24, 'in_stock', 'Bàn Phím Cơ ZADEZ GT-021K Gaming Black', '&nbsp; &nbsp; Pro-Gaming Keyboard&nbsp;ZADEZ GT-021K Kích thước:&nbsp;360.6 x 135.4 x 35.5 mm Tương thích:&nbsp;Windows 8/10 và Mac (Driver cài đặt trên Windows) Thiết lập Macro:&nbsp;Hỗ trợ tùy chỉnh qua driver chuyên dụng Trọng lượng:&nbsp;736.6 gram Đèn LED:&nbsp;RGB Rainbow, tùy chỉnh chế độ qua driver/ bàn phím Cổng kết nối:&nbsp;USB 3.0/ USB 2.0 Chiều dài dây:&nbsp;1.7M dây bọc dù, đầu USB mạ vàng Keycap:&nbsp;Double Injection, xuyên sáng Bảo hành:&nbsp;Kích hoạt bảo hành điện tử, 12 tháng (1 đổi 1) &nbsp; &nbsp; Pro-Gaming Keyboard - Switch Cơ Học Switch HUANO (Blue) mang đến cảm giác gõ chân thực, bền bỉ đến 50 triệu lần. -Đèn LED Rainbow Đèn LED RGB Rainbow tinh tế, có thể tùy chỉnh hiệu ứng ánh sáng qua driver. Phím double injection xuyên LED. &nbsp; &nbsp; &nbsp; -Thiết Kế TKL 87 Phím Thiết kế TKL thân thiện với game thủ, thuận tiện sử dụng với các Game thủ thường xuyên di chuyển -Độ Bền Phím 50 Triệu Lần Cực kỳ bền bỉ, đáp ứng tác động gõ mãnh liệt của các game thủ khi trò chơi đạt đến cao trào &nbsp; &nbsp; &nbsp; -Driver Tùy Chỉnh Tối ưu hiệu quả thao tác của các game thủ với driver/ software chuyên nghiệp của hãng ZADEZ -Mang Đến Sự Hài Lòng Dây cáp 1.7 mét bọc dù và chống nhiễu. Kích hoạt bảo hành điện tử 12 tháng, 1 đổi 1. &nbsp; &nbsp; Thông Số Kỹ Thuật 50 TRIỆU LẦN NHẤN CỰC KỲ BỀN BỈ HUANO BLUE SWITCH CƠ HỌC DRIVER CHUYÊN NGHIỆP TƯƠNG THÍCH WINDOWS 8/10 Kích thước 360.6 x 135.4 x 35.5 mm Trọng lượng 736.6 gram Chiều dài dây 1.7M dây bọc dù, đầu USB mạ vàng ', '{"50 TRIỆU LẦN NHẤN CỰC KỲ BỀN BỈ":"HUANO BLUE SWITCH CƠ HỌC","Kích thước":"360.6 x 135.4 x 35.5 mm","Trọng lượng":"736.6 gram","Chiều dài dây":"1.7M dây bọc dù, đầu USB mạ vàng","Tương thích":"Windows 8/10 và Mac (Driver cài đặt trên Windows)","Đèn LED":"RGB Rainbow, tùy chỉnh chế độ qua driver/ bàn phím","Keycap":"Double Injection, xuyên sáng","Thiết lập Macro":"Hỗ trợ tùy chỉnh qua driver chuyên dụng","Cổng kết nối":"USB 3.0/ USB 2.0","Bảo hành":"Kích hoạt bảo hành điện tử, 12 tháng (1 đổi 1)"}', 0, 1);
