INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1066260331', 'SP1081764', '1066260331', 'https://www.maytinhbienhoa.vn/products/ban-phim-co-machenike-k500-b87-red-switch-black', 'Bàn Phím Cơ Machenike K500-B87 Red Switch Black', 'ban-phim-co-machenike-k500-b87-red-switch-black', 'brand_machenike_645', 'cat_keyboards', 539000, 609000, 11, 431200, 24, 'in_stock', 'Bàn Phím Cơ Machenike K500-B87 Red Switch Black', 'Thông số kỹ thuật &nbsp; Phương thức kết nối Có dây Kích thước 359.7*129.7*36mm Trọng lượng 625g Số phím 87 phím Switch Outemu Red Hỗ trợ Hot-swap Có (3-Pin) Keycaps Double-shot PBT Hiệu ứng ánh sáng Mixed light effect, hỗ trợ 11 kiểu LED Rainbow, có phần mềm Driver để chỉnh LED Kết nối Cổng USB (Dây liền phím) Tính năng 100% Anti-ghosting và N-key rollover Tương thích PC/Laptop/MacOS &nbsp; MÔ TẢ SẢN PHẨM Bàn phím cơ Machenike K500B B87 | Led Rainbow, Red Switch – Trải nghiệm gõ mượt mà, giá cực tốt tại Tin Học Ngôi Sao Bạn đang tìm kiếm một chiếc bàn phím cơ nhỏ gọn, switch mượt, LED rực rỡ và hỗ trợ hot-swap? Machenike K500B B87 chính là lựa chọn hoàn hảo cho bạn! Với thiết kế TKL tiết kiệm không gian, switch Red êm ái, hiệu ứng LED Rainbow ấn tượng cùng khả năng tùy biến linh hoạt, sản phẩm này sẽ nâng tầm trải nghiệm gõ phím và chơi game của bạn lên một tầm cao mới. Thiết kế nhỏ gọn, tiện lợi cho mọi không gian Bàn phím Machenike K500B B87 có kích thước 359.7 129.7 36mm, giúp tiết kiệm diện tích bàn làm việc mà vẫn giữ được đầy đủ các phím chức năng quan trọng. Với layout 87 phím (TKL), sản phẩm phù hợp cho cả game thủ lẫn dân văn phòng cần sự gọn nhẹ và linh hoạt. Switch Red mượt mà – Trải nghiệm gõ cực êm Sử dụng&nbsp; Outemu Red Switch &nbsp;– dòng switch cơ học nổi tiếng với lực nhấn nhẹ, tuyến tính và không có tiếng click – bàn phím cho cảm giác gõ mượt mà, nhanh nhạy và yên tĩnh. Đây là lựa chọn lý tưởng cho người dùng cần gõ nhiều trong thời gian dài hoặc thường x', '{"Phương thức kết nối":"Có dây","Kích thước":"359.7*129.7*36mm","Trọng lượng":"625g","Số phím":"87 phím","Switch":"Outemu Red","Hỗ trợ Hot-swap":"Có (3-Pin)","Keycaps":"Double-shot PBT","Hiệu ứng ánh sáng":"Mixed light effect, hỗ trợ 11 kiểu LED Rainbow, có phần mềm Driver để chỉnh LED","Kết nối":"Cổng USB (Dây liền phím)","Tính năng":"100% Anti-ghosting và N-key rollover","Tương thích":"PC/Laptop/MacOS"}', 0, 1);
