INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1073476431', 'SP1083378', '1073476431', 'https://www.maytinhbienhoa.vn/products/ban-phim-co-aula-s500-xam-den-vang-wired-blue-sw', 'Bàn Phím Cơ Aula S500 Xám Đen Vàng Wired Blue Sw', 'ban-phim-co-aula-s500-xam-den-vang-wired-blue-sw', 'brand_aula_291', 'cat_keyboards', 549000, 549000, 0, 439200, 24, 'in_stock', 'Bàn Phím Cơ Aula S500 Xám Đen Vàng Wired Blue Sw', 'THÔNG SỐ KỸ THUẬT Thương hiệu Aula Bảo hành 24 tháng Kiểu Bàn phím cơ Kết nối USB 2.0 Kiểu kết nối Có dây Màu sắc Đen – Trăng – Đỏ, Xám – Den – Vàng Màu sắc đèn LED RGB Kích thước 436,0 × 126,0 × 49,7 ± 0.2 mm &nbsp; &nbsp; Mô tả Bàn Phím Gaming Có Dây AULA S500 – Blue Switch Clicky, LED RGB 20 Hiệu Ứng Bàn phím gaming&nbsp; AULA S500 &nbsp;là lựa chọn lý tưởng cho game thủ và người dùng yêu thích cảm giác gõ phím cơ học rõ ràng, dứt khoát. Sở hữu thiết kế fullsize 104 phím, switch Blue clicky đặc trưng cùng hệ thống LED RGB đa hiệu ứng, AULA S500 mang đến trải nghiệm chơi game và làm việc vừa mạnh mẽ vừa trực quan. Trải nghiệm gõ phím cơ học sắc nét AULA S500 được trang bị&nbsp; Blue Switch &nbsp;với hiệu ứng âm thanh&nbsp; clicky &nbsp;rõ ràng, phản hồi nhanh và hành trình phím chính xác. Mỗi lần nhấn đều cho cảm giác chắc tay, phù hợp với game thủ FPS, MOBA cũng như người dùng thường xuyên gõ văn bản. Độ bền phím lên đến&nbsp; 50 triệu lần bấm , đảm bảo sử dụng ổn định lâu dài. LED RGB 20 hiệu ứng nổi bật Hệ thống&nbsp; đèn nền LED RGB &nbsp;với&nbsp; 20 hiệu ứng ánh sáng &nbsp;giúp không gian chơi game trở nên sống động và cá tính hơn. Người dùng có thể dễ dàng tùy chỉnh hiệu ứng thông qua tổ hợp&nbsp; phím FN đa chức năng , tối ưu trải nghiệm theo sở thích cá nhân. Thiết kế fullsize chắc chắn, kết nối ổn định Với&nbsp; 104 phím tiêu chuẩn , AULA S500 đáp ứng đầy đủ nhu cầu chơi game và làm việc văn phòng. Kết nối&nbsp; USB 2.0 có dây &nbsp;mang lại tín hiệu ổn định, ', '{"Aula":"24 tháng","Bàn phím cơ":"USB 2.0","Có dây":"Đen – Trăng – Đỏ, Xám – Den – Vàng","RGB":"436,0 × 126,0 × 49,7 ± 0.2 mm"}', 0, 1);
