INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074756640', 'SP1083624', '1074756640', 'https://www.maytinhbienhoa.vn/products/ban-phim-co-dareu-ek87-v2-gray-black-switch-dream', 'Bàn Phím Cơ Dareu EK87 V2 Gray Black Switch Dream', 'ban-phim-co-dareu-ek87-v2-gray-black-switch-dream', 'brand_dareu_369', 'cat_keyboards', 549000, 549000, 0, 439200, 24, 'in_stock', 'Bàn Phím Cơ Dareu EK87 V2 Gray Black Switch Dream', 'Bàn phím cơ DareU EK87 V2 DareU EK87 V2 &nbsp;là phiên bản tiếp theo được nâng cấp từ dòng EK87 đình đám đã từng khuấy đảo phân khúc&nbsp;phím cơ&nbsp;giá rẻ thời gian qua. Sở hữu nhiều cải tiến đáng chú ý nhưng mức giá không hề đổi so với phiên bản tiền nhiệm, mẫu&nbsp;bàn phím DareU&nbsp;này hứa hẹn mang lại trải nghiệm gõ phím tuyệt vời hơn bao giờ hết cho anh em Game thủ và cả dân văn phòng. Trải nghiệm gõ mượt mà với Switch DareU Dream được lube sẵn Điểm nổi bật của&nbsp; DareU EK87 V2 &nbsp;là việc trang bị switch Dream được lube sẵn.Dòng Switch Dream của Dareu mang đến cảm giác gõ mượt mà, độ nhạy cao cùng với độ bền ấn tượng lên tới hàng chục triệu lần nhấn để đảm bảo cả về trải nghiệm gõ lẫn độ bền bỉ cho EK87 V2. Bên cạnh đó, việc lube sẵn switch từ nhà máy giúp giảm ma sát, tạo cảm giác gõ phím êm ái và mượt mà khi sử dụng. Stab được cân chỉnh tốt hơn Phần Stabilizer trên DareU EK87 V2 đã được cân chỉnh lại, giúp tăng cường độ ổn định trên những phím dài như phím Space, phím Shift&nbsp;giúp giảm thiểu tiếng ồn và mang lại cảm giác gõ chắc chắn. Keycap PBT double shot siêu bền Một trong những cải tiến đáng chú ýtrên&nbsp; DareU EK87 V2 &nbsp;là việc sử dụng keycap PBT double shot. Với chất liệu PBT bền bỉ và công nghệ đúc 2 lớp, keycap không chỉ chống mòn tốt mà còn giúp giữ được độ sắc nét của ký tự trong suốt thời gian sử dụng dài. Hệ thống LED RGB đẹp mắt DareU EK87 V 2 được trang bị hệ thống&nbsp;LED Rainbow với ánh sáng chia theo từng hàng phím, tạo ra hiệu ứng', '{"Model":"Bàn Phím Cơ Dareu EK87 V2 Gray Black Switch Dream"}', 0, 1);
