INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1051782840', 'SP109191', '1051782840', 'https://www.maytinhbienhoa.vn/products/ban-phim-khong-day-rapoo-e9180p-1', 'BÀN PHÍM KHÔNG DÂY RAPOO E9180P', 'ban-phim-khong-day-rapoo-e9180p-1', 'brand_rapoo_385', 'cat_keyboards', 590000, 899000, 34, 472000, 24, 'in_stock', 'BÀN PHÍM KHÔNG DÂY RAPOO E9180P', 'Thông tin chi tiết Thương hiệu: Rapoo Kích thước: 336 x 110 x 4 mm Model: E9180P Xuất xứTrung Quốc Mô tả sản phẩm Bàn Phím Không Dây Rapoo E9180P Bàn Phím Không Dây Rapoo E9180P&nbsp; có &nbsp; kết nối không dây tốc độ cao&nbsp; 5.0Ghz , hoạt động trong vòng 10m, dễ dàng kết nối và sử dụng với bất kì máy tính nào có cổng kết nối USB. &nbsp; Rapoo E9180P&nbsp; có thiết kế siêu mỏng chỉ 5.6mm, đầy đủ các phím ký tự, số và 12 các phím chức năng (F1-F12), cho người dùng thao tác chính xác nhất. Các phím được khắc laser toàn bộ giúp cho chữ không bị bay hay mờ trong quá trình sử dụng lâu dài. Bạn có thể dễ dàng sử dụng&nbsp;&nbsp;mà không cần sử dụng phần mềm cài đặt riêng. Tính năng sản phẩm: - Công nghệ kế nối không dây 5GHz giúp tránh nhiễu sóng từ Bluetooth hay wifi, cho phép hoạt động ở khoảng cách 10m. - Tính năng Plug and Play bạn chỉ cần cắm đầu kết nối USB (Receiver) của bàn phím vào máy là có thể hoạt động và sử dụng. - Rapoo E9180P&nbsp; cho phép bạn thao tác các phím nóng trên các ứng dụng khi xem phim, nghe nhạc, soạn thảo văn bản hay giải trí nhanh chóng nhất. - Thiết kế siêu mỏng chỉ 5.6mm, làm nổi bật cá tính của bạn khi sử dụng các thiết bị. - Bàn phím có đầy đủ các phím chữ, phím số cùng 12 phím chức năng F1 - F12 với phím FN cho bạn thao tác trong công việc và giải trí dễ dàng và nhanh chóng. - Các ký tự của phím được khắc laser không bị bay màu, với màu trắng sáng trên nền màu đen giúp cho người dùng dễ đọc hơn, hỗ trợ tối đa cho những người có tầm nhìn kém. Th', '{"Model":"BÀN PHÍM KHÔNG DÂY RAPOO E9180P"}', 0, 1);
