INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1076499399', 'SP1084130', '1076499399', 'https://www.maytinhbienhoa.vn/products/ban-phim-co-aula-gaming-f2058-blue-sw-usb-led-rainbow', 'Bàn Phím Cơ AULA Gaming F2058 Blue Sw (USB, LED Rainbow)', 'ban-phim-co-aula-gaming-f2058-blue-sw-usb-led-rainbow', 'brand_aula_291', 'cat_keyboards', 689000, 689000, 0, 551200, 24, 'in_stock', 'Bàn Phím Cơ AULA Gaming F2058 Blue Sw (USB, LED Rainbow)', 'THÔNG SỐ KỸ THUẬT &nbsp; Kiểu dáng Full Size Kết nối Có dây Chuẩn kết nối USB Switch Blue Switch KEYCAP ABS Layout 104 phím Đèn Led LED Rainbows Màu sắc Đen Mô tả khác - Trọng lượng: 700g - Chiều dài dây: 1m2 - Kích thước bàn phím (LxWxH): 435 x 125 x 39 mm - Hệ điều hành tương thích: Windows / Mac Bàn phím cơ Phụ kiện Sách hướng dẫn sử dụng + Kê tay + Dụng cụ thay keycap &nbsp; &nbsp; BÀN PHÍM CƠ AULA F2058 BLUE SWITCH MECHANICAL KEYBOARD&nbsp; Trải nghiệm gõ chuyên nghiệp, thiết kế đậm chất gaming cùng khả năng tuỳ biến đèn LED tuyệt đẹp - đó chính là những gì bạn nhận được từ bàn phím cơ Aula F2058 Blue Switch Mechanical Keyboard. Với thiết kế fullsize tiện dụng, độ nhạy cao và cảm giác gõ tactile kèm âm thanh clicky đặc trưng của Blue Switch, sản phẩm chính là lựa chọn lý tưởng cho cả công việc văn phòng và chơi game giải trí. Thiết Kế Cao Cấp – Độ Hoàn Thiện Vượt Trội Aula F2058 sở hữu ngoại hình mạnh mẽ nhờ lớp vỏ trên bằng nhôm chắc chắn, kết hợp cùng chất liệu keycap nhựa ABS bền bỉ, mang đến cảm giác cao cấp ngay từ cái nhìn đầu tiên. Cấu trúc bàn phím Fullsize với 104 phím giúp người dùng thao tác đầy đủ và thuận tiện. Với cân nặng dao động từ 700g đến 820g (tuỳ phiên bản), bàn phím đảm bảo độ ổn định trong quá trình sử dụng lâu dài. Cảm Giác Gõ Đặc Trưng Nhờ Blue Switch Bàn phím được trang bị hệ thống Blue Switch, mang lại phản hồi chính xác, âm thanh clicky rõ ràng và cảm giác gõ rõ rệt từng phím. Đây là lựa chọn hoàn hảo cho những ai làm việc cần nhập liệu nhiều ', '{"Kiểu dáng":"Full Size","Kết nối":"Có dây","Chuẩn kết nối":"USB","Switch":"Blue Switch","KEYCAP":"ABS","Layout":"104 phím","Đèn Led":"LED Rainbows","Màu sắc":"Đen","Mô tả khác":"- Trọng lượng: 700g - Chiều dài dây: 1m2 - Kích thước bàn phím (LxWxH): 435 x 125 x 39 mm - Hệ điều hành tương thích: Windows / Mac","Bàn phím cơ":"Phụ kiện"}', 0, 1);
