INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1053746594', 'SP109674', '1053746594', 'https://www.maytinhbienhoa.vn/products/ban-phim-co-aula-f87-3-mode-den-trang-xanh-la-typec-2-4g-bluetooth-grey-wood-v3-switch-led-rgb', 'BÀN PHÍM CƠ AULA F87 3 MODE ĐEN TRẮNG XANH LÁ (TYPEC + 2.4G + BLUETOOTH, GREY WOOD V3 SWITCH, LED RGB)', 'ban-phim-co-aula-f87-3-mode-den-trang-xanh-la-typec-2-4g-bluetooth-grey-wood-v3-switch-led-rgb', 'brand_aula_291', 'cat_keyboards', 1250000, 1250000, 0, 1000000, 24, 'in_stock', 'BÀN PHÍM CƠ AULA F87 3 MODE ĐEN TRẮNG XANH LÁ (TYPEC + 2.4G + BLUETOOTH, GREY WOOD V3 SWITCH, LED RGB)', 'THÔNG SỐ KỸ THUẬT &nbsp; - Độ bền phím: 60 triệu lần bấm - Thời gian sử dụng sau khi sạc đầy pin: Khoảng 22 giờ (hiệu ứng ánh sáng mặc định)/ 266 giờ (khi tắt đèn) - Kết nối: 3 mode có dây Type-C, không dây 2.4G &amp; BT - Màu sắc: đen + trắng + xanh lá - Đèn nền: LED RGB - 16 loại hiệu ứng ánh sáng - Loại switch: Grey Wood V3 Switch - Hiệu ứng âm thanh khi gõ phím: Linear - Hot-Swap - Gasket mount - Số lượng phím: 87 phím - Hành trình phím: 4.0mm - Điện áp/dòng sạc: DC5V 600mA - Điện áp định mức: DC 3.7V (đầy đủ 4.2V) - Định mức dòng điện: 180mA @37V (hiệu ứng ánh sáng mặc định)/15 mA (tắt tất cả đèn) - Trọng lượng: Xấp xỉ 916g (không có cáp/bộ thu), 935g (với cáp/bộ thu) - Kích thước bàn phím (L x W x H): 365,90 x 139,00 x 41,10 +1 mm - Phụ kiện kèm theo: Sách hướng dẫn sử dụng + 2 Switch tặng kèm + Dây USB type-C + Dụng cụ thay keycap &nbsp;', '{"Model":"BÀN PHÍM CƠ AULA F87 3 MODE ĐEN TRẮNG XANH LÁ (TYPEC + 2.4G + BLUETOOTH, GREY WOOD V3 SWITCH, LED RGB)"}', 0, 1);
