INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1063425740', 'SP1081446', '1063425740', 'https://www.maytinhbienhoa.vn/products/chuot-zadez-gt-616m-rgb-gaming-black', 'Chuột Zadez GT-616M RGB Gaming Black', 'chuot-zadez-gt-616m-rgb-gaming-black', 'brand_zadez_382', 'cat_mice', 299000, 299000, 0, 239200, 24, 'in_stock', 'Chuột Zadez GT-616M RGB Gaming Black', 'Pro-Gaming Mouse - Thiết Kế Ergonomic Nút cuộn cao cấp, form chuột ôm sát lòng bàn tay, các nút nhấn được bố trí cực kỳ thuận tiện. Khu vực đỡ ngón tay cái được bố trí tinh tế, mang đến sự thoải mái khi trải nghiệm chuột trong thời gian dài, đồng thời nút chức năng cũng được bố trí tại khu vực này, là một ``tuyệt chiêu`` để người dùng vượt trội các game thủ khác. -Chuẩn Mực Của Độ Chính Xác Được trang bị PixArt PMW3330 - một trong những cảm biến tốt nhất hiện nay, GT-616M cho phép tùy chỉnh DPI lên đến 10.000 (qua phần mềm), giúp tất cả cú vẩy chuột đều chính xác đến từng milimet. -Thi Đấu Chuyên Nghiệp Với 9 nút chức năng, cấu hình 5 profiles, game thủ dễ dàng thiết lập và chuyển đổi phím chức năng tương ứng với 5 game khác nhau. Đặc biệt, phím Fire Button hỗ trợ tính năng nhả đạn liên tục và phím Easy Aim hỗ trợ khả năng ngắm bắn, giúp đường đạn trở nên chính xác hơn. -Chất Lượng Mang Đến Sự Hài Lòng Độ bền nút nhấn đến 20 triệu lần, dây bọc dù, đầu cáp USB mạ vàng, chống nhiễu tín hiệu cùng với hệ thống đăng ký bảo hành điện tử hiện đại nhất Việt Nam, ZADEZ GT-616M cam kết sẽ mang đến sự hài lòng tuyệt đối trong suốt quá trình trải nghiệm và vòng đời sản phẩm. -Dải Đèn LED RGB Tinh Tế 16.8 Triệu Màu Game thủ có thể tùy chỉnh cách hiển thị màu sắc, hiệu ứng phù hợp với phong cách cá nhân nhất. Từng dải đèn LED chạy dọc thân tạo ra không gian mạch ánh sáng cực đẹp mắt. -Bảo Hành Điện Tử Theo Serial Number Mỗi sản phẩm đều được định mã số định danh - Serial Number ̣(SN) - để', '{"PWN3330 PixArt CẢM BIẾN GAMING":"LED RGB 16,8 TRIỆU MÀU","Kích thước":"125 x 75,5 x 43 mm","Trọng lượng":"124 gms (chuột)","Chiều dài dây":"1.8 mét (dây bọc dù)","Độ phân giải":"1000/1500/2000/3000/5000/7200 DPI","Cảm biến":"Pixart PMW3330","Gia tốc":"30G/sec","Tốc độ IPS":"150inch/sec","Độ bền nút bấm":"Đến 20 triệu lần nhấn","Bảo hành":"Kích hoạt bảo hành điện tử, 12 tháng (1 đổi 1)"}', 0, 1);
