INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1032329638', 'SP010408', '1032329638', 'https://www.maytinhbienhoa.vn/products/chuot-adata-xpg-infarex-m20-gaming-black-1', 'CHUỘT ADATA XPG INFAREX M20 GAMING BLACK', 'chuot-adata-xpg-infarex-m20-gaming-black-1', 'brand_adata_347', 'cat_mice', 299000, 740000, 60, 239200, 24, 'in_stock', 'CHUỘT ADATA XPG INFAREX M20 GAMING BLACK', 'XPG INFAREX M20 Gaming Mouse Victory At Hand Kỹ năng của bạn trên chiến trường chỉ tốt khi vũ khí bạn sử dụng. Nâng cấp kho vũ khí của bạn với chuột chơi game XPG INFAREX M20! Với các công tắc OMRON đã được thử nghiệm tới 20 triệu lần nhấp, cảm biến 5.000 dpi và ánh sáng RGB, INFAREX M20 sẽ giúp đưa trò chơi của bạn lên một tầm cao mới. Switch OMRON bền bỉ Có thể điều chỉnh dpi, 5 mức cài đặt độ nhạy Hiệu ứng RGB thở Thiết kế gọn nhẹ Công tắc OMRON bền bỉ Bằng cách sử dụng các công tắc OMRON, INFAREX M20 cung cấp cho bạn độ chính xác để bắn trúng mục tiêu và thực hiện nhiệm vụ một cách hiệu quả. Nó đã được thử nghiệm tới 20 triệu lần nhấp chuột, mang lại cho bạn một con chuột bền bỉ có thể sử dụng trong thời gian dài. Adjustable DPI Với cảm biến quang học 5.000 dpi, INFAREX M20 mang lại độ chính xác đáng kinh ngạc để giúp bạn đi trước đối thủ một bước. Nút điều chỉnh dpi năm đoạn cho phép bạn thay đổi tốc độ con trỏ để điều khiển tối ưu trong các tình huống khác nhau. RGB Lighting Effects INFAREX M20 đi kèm với đầy đủ các hiệu ứng ánh sáng RGB sẽ giúp bạn có tư duy đúng đắn trước hoặc trong một trận chiến căng thẳng. Thiết kế công thái học mang lại sự thoải mái Thiết kế công thái học của INFAREX M20 cho phép nó vừa vặn thoải mái trong tay bạn để có tư thế đặt tay tự nhiên và thoải mái. Mọi chuyển động, bao gồm nhấc chuột và quét trên bàn di chuột, đều có thể được thực hiện nhanh chóng, dễ dàng và chính xác.', '{"Model":"CHUỘT ADATA XPG INFAREX M20 GAMING BLACK"}', 0, 1);
