INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1050493440', 'SP108859', '1050493440', 'https://www.maytinhbienhoa.vn/products/chuot-asus-tuf-m3-gen-ii', 'CHUỘT ASUS TUF M3 GEN II', 'chuot-asus-tuf-m3-gen-ii', 'brand_asus_316', 'cat_mice', 359000, 549000, 35, 287200, 24, 'in_stock', 'CHUỘT ASUS TUF M3 GEN II', 'Thông số kỹ thuật : Hãng sản xuất: Asus Bảo hành: 24 Tháng Kiểu kết nối: Có dây Độ nhạy (DPI): Lên đến 8000 Cảm biến: PAW3318 Số nút bấm: 6 Tuổi thọ switch: Lên đến 60 triệu&nbsp;lần nhấn Kích thước: 123x68x40mm Khối lượng: 63g OS: Windows® 10,&nbsp;Windows® 11 &nbsp; Đánh giá chi tiết chuột Asus TUF Gaming M3 Gen II &nbsp; Asus TUF Gaming M3 được biết đến là dòng&nbsp;chuột máy tính&nbsp;sở hữu hiệu năng ấn tượng, khả năng tương thích cao, nút bấm được bố trí thông minh thuận tiện cho mọi nhu cầu sử dụng. Đặc biệt, ở thế hệ Gen II hãng còn tích hợp thêm nhiều công nghệ hiện đại. Hứa hẹn sẽ là một trong những dòng chuột gaming rất đáng trải nghiệm. Thiết kế công thái học cùng trọng lượng siêu nhẹ &nbsp; &nbsp; Một trong những điểm ấn tượng trên dòng chuột gaming ASUS TUF M3 Gen II chính là sở hữu thiết kế&nbsp;chuột công thái học&nbsp;ôm trọng lòng bàn tay giúp cho mọi thao tác di chuột trở nên dễ dàng, tạo cảm giác thoải mái khi sử dụng trong suốt thời gian dài. Đồng thời, sở hữu trọng lượng siêu nhẹ chỉ 59g người chơi sẽ chiếm ưu thế với các tựa game bắn súng cần thao tác nhanh và chính xác. &nbsp; &nbsp; Ngoài việc mang kiểu dáng công thái học,&nbsp;Asus TUF Gaming M3 Gen II còn mang thiết kế vô cùng đẹp mắt tạo điều kiện Build góc máy làm việc &amp; giải trí độc đáo khi kết hợp cùng các thiết bị Gaming Gear khác như&nbsp;bàn phím cơ, tai nghe gaming,....tăng thêm phấn khởi cùng các tựa game yêu thích. Cảm biến quang học điều chỉnh DPI lên đến 8000 &nbsp; &nbsp; Nâng cao t', '{"Hãng sản xuất:":"Asus","Bảo hành:":"24 Tháng","Kiểu kết nối:":"Có dây","Độ nhạy (DPI):":"Lên đến 8000","Cảm biến:":"PAW3318","Số nút bấm:":"6","Tuổi thọ switch:":"Lên đến 60 triệu&nbsp;lần nhấn","Kích thước:":"123x68x40mm","Khối lượng:":"63g","OS:":"Windows® 10,&nbsp;Windows® 11"}', 0, 1);
