INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1032329651', 'SP010409', '1032329651', 'https://www.maytinhbienhoa.vn/products/chuot-adata-xpg-primer-gaming-black-rgb', 'CHUỘT ADATA XPG PRIMER GAMING BLACK RGB', 'chuot-adata-xpg-primer-gaming-black-rgb', 'brand_adata_347', 'cat_mice', 379000, 1190000, 68, 303200, 24, 'in_stock', 'CHUỘT ADATA XPG PRIMER GAMING BLACK RGB', 'Chuột chơi game XPG PRIMER ● Bề mặt chụp đôi bền với PBT ● Trọng lượng cân bằng – 98g ± 5% ● Tay cầm bên có kết cấu cho cảm giác thoải mái trong thời gian dài ● Cáp bện siêu nhẹ ● Hiệu ứng ánh sáng RGB có thể lựa chọn ● Cảm biến quang 12000 DPI PMW3360 ● Công tắc cơ Omron với 20 triệu Độ bền của lần nhấp ● Bánh xe cuộn xúc giác để kiểm soát tốt hơn Thông số kỹ thuật :&nbsp; Giao diện :USB loại ACông tắc điện: Omron với xếp hạng 20 triệu lần nhấp &nbsp; Độ phân giải: 400/800/1600/3200/6400/12000 dpi Kích thước:126 x 65,6 x 37,9 mm / 4,9 x 2,58 x 1,49 inch Cân nặng : 98g ± 5% Tối đa Sự tăng tốc: 50G Báo cáo Tỷ lệ: 250/500/1000 Hz Hiệu ứng ánh sáng: Sóng màu, Thở, Tĩnh, Tắt Yêu cầu hệ thống: Windows 10/8/7 Vôn: 5V Hiện hành: 220mA Chiều dài cáp: 1,8m Chứng nhận: CE / FCC / BSMI / KC / VCCI / RCM / EAC bảo hành: 2 năm Giới thiệu chuột chơi game XPG PRIMER.&nbsp;Cho dù bạn là một cựu chiến binh thích một con chuột đơn giản với thái độ hay một người mới bắt đầu tìm kiếm khả năng chơi game của mình, XPG PRIMER là dành cho bạn.&nbsp;Thiết bị chuyển mạch Sporting Omron với xếp hạng 20 triệu lần nhấp, cảm biến quang học lên đến 12000 DPI và vô số thiết kế mang lại sự thoải mái, chính xác, độ bền và sự tinh tế, XPG PRIMER đã sẵn sàng để hoàn thiện trò chơi của bạn! Bề mặt Double-Shot bền với PBT Vỏ ngoài của XPG PRIMER được làm từ PBT bắn kép siêu bền cho bề mặt nhẵn nhưng không trơn, luôn sạch sẽ và không bị mài mòn hoặc phai màu sau thời gian dài sử dụng. Thoải mái trong thời gian dài', '{"Model":"CHUỘT ADATA XPG PRIMER GAMING BLACK RGB"}', 0, 1);
