INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1033936712', 'SP104864', '1033936712', 'https://www.maytinhbienhoa.vn/products/chuot-razer-deathadder-essential-ergonomic-gaming-black', 'Chuột Razer DeathAdder Essential Ergonomic Gaming Black', 'chuot-razer-deathadder-essential-ergonomic-gaming-black', 'brand_razer_388', 'cat_mice', 419000, 1290000, 68, 335200, 24, 'in_stock', 'Chuột Razer DeathAdder Essential Ergonomic Gaming Black', 'Razer DeathAdder là 1 trong những con chuột nổi tiếng nhất Thế Giới và được công nhận bởi hàng triệu người dùng trên toàn Thế Giới. Với hàng triệu sản phẩm được bán ra và hàng chục giải thưởng uy tín, DeathAdder đã tạo nên 1 đế chế kể từ khi được ra mắt. Và Razer DeathAdder Essential là 1 phiên bản mới nhất và là sự hồi sinh của 1 trong những con chuột nổi tiếng nhất. Thiết kế truyền thống Razer DeathAdder Essential vẫn giữ nguyên thiết kế công thái học từ trước đến nay. Với thiết kế kiểu cầm ôm tay, thoải mái khi sử dụng trong thời gian dài. Cảm biến quang học 6400 DPI Razer Switch với độ bền 10 triệu lần bấm 5&nbsp; phím bấm có thể lập trình Thiết kế công thái học cho người thuận tay phải Gia tốc 220 IPS / 30G Tần số quét 1000Hz Trang bị đèn led màu xanh lá cây ở logo và con lăn Tương thích với Razer Synapse 3 Kích thước: 127 x 73 x 43 (mm) (Dài x Rộng x Cao) Trọng lượng: 96G', '{"Model":"Chuột Razer DeathAdder Essential Ergonomic Gaming Black"}', 0, 1);
