INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1033936719', 'SP104865', '1033936719', 'https://www.maytinhbienhoa.vn/products/chuot-razer-deathadder-essential-ergonomic-gaming-white', 'Chuột Razer DeathAdder Essential Ergonomic Gaming White', 'chuot-razer-deathadder-essential-ergonomic-gaming-white', 'brand_razer_388', 'cat_mice', 419000, 990000, 58, 335200, 24, 'in_stock', 'Chuột Razer DeathAdder Essential Ergonomic Gaming White', 'Thiết kế công thái học, thoải mái khi cầm Cảm biến quang học với độ phân giải 6400 DPI 5 nút bấm, tuổi thọ 10 triệu lần nhấp Hỗ trợ phần mềm điều khiển Razer Synapse 3 (Beta) Tốc độ tối đa: 220 IPS Gia tốc tối đa: 30G Tần số quét: 1000 Hz Chiều dài cáp: 1,8m Kích thước: 127 x 73 x 43mm Chuột Chơi Game Có Dây Razer DeathAdder Essential &nbsp;-&nbsp;Trong hơn một thập kỷ qua, dòng Razer DeathAdder đã trở thành trụ cột trong đấu trường esports toàn cầu.&nbsp;Nó đã đạt được danh tiếng và độ tin cậy bởi độ bền và thiết kế công thái học tuyệt vời. Thiết kế công thái học của dòng Razer DeathAdder Essential vẫn giữ được hình thức công thái học cổ điển vốn là đặc trưng của các thế hệ Razer DeathAdder trước đây. Thiết kế vừa vặn với lòng bàn tay, thoải mái khi lướt, cho phép bạn duy trì hiệu suất cao trong suốt trận đấu, đảm bảo bạn sẽ không bao giờ chùn bước trong sức nóng của trận chiến. Sử dụng cảm biến quang 6.400 DPI, cho phép vuốt chuột nhanh và chính xác, cung cấp khả năng kiểm soát tốt hơn cho các nhu cầu chơi game thiết yếu nhất. 5 nút Hyperesponse được lập trình độc lập cung cấp cho bạn các điều khiển nâng cao phù hợp với lối chơi của mình Sử dụng Switch cơ Razer cao cấp từng giành được nhiều giải thưởng, độ bền phím nhấn lên đến 10 triệu lần nhấp. Razer Deathadder Essential đã nâng cấp báng cầm chống trượt, giúp tăng cường kiểm soát và độ chính xác đối với chuột trong quá trình nâng và vuốt nhanh. Hỗ trợ phần mềm điều khiển Razer Synapse 3 (Beta) cho phép bạn lập trình các t', '{"Model":"Chuột Razer DeathAdder Essential Ergonomic Gaming White"}', 0, 1);
