INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1072461963', 'SP1083132', '1072461963', 'https://www.maytinhbienhoa.vn/products/chuot-mchose-g3-v2-gaming-wireless-white-3-modes', 'Chuột MCHOSE G3 V2 Gaming Wireless White 3 Modes', 'chuot-mchose-g3-v2-gaming-wireless-white-3-modes', 'brand_mchose_447', 'cat_mice', 419000, 419000, 0, 335200, 24, 'in_stock', 'Chuột MCHOSE G3 V2 Gaming Wireless White 3 Modes', 'THÔNG SỐ KỸ THUẬT &nbsp; Thương hiệu MCHOSE Bảo hành 12 Tháng Cảm biến Optical Độ phân giải (DPI) 12000 Đèn LED Có Công nghệ cảm biến PAW3311 Kết nối Bluetooth,&nbsp;Type-C,&nbsp;Wireless Tốc độ tối đa 300 IPS Công nghệ kết nối Có dây,&nbsp;Không dây Trọng lượng 59 g Màu sắc Black, Blue, White &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Độ chính xác vượt trội với cảm biến PAW3395 Chuột G3 V2 Pro trang bị cảm biến PAW3395 hiệu năng cao, tiết kiệm điện năng, cho độ phân giải lên đến 26.000 DPI, tốc độ theo dõi 650 IPS và gia tốc 50G. Tận hưởng tốc độ phản hồi nhanh như chớp và độ chính xác hoàn hảo đến từng pixel – lý tưởng cho chơi game chuyên nghiệp và làm việc hiệu quả ở tốc độ cao. &nbsp; Độ bám toàn diện — Thiết kế công thái học cổ điển được nâng cấp. Được thiết kế cho bàn tay nhỏ đến trung bình với hình dạng đối xứng. Thiết kế lại kiểu dáng chuột cổ điển tương thích với các kiểu cầm chuột claw, palm và fingertip, tạo nên sự cân bằng hoàn hảo giữa sự thoải mái và khả năng điều khiển linh hoạt, giúp thao tác dễ dàng trong suốt các phiên chơi game dài. &nbsp; Thiết kế siêu nhẹ Nhờ tối ưu hóa cấu trúc cơ khí và khả năng tiêu thụ điện năng hiệu quả, G3 V2 chỉ nặng 59 gram. Nó mang đến trải nghiệm điều khiển cực kỳ nhạy bén, cân bằng hoàn hảo cho các thao tác nhanh chóng đồng thời giảm thiểu hiệu quả sự mệt mỏi khi sử dụng trong thời gian dài. &nbsp; Thời lượng pin cực dài Khi đang say mê chơi game, điều cuối cùng bạn muốn là phải dừng lại và sạc chuột. Pin dung lượng cao 800mAh mang đế', '{"MCHOSE":"12 Tháng","Optical":"12000","Có":"PAW3311","Bluetooth,&nbsp;Type-C,&nbsp;Wireless":"300 IPS","Có dây,&nbsp;Không dây":"59 g"}', 0, 1);
