INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1071776396', 'SP1083001', '1071776396', 'https://www.maytinhbienhoa.vn/products/chuot-machenike-l9-x1-wireless-black', 'Chuột Machenike L9 X1 Wireless - Black', 'chuot-machenike-l9-x1-wireless-black', 'brand_machenike_645', 'cat_mice', 590000, 590000, 0, 472000, 24, 'in_stock', 'Chuột Machenike L9 X1 Wireless - Black', 'THÔNG SỐ KỸ THUẬT &nbsp; Thương hiệu Machenike Bảo hành 12 Tháng Công nghệ kết nối Có dây,&nbsp;Không dây Kết nối Bluetooth,&nbsp;Wireless,&nbsp;USB-C Cảm biến Optical Công nghệ cảm biến PAW3311 Độ phân giải (DPI) 8500 Số nút bấm 6 Đèn LED Không Trọng lượng 58 g Màu sắc Black, Blue, White &nbsp; Chuột Machenike L9 X1 Tri-mode&nbsp;(Có dây / 2.4G Wireless / Bluetooth 5.0, 12000 DPI, PAW 3311) Chuột Machenike L9 X1 Tri-mode &nbsp;là chuột máy tính với 03 chế độ kết nối Có dây / 2.4G Wireless / Bluetooth 5.0 linh hoạt để kết nối nhiều thiết bị laptop,&nbsp; máy tính để bàn , hay MacBook.&nbsp; Machenike L9 X1 &nbsp;là&nbsp; chuột không dây &nbsp;nổi bật từ thương hiệu&nbsp; Machenike , mang đến sự kết hợp giữa trọng lượng siêu nhẹ, hỗ trợ Polling rate 1000Hz, là sản phẩm lý tưởng cho game thủ chuyên nghiệp và người dùng yêu thích sự linh hoạt. Hiệu năng của&nbsp; Chuột Machenike L9&nbsp; được tối ưu nhờ cảm biến&nbsp; PAW 3311 , hỗ trợ DPI lên tới 12000, đảm bảo phản hồi chính xác trong mọi trận đấu.&nbsp; Chuột Machenike L9 X1 &nbsp;là mẫu chuột được thiết kế dành cho game thủ lẫn người dùng văn phòng, với khả năng kết nối linh hoạt và hiệu năng ổn định. &nbsp; TỔNG QUAN CHUỘT&nbsp;MACHENIKE&nbsp;L9 X1 TRI-MODE Tên sản phẩm: Chuột Machenike L9 X1 Tri-mode Kết nối: Có dây / 2.4G Wireless / Bluetooth 5.0 Kích thước: 122 x 72 x 39 mm Trọng lượng: 58g ± 6g Cảm biến: PixArt PAW 3311 DPI: tối đa 12.000 DPI – điều chỉnh qua phần mềm Polling Rate: 1000Hz Switch: Huano – độ bền 80 triệu', '{"8500":"6","Machenike":"12 Tháng","Có dây,&nbsp;Không dây":"Bluetooth,&nbsp;Wireless,&nbsp;USB-C","Optical":"PAW3311","Không":"58 g"}', 0, 1);
