INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1012167899', 'SP002848', '1012167899', 'https://www.maytinhbienhoa.vn/products/chuot-logitech-g402-hyperion-fury', 'CHUỘT LOGITECH G402 HYPERION FURY NEW', 'chuot-logitech-g402-hyperion-fury', 'brand_logitech_591', 'cat_mice', 619000, 1000000, 38, 495200, 24, 'in_stock', 'CHUỘT LOGITECH G402 HYPERION FURY NEW', 'THÔNG SỐ KỸ THUẬT CHUỘT LOGITECH G402 HYPERION FURY đến từ thương hiệu&nbsp; MOUSE - CHUỘT LOGITECH Hãng sản xuất Logitech Model G402 Độ phân giải 240-4000 dpi Tăng tốc tối đa &gt;16G Tốc độ tối đa &gt;500 ips Định dạng dữ liệu USB 16 bit/trục Tốc độ báo cáo USB 1000 Hz (1ms) Bộ vi xử lý 32-bit Lướt Hệ số ma sát động -: &nbsp;0,09 µ (k)/&nbsp;Hệ số ma sát tĩnh -: &nbsp;0,14 µ (s) Độ bền Các nút (Trái/Phải): 20 triệu lần nhấp/ Chân: 250 km (155,3) Tính năng Cảm biến lai Fusion Engine 8 nút có thể lập trình Chuyển đổi DPI tức thì Bộ xử lý ARM 32 bit Báo cáo 1 mili giây Nhấp chuột tốc độ cao USB tốc độ tối đa Kích thước (C x R x D) 136 mm x&nbsp;72 mm x&nbsp;41 mm Trọng lượng 144 gram (kèm dây 108 gram (không kèm dây) &nbsp; &nbsp; THEO DÕI TỐC ĐỘ CAO FUSION ENGINE Công nghệ cảm biến tinh vi để chơi game siêu nhanh Hyperion Fury kết hợp cảm biến quang học sử dụng công nghệ Logitech Delta Zero™ với cảm biến lai Fusion Engine™ độc quyền cho phép tốc độ theo dõi vượt quá 500 IPS. 8 NÚT CÓ THỂ LẬP TRÌNH Tùy chỉnh để phù hợp với kiểu chơi game của bạn Tùy chỉnh chuột với 8 nút có thể lập trình. Cho dù bạn muốn ném lựu đạn hay nhanh chóng vào kho vũ khí của mình, tất cả đều ở trong tầm tay. Phần mềm chơi game của Logitech (Logitech Gaming Software) tùy chọn khiến cho việc cài đặt dễ dàng. CHUYỂN ĐỔI DPI TỨC THÌ 4 cài đặt để điều khiển&nbsp; Gaming gear cao cấp cách chơi tốt hơn Chuyển đổi tức thì giữa bốn cài đặt DPI. Bắn tỉa kẻ địch trên khắp bản đồ (250 DPI) trước khi rút lui trong ', '{"Hãng sản xuất":"Logitech","Model":"G402","Độ phân giải":"240-4000 dpi","Tăng tốc tối đa":"&gt;16G","Tốc độ tối đa":"&gt;500 ips","Định dạng dữ liệu USB":"16 bit/trục","Tốc độ báo cáo USB":"1000 Hz (1ms)","Bộ vi xử lý":"32-bit","Lướt":"Hệ số ma sát động -: &nbsp;0,09 µ (k)/&nbsp;Hệ số ma sát tĩnh -: &nbsp;0,14 µ (s)","Độ bền":"Các nút (Trái/Phải): 20 triệu lần nhấp/ Chân: 250 km (155,3)","Tính năng":"Cảm biến lai Fusion Engine 8 nút có thể lập trình Chuyển đổi DPI tức thì Bộ xử lý ARM 32 bit Báo cáo 1 mili giây Nhấp chuột tốc độ cao USB tốc độ tối đa","Kích thước (C x R x D)":"136 mm x&nbsp;72 mm x&nbsp;41 mm"}', 0, 1);
