INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1028067969', 'SP009078', '1028067969', 'https://www.maytinhbienhoa.vn/products/chuot-logitech-g304-white-edition-wireless', 'CHUỘT LOGITECH G304 WHITE EDITION WIRELESS', 'chuot-logitech-g304-white-edition-wireless', 'brand_logitech_591', 'cat_mice', 749000, 1090000, 31, 599200, 24, 'in_stock', 'CHUỘT LOGITECH G304 WHITE EDITION WIRELESS', 'Kích thước 116.6 x 62.15 x 38.2 ( mm ) ( Dài x Rộng x Cao ) Trọng lượng 99g Cảm biến HERO ™ Độ phân giải 200 –&nbsp;12000&nbsp;DPI Tăng tốc tối đa &nbsp;&gt; 40 G 5 Tốc độ tối đa &gt; 400 IPS 6 Tốc độ báo cáo không dây 1000Hz ( 1ms ) Công nghệ LIGHTSPEED Có Bộ vi xử lý ARM 32-bit Tuổi thọ pin 250 giờ Bộ nhớ tích hợp 1 cấu hình Hệ thống Ứng lực Nút Cơ học Tương thích phần mềm Logitech Gaming Software Công nghệ không dây Lightspeed G304 là chuột chơi game không dây LIGHTSPEED được thiết kế cho hiệu suất thực sự với các đột phá công nghệ mới nhất ở mức giá thành phù hợp. Đó là chơi game không dây thế hệ mới, hiện đã sẵn sàng cho mọi game thủ.&nbsp;Thông qua chế tạo và thiết kế đầu cuối, Logitech G đã phát triển một giải pháp không dây mạnh mẽ để giải quyết vấn đề cơ bản của độ trễ, độ ổn định và khả năng kết nối. Kết quả cuối cùng là LIGHTSPEED, giải pháp không dây cấp độ chuyên gia đạt được hiệu suất như có dây. Thời gian sử dụng pin siêu dài Cảm biến HERO và công nghệ LIGHTSPEED không dây đem lại hiệu suất đỉnh cao cho phép bạn chơi game trong hàng tháng. Nó đem lại tới 250 giờ hoạt động chỉ trên một quả pin AA. Nó có thể được điều chỉnh để sử dụng trong tới 9 tháng ở mức thông thường trong chế độ Bền. Có thể chọn chế độ này qua Phần mềm Chơi game của Logitech.Được kiểm nghiệm trên Bàn di chuột Chơi game G240 của Logitech&nbsp;Phần mềm Chơi game của Logitech (Logitech Gaming Software), cũng như đèn chỉ báo trên G304 sẽ thông báo cho bạn khi mức pin còn lại 15%. Cảm biến HERO H', '{"Kích thước":"116.6 x 62.15 x 38.2 ( mm ) ( Dài x Rộng x Cao )","Trọng lượng":"99g","Cảm biến":"HERO ™","Độ phân giải":"200 –&nbsp;12000&nbsp;DPI","Tăng tốc tối đa":"&nbsp;&gt; 40 G 5","Tốc độ tối đa":"&gt; 400 IPS 6","Tốc độ báo cáo không dây":"1000Hz ( 1ms )","Công nghệ LIGHTSPEED":"Có","Bộ vi xử lý":"ARM 32-bit","Tuổi thọ pin":"250 giờ","Bộ nhớ tích hợp":"1 cấu hình","Hệ thống":"Ứng lực Nút Cơ học"}', 0, 1);
