INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1061924064', 'SP1081223', '1061924064', 'https://www.maytinhbienhoa.vn/products/chuot-razer-cobra-black-gaming', 'Chuột Razer Cobra Black Gaming', 'chuot-razer-cobra-black-gaming', 'brand_razer_388', 'cat_mice', 779000, 779000, 0, 623200, 24, 'in_stock', 'Chuột Razer Cobra Black Gaming', 'Thông số kỹ thuật : Hãng sản xuất: Razer Bảo hành: 24 Tháng Model: Razer Cobra Màu sắc: Đen Kiểu kết nối: Có dây Độ nhạy ( DPI ): 8500 Cảm biến: 8500 DPI Optical Sensor Số nút bấm: 90 Triệu lần nhấn Switch: Optical Mouse Switches Gen-3 Kích thước: Length: 119.6 mm / 4.71 in Width: 62.5 mm / 2.46 in Height: 38.1 mm / 1.50 in Khối lượng: 58 Gram Phụ kiện: Hướng dẫn thông tin sản phẩm quan trọng Đánh giá chi tiết chuột Razer Cobra Razer Cobra dòng chuột chơi game sở hữu thiết kế đối xứng giúp các thao tác di chuột thêm phần chắc chắn. Đồng thời, trang bị lên đến 6 nút bấm được bố trí thông minh dọc thân chuột giúp cho các thao tác xử lý thêm phần hiệu quả. Hứa hẹn đây sẽ là một trong những dòng chuột máy tính chơi game rất đáng sở hữu đến từ nhà Razer đấy nhé! Thiết kế độc đáo, form cầm đối xứng &nbsp; &nbsp; Thiết kế độc đáo được thể hiện qua các chi tiết góc cạnh cùng tone màu đen chủ đạo, Razer mang đến thị trường&nbsp;chuột máy tính&nbsp;chơi game dòng sản phẩm sở hữu thẩm mỹ cao và hiệu năng ấn tượng. Nhờ vào form cầm đối xứng giúp ôm sát lòng bàn tay mang đến cảm giác chắc chắn khi di chuột giúp bạn chiếm lợi thế trong các tựa game bắn súng FPS. Đồng thời, nhờ vào thiết kế có phần gọn gàng&nbsp;hơn so với các dòng chuột gaming ở cùng phân khúc người chơi có thể kết hợp với các phụ kiện chơi game khác có thể kể đến như&nbsp;bàn phím không dây,&nbsp;tai nghe Bluetooth,...để tạo nên góc máy gọn gàng mang tính thẩm mỹ cao.&nbsp; Hệ thống led chiếu sáng Razer Chroma RGB &nbsp; ', '{"Hãng sản xuất:":"Razer","Bảo hành:":"24 Tháng","Model:":"Razer Cobra","Màu sắc:":"Đen","Kiểu kết nối:":"Có dây","Độ nhạy ( DPI ):":"8500","Cảm biến:":"8500 DPI Optical Sensor","Số nút bấm:":"90 Triệu lần nhấn","Switch:":"Optical Mouse Switches Gen-3","Kích thước:":"Length: 119.6 mm / 4.71 in Width: 62.5 mm / 2.46 in Height: 38.1 mm / 1.50 in","Khối lượng:":"58 Gram","Phụ kiện:":"Hướng dẫn thông tin sản phẩm quan trọng"}', 0, 1);
