INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1032329783', 'SP010413', '1032329783', 'https://www.maytinhbienhoa.vn/products/tai-nghe-adata-xpg-emix-h20-7-1-rgb-gaming-black', 'TAI NGHE ADATA XPG EMIX H20 7.1 RGB TRƯNG BÀY CHƯA SỬ DỤNG BH 3 THÁNG', 'tai-nghe-adata-xpg-emix-h20-7-1-rgb-gaming-black', 'brand_adata_347', 'cat_headsets', 169000, 499000, 66, 135200, 24, 'in_stock', 'TAI NGHE ADATA XPG EMIX H20 7.1 RGB TRƯNG BÀY CHƯA SỬ DỤNG BH 3 THÁNG', 'Tai nghe Chơi game XPG EMIX H20 ● Độ chính xác vị trí cùng với âm thanh surround 7.1 ảo. ● Âm thanh đắm chìm với âm thanh HiFi 50mm ● Tìm đúng tâm trạng cho trận chiến bằng RGB ● Micrô có thể điều chỉnh Thông số kỹ thuật : + Màu sắc: Đen + Kích thước (Dài x Rộng x Cao): 212 x 85 x 205 mm + Trọng lượng của tai nghe : 305g + Thiết Bị Điều Khiển : Ф50 mm + Loại Tần Số:&nbsp; 20 – 20k Hz + Trở Kháng : 32Ω + Độ Nhạy : 106dB + Chiều Mic: Đẳng hướng + Mic Tháo Lắp Dễ Dàng : No + Giao diện USB: Hiệu ứng ánh sáng RGB + Bảo hành:&nbsp; 2 năm + Định mức dòng &lt;200mA + Chiều Dài Cáp Nối : 2.2m + Điện áp vận hành : 5V + Hiệu suất âm thanh:&nbsp; Virtual 7.1 channel surround + OS compatibility Windows : 10/8/7 + Chứng nhận CE / FCC / KC / VCCI / RCM / EAC Trong thế giới phiêu lưu mạo hiểm, phản ứng chính xác và phản ứng nhanh là chìa khóa quan trọng để bạn hạ sát cấu rỉa máu trong hàng quân địch! Tai nghe chơi game H20 được tích hợp kênh âm thanh vòm ảo 7.1, có thể củng cố nhận thức của người chơi về môi trường xung quanh. Nó vẫn có thể nghe chính xác vị trí âm thanh, phản ứng kịp thời và đánh bại kẻ thù trong một trận chiến khốc liệt; được trang bị bộ trình điều khiển chất lượng cao 50mm, mang đến nhiều cấp độ Hiệu ứng âm thanh gây sốc tại chỗ, tạo ra trải nghiệm chiến đấu thực tế sống động, với hiệu ứng ánh sáng RGB đầy màu sắc và thiết kế bịt tai nhẹ, người chơi có thể thách thức giới hạn của mình trong trạng thái nêu trên tận hưởng chất lượng âm thanh đáng kinh ngạc trong khi thực hi', '{"Model":"TAI NGHE ADATA XPG EMIX H20 7.1 RGB TRƯNG BÀY CHƯA SỬ DỤNG BH 3 THÁNG"}', 0, 1);
