INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1063425884', 'SP1081452', '1063425884', 'https://www.maytinhbienhoa.vn/products/gia-treo-tai-nghe-zadez-zhs-701g-usb-3-in-1-pink-gaming', 'Giá Treo Tai Nghe ZADEZ ZHS-701G USB 3 in 1 Pink Gaming', 'gia-treo-tai-nghe-zadez-zhs-701g-usb-3-in-1-pink-gaming', 'brand_zadez_382', 'cat_headsets', 359000, 359000, 0, 287200, 24, 'in_stock', 'Giá Treo Tai Nghe ZADEZ ZHS-701G USB 3 in 1 Pink Gaming', '&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Headset Stand -Thiết Kế Tinh Tế ZADEZ ZHS-701GP mang phong cách hiện đại, bắt kịp xu hướng giới trẻ -Hub USB Tiện Dụng Có 2 cổng USB 3.0 truyền dữ liệu tốc độ cao, mở rộng kết nối và đáp ứng nhiều mục đích sử dụng khác nhau. -Tích Hợp Mouse Bungee Một phụ kiện rất cần thiết đi cùng gaming mouse có dây. Hạn chế gập/gãy dây, tăng cường không gian để các thao tác bằng chuột khi chơi Game thoải mái hơn. Đồng thời giúp góc Gaming của bạn trông chất hơn rất nhiều. -Đèn LED RGB Tinh Tế ZADEZ ZHS-701GP có hệ thống đèn LED RGB viền theo khung đế treo đẹp mắt. -Hiệu Ứng Ánh Sáng Đẹp Mắt Với 8 hiệu ứng ánh sáng tuyệt đẹp thay đổi chỉ bằng thao tác chạm qua nút cảm ứng -Bảo Hành Điện Tử Theo Serial Number Mỗi sản phẩm đều được định mã số định danh - Serial Number ̣(SN) - để toàn bộ quá trình từ sản xuất đến đóng gói thành phẩm đều được ghi vào hệ thống. Số SN sẽ được dùng để kích hoạt bảo hành điện tử tại website&nbsp; psi.zadez.vn Thông Số Kỹ Thuật LED RGB 16,8 TRIỆU MÀU CHẠM CẢM ỨNG THAY ĐỔI HIỆU ỨNG ÁNH SÁNG RGB HUB USB 3.0 TRUYỀN DỮ LIỆU TỐC ĐỘ CAO &nbsp; Kích thước 252.5 x 128.5 x 128.5 mm Trọng lượng 384 gram (đế treo) Hub USB 2 cổng USB 3.0 Tích hợp Mouse Bungee Màu sắc Hồng Đèn Led RGB 16,8 triệu màu Tương thích Windows 8/10 và Mac Bộ bán hàng tiêu chuẩn Hộp, đế treo tai nghe, cáp USB 3.0 Bảo hành Kích hoạt bảo hành điện tử, 12 tháng (1 đổi 1', '{"LED RGB 16,8 TRIỆU MÀU":"CHẠM CẢM ỨNG THAY ĐỔI HIỆU ỨNG ÁNH SÁNG RGB","Kích thước":"252.5 x 128.5 x 128.5 mm","Trọng lượng":"384 gram (đế treo)","Hub USB":"2 cổng USB 3.0","Tích hợp":"Mouse Bungee","Màu sắc":"Hồng","Đèn Led":"RGB 16,8 triệu màu","Tương thích":"Windows 8/10 và Mac","Bộ bán hàng tiêu chuẩn":"Hộp, đế treo tai nghe, cáp USB 3.0","Bảo hành":"Kích hoạt bảo hành điện tử, 12 tháng (1 đổi 1)"}', 0, 1);
