INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074526676', 'SP1083576', '1074526676', 'https://www.maytinhbienhoa.vn/products/tai-nghe-machenike-th60-gaming-wireless-earbuds-black', 'Tai Nghe Machenike TH60 Gaming Wireless Earbuds Black', 'tai-nghe-machenike-th60-gaming-wireless-earbuds-black', 'brand_machenike_645', 'cat_headsets', 590000, 590000, 0, 472000, 24, 'in_stock', 'Tai Nghe Machenike TH60 Gaming Wireless Earbuds Black', 'THÔNG SỐ KỸ THUẬT &nbsp; Model sản phẩm MACHENIKE TH60 Phương thức kết nối Bluetooth 5.4 Thiết bị tương thích Thiết bị Bluetooth phổ thông Khoảng cách kết nối Khoảng 10m Micro ENC 4 mic Khử tiếng ồn cuộc gọi Giao thức Bluetooth HSF / HFP / A2DP / AVRCP Giải mã âm thanh SBC / AAC Chip micro silicon kép 2718 Độ nhạy micro -38 ± 3dB @1kHz Driver Dynamic 10mm Trở kháng 32Ω Độ nhạy loa 105 ± 3dB @1kHz Dải tần 20Hz – 20kHz Pin tai nghe 40mAh Pin hộp sạc 400mAh Thời gian sạc Khoảng 1.5 giờ Thời gian sử dụng Khoảng 7 giờ Cổng sạc Type-C Tai Nghe Gaming Bluetooth True Wireless Machenike TH60 – Độ trễ siêu thấp, âm thanh chuẩn gaming, pin dùng cả ngày Tai nghe gaming Bluetooth True Wireless Machenike TH60 là mẫu tai nghe không dây hướng tới game thủ và người dùng đa thiết bị, nơi tốc độ phản hồi, chất lượng âm thanh và sự tiện lợi đều được đặt lên hàng đầu. Với kết nối Bluetooth 5.4, cùng độ trễ cực thấp, sản phẩm mang lại trải nghiệm gần như “real-time”, phù hợp cho cả gaming lẫn giải trí hàng ngày. &nbsp; Kết nối Bluetooth 5.4 – Linh hoạt mọi thiết bị TH60 hỗ trợ cả kết nối không dây Bluetooth 5.4, giúp người dùng dễ dàng sử dụng với nhiều thiết bị khác nhau như PC, laptop, điện thoại hay console. Đặc biệt, khả năng kết nối đồng thời 2 thiết bị giúp bạn có thể vừa chơi game trên PC, vừa nhận cuộc gọi từ điện thoại mà không cần kết nối lại. Trải nghiệm chuyển đổi mượt mà, tiện lợi trong thực tế sử dụng. Âm thanh Hi-Fi với driver 10mm – Nghe rõ từng chi tiết Tai nghe được trang bị driv', '{"Model sản phẩm":"MACHENIKE TH60","Phương thức kết nối":"Bluetooth 5.4","Thiết bị tương thích":"Thiết bị Bluetooth phổ thông","Khoảng cách kết nối":"Khoảng 10m","Micro ENC 4 mic":"Khử tiếng ồn cuộc gọi","Giao thức Bluetooth":"HSF / HFP / A2DP / AVRCP","Giải mã âm thanh":"SBC / AAC","Chip micro silicon kép":"2718","Độ nhạy micro":"-38 ± 3dB @1kHz","Driver":"Dynamic 10mm","Trở kháng":"32Ω","Độ nhạy loa":"105 ± 3dB @1kHz"}', 0, 1);
