INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1065118804', 'SP1081666', '1065118804', 'https://www.maytinhbienhoa.vn/products/tai-nghe-corsair-hs35-carbon-v2', 'TAI NGHE CORSAIR HS35 Carbon V2', 'tai-nghe-corsair-hs35-carbon-v2', 'brand_corsair_531', 'cat_headsets', 689000, 689000, 0, 551200, 24, 'in_stock', 'TAI NGHE CORSAIR HS35 Carbon V2', 'Thông số kỹ thuật: Thương hiệu: Corsair Bảo hành: 24 Tháng Model: Corsair HS35 v2&nbsp; Màu sắc: Đen Kiểu tai nghe Over-ear Kiểu kết nối: Có dây Microphone: Có Dây: Dài 1,8m Drivers: 50mm Tương thích: PC, Mac, PlayStation 4/5, Xbox One / Series XS, Nintendo Switch, Mobile devices &nbsp; Khả năng cách âm: Có &nbsp; Corsair HS35 V2 Multiplatform Carbon là chiếc tai nghe gaming được sở hữu tất cả những điểm nổi bật từ chất lượng thiết kế, âm thanh, thiết kế đều mang nét đột phá cao cấp.&nbsp; &nbsp; Tương thích đa nền tảng Tai nghe Corsair HS35 V2 Multiplatform Carbon được trang bị chuẩn kết nối 3.5mm Analog Headset, cho phép bạn dễ dàng kết nối với hầu hết các thiết bị gaming phổ biến hiện nay, từ PC, Mac, PS5, PS4, Xbox, Nintendo Switch cho đến các thiết bị di động. Bạn sẽ không còn phải lo lắng về vấn đề tương thích, thoải mái tận hưởng âm thanh chất lượng cao trên mọi nền tảng yêu thích. &nbsp; Mang đến âm trường rộng Sức mạnh của Corsair nằm ở cặp driver 50mm tùy chỉnh, mang đến âm trường rộng và chi tiết. Bạn sẽ được trải nghiệm âm thanh sống động, chân thực. Bất kể thể loại game nào, Corsair HS35 V2 cũng sẽ tái hiện âm thanh một cách trung thực và sống động nhất. Chất lượng âm thanh tuyệt vời Không chỉ dừng lại ở âm trường rộng, Corsair HS35 V2 Multiplatform Carbon còn mang đến chất lượng âm thanh vượt trội. Âm bass mạnh mẽ, âm mid rõ ràng và âm treble sắc nét tạo nên một trải nghiệm âm thanh cân bằng và hoàn hảo. Bạn sẽ được đắm chìm trong thế giới game một cách trọn vẹn', '{"Thương hiệu:":"Corsair","Bảo hành:":"24 Tháng","Model:":"Corsair HS35 v2&nbsp;","Màu sắc:":"Đen","Kiểu tai nghe":"Over-ear","Kiểu kết nối:":"Có dây","Microphone:":"Có","Dây:":"Dài 1,8m","Drivers:":"50mm","Tương thích:":"PC, Mac, PlayStation 4/5, Xbox One / Series XS, Nintendo Switch, Mobile devices &nbsp;","Khả năng cách âm:":"Có"}', 0, 1);
