INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1050018650', 'SP108763', '1050018650', 'https://www.maytinhbienhoa.vn/products/tai-nghe-corsair-hs55-carbon-stereo', 'Tai Nghe Corsair HS55 Carbon Stereo', 'tai-nghe-corsair-hs55-carbon-stereo', 'brand_corsair_531', 'cat_headsets', 749000, 749000, 0, 599200, 24, 'in_stock', 'Tai Nghe Corsair HS55 Carbon Stereo', 'Thông số kỹ thuật: Thương hiệu: Corsair Bảo hành: 24 Tháng Model: Corsair HS55 Carbon Màu sắc: Đen Kiểu tai nghe Over-ear Kiểu kết nối: Có dây Microphone: Có Dây: Dài 1,8m Tần số : Tai nghe:&nbsp;20Hz - 20000Hz Micro:&nbsp;100Hz - 10000Hz Trở kháng: Tai nghe: 32k Ohms @ 1 kHz Micro: 2.2k Ohms Độ nhạy: Tai nghe:&nbsp;114dB (+/-3dB) Micro:&nbsp;-41dB (+/-3dB) Drivers: 50mm Tương thích: PC, Mac, PlayStation 4/5, Xbox One / Series XS, Nintendo Switch, Mobile devices Khả năng cách âm: Có Đánh giá chi tiết tai nghe Corsair HS55 Stereo Carbon &nbsp; HS55 Stereo là dòng sản phẩm&nbsp;tai nghe máy tính&nbsp;mới nhất đến từ Corsair với nhiều cải tiến về công nghệ âm thanh mang đến cho người dùng những trải nghiệm tuyệt vời trong những trò chơi mình yêu thích.&nbsp; Thiết kế ấn tượng, sang trọng &nbsp; &nbsp; Corsair được biết đến là một trong những hãng chuyên sản xuất các dòng sản phẩm gaming gear chất lượng được người dùng tiêu dùng đánh giá cao về hiệu năng lẫn thiết kế từ&nbsp;bàn phím,&nbsp;chuột máy tính, tai nghe cho đến ghế gaming.&nbsp; Tai nghe chơi game Corsair HS55 Stereo là một thiết bị ấn tượng mà bất kỳ game thủ bình thường hay chuyên nghiệp nào cũng nên yêu thích. Với thiết kế dạng over-ear (tai nghe chụp tai) mang đến âm thanh tốt, lọc tiếng ồn cực tốt. Phối màu carbon sang trọng phù hợp với mọi góc máy chơi game, làm việc. Đây không chỉ là phụ kiện giúp bạn nâng cao chất lượng giải trí mà còn làm dàn PC của bạn thêm phần nổi bật.&nbsp; Công nghệ âm thanh neodymium 50m', '{"Thương hiệu:":"Corsair","Bảo hành:":"24 Tháng","Model:":"Corsair HS55 Carbon","Màu sắc:":"Đen","Kiểu tai nghe":"Over-ear","Kiểu kết nối:":"Có dây","Microphone:":"Có","Dây:":"Dài 1,8m","Tần số :":"Tai nghe:&nbsp;20Hz - 20000Hz Micro:&nbsp;100Hz - 10000Hz","Trở kháng:":"Tai nghe: 32k Ohms @ 1 kHz Micro: 2.2k Ohms","Độ nhạy:":"Tai nghe:&nbsp;114dB (+/-3dB) Micro:&nbsp;-41dB (+/-3dB)","Drivers:":"50mm"}', 0, 1);
