INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1022409758', 'SP006851', '1022409758', 'https://www.maytinhbienhoa.vn/products/kraken-x-black', 'Tai Nghe Razer Kraken X For Console Black', 'kraken-x-black', 'brand_razer_388', 'cat_headsets', 790000, 990000, 20, 632000, 24, 'out_of_stock', 'Tai Nghe Razer Kraken X For Console Black', 'Thông số kỹ thuật: Hãng sản xuất Razer Model Kraken X Màu sắc Xanh Driver 40 mm Kết nối Analog 3.5 mm Chiều dài dây 1.3 m Tần số Tai nghe: 12 Hz – 28 kHz Micro: 100 Hz - 10 kHz Trở kháng 32 Ohm (1 kHz) Độ nhạy Tai nghe: 109 dB (1 kHz) Micro:&nbsp;-45 ± 3 dB Micro Có (có thể uốn cong) Chức năng&nbsp; Chức năng tắt tiếng trên tai nghe: Nhấp để tắt tiếng Chụp tai: Tăng / Giảm âm lượng Trọng lượng 250g Đánh giá chi tiết&nbsp;tai nghe Razer Kraken X for Console Tai nghe chụp tai&nbsp;Razer Kraken X for Console hứa hẹn mang đến những trải nghiệm nghe thoải mái cho người dùng. Thiết kế kiểu dáng đẹp mắt, âm thanh chất lượng đáp ứng mọi nhu cầu chơi game hằng ngày.&nbsp; Thiết kế chắc chắn và mạnh mẽ Tai nghe&nbsp;Razer&nbsp;Kraken X for Console thể hiện vẻ đẹp của mình qua kiểu dáng mạnh mẽ được thiết kế bên ngoài. Khung tai nghe chất lượng với kết cấu bền bỉ trong tông màu đen huyền bí. Điểm xuyến phần logo và một vài vị trí màu xanh ấn tượng.&nbsp; &nbsp; Âm thanh to rõ Razer Kraken X mang đến chất âm mượt mà giúp người sử dụng đắm chìm vào không gian giải trí. Hai phần chụp tai vừa vặn phù hợp với nhiều kích cỡ tai khác nhau và hoàn toàn ôm sát để nghe rõ hơn. Các tạp âm bên ngoài cũng từ đó mà giảm đi rất nhiều.&nbsp; &nbsp; Sự êm ái và thoái mái khi đeo Tai nghe chơi game&nbsp;Razer Kraken X sẽ giúp các game thủ thấy thoải mái hơn khi đeo trong nhiều giờ chiến game đầy căng thẳng. Phần đệm tai êm ái sẽ không làm tai bị đau cũng như đầu bị mỏi. Trọng lượng nhẹ chiếm khoảng 250g ', '{"Hãng sản xuất":"Razer","Model":"Kraken X","Màu sắc":"Xanh","Driver":"40 mm","Kết nối":"Analog 3.5 mm","Chiều dài dây":"1.3 m","Tần số":"Tai nghe: 12 Hz – 28 kHz","Trở kháng":"32 Ohm (1 kHz)","Độ nhạy":"Tai nghe: 109 dB (1 kHz) Micro:&nbsp;-45 ± 3 dB","Micro":"Có (có thể uốn cong)","Chức năng&nbsp;":"Chức năng tắt tiếng trên tai nghe: Nhấp để tắt tiếng Chụp tai: Tăng / Giảm âm lượng","Trọng lượng":"250g"}', 0, 1);
