INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1076249589', 'SP1084079', '1076249589', 'https://www.maytinhbienhoa.vn/products/tai-nghe-aula-g7-pro-gaming-3-mode', 'TAI NGHE AULA G7 PRO GAMING 3 MODE', 'tai-nghe-aula-g7-pro-gaming-3-mode', 'brand_aula_291', 'cat_headsets', 890000, 890000, 0, 712000, 24, 'in_stock', 'TAI NGHE AULA G7 PRO GAMING 3 MODE', 'THÔNG SỐ KỸ THUẬT &nbsp; - Kết nối: Jack 3.5 mm / USB-C / 2.4 GHz / Bluetooth - Âm thanh vòm chuẩn Esports tối ưu cho game FPS - Tùy chỉnh EQ bằng phần mềm cân chỉnh âm thanh chuyên nghiệp - Đèn nền RGB ánh sáng dịu - Độ trễ không dây siêu thấp 10 ms với công nghệ HyperLink - Micro đa hướng 360° tích hợp AI khử tiếng ồn - Màu sắc: Đen - Trọng lượng: Khoảng 280g - Công suất đầu vào: DC5V-500mA - Thời gian sạc: 3–4 tiếng - Dung lượng pin: 1000mAh - Thời gian hoạt động: Khoảng 65 tiếng (2.4G), 80 tiếng (Bluetooth) - Phạm vi hoạt động: 10m - Đường kính loa: 40mm - Trở kháng loa: 16Ω - Dải tần số đáp ứng: 20Hz ~ 20kHz - Độ nhạy tai nghe: 116 ± 5dB - Độ nhạy microphone: -38dB &nbsp; &nbsp; MÔ TẢ SẢN PHẨM – TAI NGHE AULA G7 PRO GAMING 3 MODE AULA G7 Pro là mẫu tai nghe gaming không dây 3 chế độ kết nối, được thiết kế dành cho game thủ cần độ trễ thấp, âm thanh định hướng tốt và khả năng sử dụng linh hoạt trên nhiều thiết bị. Tai nghe hỗ trợ 2.4GHz Wireless, Bluetooth và kết nối có dây , đáp ứng từ chơi game PC/Console đến nghe nhạc và đàm thoại hằng ngày. &nbsp; &nbsp; &nbsp; 3 CHẾ ĐỘ KẾT NỐI 2.4GHz Wireless: kết nối không dây độ trễ cực thấp, khoảng 10ms theo công bố của AULA, phù hợp chơi game FPS và game cạnh tranh. Bluetooth: kết nối nhanh với điện thoại, laptop và các thiết bị hỗ trợ Bluetooth. Wired: sử dụng kết nối có dây khi cần. Tương thích với PC, Laptop, PS4, PS5 và thiết bị di động . &nbsp; &nbsp; ÂM THANH GAMING 7.1 G7 Pro được trang bị driver Dynamic 40mm , kết hợp hệ ', '{"2.4GHz Wireless":"kết nối không dây độ trễ cực thấp, khoảng 10ms theo công bố của AULA, phù hợp chơi game FPS và game cạnh tranh.","Bluetooth":"khoảng 80 giờ","Wired":"sử dụng kết nối có dây khi cần.","2.4GHz":"khoảng 65 giờ","Thời gian sạc":"khoảng 3–4 giờ","Khoảng cách hoạt động":"khoảng 10m"}', 0, 1);
