INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074990592', 'SP1083724', '1074990592', 'https://www.maytinhbienhoa.vn/products/tai-nghe-hyperx-cloud-earbuds-iii-black', 'Tai Nghe HyperX Cloud Earbuds III Black', 'tai-nghe-hyperx-cloud-earbuds-iii-black', 'brand_hp_152', 'cat_headsets', 890000, 890000, 0, 712000, 24, 'in_stock', 'Tai Nghe HyperX Cloud Earbuds III Black', 'THÔNG SỐ KỸ THUẬT Thương hiệu HyperX Bảo hành 24 tháng Màu sắc Đen Kết nối 3.5mm Kiểu kết nối Có dây Driver 14mm Tương thích PC, Nintendo, Steamdeck, Một số thiết bị di động Tai nghe HP HyperX Cloud Earbuds III – Gaming di động với âm thanh sống động và thoải mái cả ngày HP HyperX Cloud Earbuds III là mẫu tai nghe gaming in-ear được thiết kế dành cho game thủ yêu thích sự nhỏ gọn, tiện lợi nhưng vẫn đảm bảo chất lượng âm thanh và khả năng giao tiếp rõ ràng. Với thiết kế siêu di động, chất âm cân bằng cùng độ thoải mái đặc trưng từ HyperX, sản phẩm mang đến trải nghiệm chơi game linh hoạt trên nhiều thiết bị khác nhau. Thiết kế công thái học cho cảm giác đeo thoải mái suốt ngày dài HyperX Cloud Earbuds III được tối ưu cho những phiên chơi game kéo dài với thiết kế Intra-Concha độc quyền giúp giảm áp lực lên tai. Bộ đệm tai mềm mại đi kèm nhiều kích cỡ từ XS đến L giúp người dùng dễ dàng lựa chọn kích thước phù hợp, mang lại độ ôm tai chắc chắn và thoải mái hơn khi sử dụng lâu. Thiết kế này còn cho phép âm thanh môi trường lọt vào vừa đủ để người dùng vẫn duy trì khả năng nhận biết xung quanh trong quá trình chơi game hoặc sử dụng hàng ngày. Âm thanh cân bằng, giàu chi tiết cho gaming và giải trí Trang bị driver 14 mm được HyperX tinh chỉnh riêng, tai nghe mang lại chất âm cân bằng với dải bass mạnh mẽ, âm trung rõ ràng và âm cao sắc nét. Nhờ đó, người dùng có thể dễ dàng nhận biết tiếng bước chân, hiệu ứng kỹ năng hay tín hiệu trong game một cách chính xác hơn. Không chỉ phù', '{"HyperX":"24 tháng","Đen":"3.5mm","Có dây":"14mm"}', 0, 1);
