INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1077333432', 'SP1084263', '1077333432', 'https://www.maytinhbienhoa.vn/products/tai-nghe-thonet-vander-klassik-bluetooth', 'Tai Nghe Thonet & Vander KLASSIK Bluetooth', 'tai-nghe-thonet-vander-klassik-bluetooth', 'brand_thonet-vander_1016', 'cat_headsets', 890000, 890000, 0, 712000, 24, 'in_stock', 'Tai Nghe Thonet & Vander KLASSIK Bluetooth', '&nbsp; THÔNG SỐ KỸ THUẬT &nbsp; Thương hiệu XIBERIA Bảo hành 12 tháng Kết nối Bluetooth, AUX 3.5mm Kiểu kết nối Có dây, Không dây Kích thước driver 40mm Dải tần đáp ứng 20Hz – 20kHz Trở kháng 16Ω + 16Ω Độ nhạy tai nghe 92 ± 3dB Micro Micro tích hợp Độ nhạy micro -38 ± 3dB Dung lượng pin 800mAh Thời lượng pin Lên đến 80 giờ (âm lượng trung bình) Cổng sạc USB-C Màu sắc Đen &nbsp; &nbsp; &nbsp; Tai nghe Bluetooth Thonet &amp; Vander KLASSIK Tai nghe Bluetooth Thonet &amp; Vander KLASSIK là mẫu tai nghe không dây hướng đến nhu cầu nghe nhạc, làm việc, giải trí và chơi game hằng ngày. Sản phẩm nổi bật với Bluetooth 5.4, khả năng kết nối đồng thời hai thiết bị, thời lượng pin lên đến 80 giờ và thiết kế gập gọn tiện lợi. Bên cạnh đó, driver 40mm, micro tích hợp và chế độ Low Latency giúp KLASSIK mang đến trải nghiệm sử dụng linh hoạt, đáp ứng tốt nhiều nhu cầu khác nhau. Driver 40mm, tái tạo âm thanh trong dải tần rộng Thonet &amp; Vander KLASSIK được trang bị driver kích thước 40mm, hỗ trợ tái tạo âm thanh trong dải tần từ 20Hz đến 20kHz. Đây là dải tần phổ biến trên các mẫu tai nghe tiêu dùng, đáp ứng nhu cầu nghe nhạc, xem phim, thưởng thức nội dung trực tuyến và chơi game. Với trở kháng 16Ω + 16Ω và độ nhạy 92 ± 3dB, tai nghe được thiết kế để hoạt động với nhiều thiết bị phát âm thanh tương thích. Nhờ đó, người dùng có thể sử dụng KLASSIK trong nhiều tình huống mà không cần trang bị thêm thiết bị khuếch đại âm thanh chuyên dụng. Bluetooth 5.4, kết nối đồng thời hai thiết bị Ta', '{"XIBERIA":"12 tháng","Bluetooth, AUX 3.5mm":"Có dây, Không dây","40mm":"20Hz – 20kHz","16Ω + 16Ω":"92 ± 3dB","Micro tích hợp":"-38 ± 3dB","800mAh":"Lên đến 80 giờ (âm lượng trung bình)","USB-C":"Đen"}', 0, 1);
