INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1053257365', 'SP109571', '1053257365', 'https://www.maytinhbienhoa.vn/products/tai-nghe-logitech-g333-gaming-earphone-purple', 'Tai nghe Logitech G333 Gaming Earphone Purple', 'tai-nghe-logitech-g333-gaming-earphone-purple', 'brand_kh-c_503', 'cat_headsets', 939000, 939000, 0, 751200, 24, 'in_stock', 'Tai nghe Logitech G333 Gaming Earphone Purple', '&nbsp;THÔNG SỐ KĨ THUẬT: Thương hiệu Logitech Model G333 Màu sắc Purple Tai nghe 2 màng loa động kép: 5,8 mm + 9,2 mm Độ nhạy tần số: 20 Hz ~ 20 KHz Trở kháng: 24 Ôm ±20% Độ nhạy: 101,6±3 dB @ 1 kHz SPL Micro Micrô ECM 4 mm, độ nhạy: -42 dB Kết nối cổng aux 3,5 mn hoặc cổng USB-C Trọng lượng Trọng lượng tai nghe và cáp: 19 gram Trọng lượng bộ tiếp hợp USB-C: 6 gram &nbsp; TÍNH NĂNG NỔI BẬT: &nbsp; Màng loa động kép nâng tầm trải nghiệm Logitech G333 được thiết kế đặc biệt dành cho trải nghiệm chơi game tối ưu. Các màng loa âm thanh kép chuyên dụng, một cho âm cao/âm trung và một cho âm trầm, cung cấp âm thanh phong phú chi tiết để tái tạo chính xác thế giới game. &nbsp; &nbsp; Mic và nút điều khiển tích hợp Tai Nghe Logitech G333 có Micro&nbsp;trên dây chất lượng cao đem đến thông tin liên lạc và trò chuyện rõ ràng, trong khi các nút điều khiển tích hợp cho phép bạn phát, tạm dừng và điều khiển âm lượng một cách liền mạch. Micrô cũng cho phép bạn giao tiếp trong trò chơi, cũng như nhận cuộc gọi khi bạn chơi game trên điện thoại của mình. &nbsp; &nbsp; Tùy chỉnh linh hoạt và sự bền bỉ tuyệt vời Chọn giữa các kích cỡ đầu nút silicon mềm dẻo đi kèm để vừa vặn và nằm nhẹ nhàng bên trong tai của bạn. Vỏ nhôm chắc chắn đáng tin cậy và bền với lớp hoàn thiện hấp dẫn. &nbsp; &nbsp; Tương thích nhiều nền tảng Tai nghe nhét tai Logitech G333 có khả năng tương thích với rất nhiều tảng như: PC, mobile, Xbox, PlayStation, Nintendo, etc... thông qua 2 đầu cắm aux 3,5 mm hoặc cổng USB-C đ', '{"Thương hiệu":"Logitech","Model":"G333","Màu sắc":"Purple","Tai nghe":"2 màng loa động kép: 5,8 mm + 9,2 mm Độ nhạy tần số: 20 Hz ~ 20 KHz Trở kháng: 24 Ôm ±20% Độ nhạy: 101,6±3 dB @ 1 kHz SPL","Micro":"Micrô ECM 4 mm, độ nhạy: -42 dB","Kết nối":"cổng aux 3,5 mn hoặc cổng USB-C","Trọng lượng":"Trọng lượng tai nghe và cáp: 19 gram Trọng lượng bộ tiếp hợp USB-C: 6 gram"}', 0, 1);
