INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1077333465', 'SP1084264', '1077333465', 'https://www.maytinhbienhoa.vn/products/tai-nghe-bluetooth-thonet-vander-dauer-gen3-black', 'Tai Nghe Bluetooth Thonet & Vander DAUER Gen3 Black', 'tai-nghe-bluetooth-thonet-vander-dauer-gen3-black', 'brand_thonet-vander_1016', 'cat_headsets', 1090000, 1090000, 0, 872000, 24, 'in_stock', 'Tai Nghe Bluetooth Thonet & Vander DAUER Gen3 Black', 'THÔNG SỐ KỸ THUẬT Thương hiệu Thonet &amp; Vander Bảo hành 12 tháng Chất liệu ABS matte, headband gia cố kim loại, đệm silicone, đệm tai da vegan Kết nối Bluetooth, AUX 3.5mm Kiểu kết nối Không dây Driver 2 x 40 mm Dải tần đáp ứng 20Hz – 20kHz Độ nhạy 102 ± 3 dB/mW Micro Tích hợp Thời lượng pin Lên đến 90 giờ (50% âm lượng, không ANC) Sạc USB-C Màu sắc Đen, Xanh dương, Be &nbsp; &nbsp; &nbsp; Tai nghe Bluetooth Thonet &amp; Vander DAUER Gen3 Tai nghe Bluetooth Thonet &amp; Vander DAUER Gen3 là mẫu headphone không dây hướng đến trải nghiệm nghe nhạc tiện lợi với Bluetooth 6.0, driver 40 mm, chống ồn chủ động ANC và thời lượng pin lên đến 90 giờ . Thiết kế gập gọn, trọng lượng chỉ 196 g cùng khả năng kết nối đồng thời 2 thiết bị giúp DAUER Gen3 phù hợp cho cả nhu cầu giải trí, làm việc và di chuyển hằng ngày. Âm thanh cân bằng với driver 40 mm Thonet &amp; Vander DAUER Gen3 được trang bị 2 driver 40 mm được tinh chỉnh riêng nhằm mang lại chất âm cân bằng trong dải tần từ 20Hz – 20kHz . Công suất đầu ra 2W RMS, trở kháng 32 Ohms và độ nhạy 102 ± 3 dB/mW giúp tai nghe đáp ứng tốt nhu cầu nghe nhạc, xem phim hoặc thưởng thức nội dung trực tuyến. ANC giảm tiếng ồn đến -22 dB DAUER Gen3 hỗ trợ Active Noise Cancelling (ANC) lên đến -22 dB , giúp hạn chế tiếng ồn từ môi trường xung quanh. Tính năng này đặc biệt hữu ích khi sử dụng tại văn phòng, quán cà phê hoặc khi di chuyển, giúp người dùng tập trung hơn vào nội dung đang nghe. Bluetooth 6.0 và kết nối Multipoint Tai nghe sử dụng ', '{"Thonet &amp; Vander":"12 tháng","Không dây":"2 x 40 mm","20Hz – 20kHz":"102 ± 3 dB/mW","Tích hợp":"Lên đến 90 giờ (50% âm lượng, không ANC)","USB-C":"Đen, Xanh dương, Be"}', 0, 1);
