INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1071391981', 'SP1082909', '1071391981', 'https://www.maytinhbienhoa.vn/products/tai-nghe-logitech-g321-lightspeed-gaming-wireless-white', 'Tai Nghe Logitech G321 LightSpeed Gaming Wireless White', 'tai-nghe-logitech-g321-lightspeed-gaming-wireless-white', 'brand_logitech_591', 'cat_headsets', 1390000, 1390000, 0, 1112000, 24, 'in_stock', 'Tai Nghe Logitech G321 LightSpeed Gaming Wireless White', 'Thông số kỹ thuật Thương hiệu Logitech Tên sản phẩm G321 LIGHTSPEED Wireless Gaming Headset Mã sản phẩm 981-001562 Driver 40mm Microphone 16kHz flip-to-mute boom mic Kết nối LIGHTSPEED 2.4GHz, Bluetooth 5.2 Thời lượng pin Hơn 20 giờ Trọng lượng 210g Kích thước Rộng 202.8mm, Cao 185.6mm, Sâu 44.7mm Tương thích PC, PS4, PS5, Nintendo Switch, Mobile Bảo hành 24 tháng Thông tin sản phẩm TAI NGHE KHÔNG DÂY LOGITECH G321 LIGHTSPEED Tai nghe không dây Logitech G321 LIGHTSPEED là sản phẩm gaming giá phải chăng, mang lại trải nghiệm âm thanh mạnh mẽ và thoải mái cho các phiên chơi dài. Với công nghệ LIGHTSPEED 2.4GHz độ trễ thấp, kết nối Bluetooth đa năng, và thời lượng pin hơn 20 giờ, tai nghe giúp bạn đắm chìm vào game mà không lo gián đoạn. Thiết kế nhẹ chỉ 210g, mic flip-to-mute 16kHz rõ ràng, phù hợp cho PC, PS4, PS5, Nintendo Switch, và di động. ÂM THANH MẠNH MẼ VÀ CHI TIẾT Driver 40mm mang lại âm thanh sống động với bass sâu, mid rõ ràng, phù hợp cho game hành động, âm thanh không gian. Hỗ trợ spatial audio, giúp bạn nghe rõ tiếng bước chân, tiếng súng, tăng lợi thế trong game. KẾT NỐI LIGHTSPEED VÀ BLUETOOTH LIGHTSPEED 2.4GHz cho độ trễ thấp dưới 1ms, kết hợp Bluetooth 5.2 cho nhạc, chat, gaming di động. Chuyển đổi dễ dàng giữa 2 chế độ, không hỗ trợ đồng thời, đảm bảo kết nối ổn định trên PC, console, mobile. THOẢI MÁI VÀ NHẸ NHẰNG Trọng lượng chỉ 210g, headband dày memory foam, earcup thoáng khí với đệm 21mm, phù hợp đeo lâu không mỏi. Thiết kế chắc chắn nhưng linh hoạt, dễ ', '{"Thương hiệu":"Logitech","Tên sản phẩm":"G321 LIGHTSPEED Wireless Gaming Headset","Mã sản phẩm":"981-001562","Driver":"40mm","Microphone":"16kHz flip-to-mute boom mic","Kết nối":"LIGHTSPEED 2.4GHz, Bluetooth 5.2","Thời lượng pin":"Hơn 20 giờ","Trọng lượng":"210g","Kích thước":"Rộng 202.8mm, Cao 185.6mm, Sâu 44.7mm","Tương thích":"PC, PS4, PS5, Nintendo Switch, Mobile","Bảo hành":"24 tháng"}', 0, 1);
