INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1068868751', 'SP1082324', '1068868751', 'https://www.maytinhbienhoa.vn/products/ban-phim-co-aula-f99-pro-den-xam-xanh-la-grey-wood-v3-switch', 'Bàn Phím Cơ AULA F99 PRO (Đen + Xám + Xanh lá/ Grey Wood V3 switch)', 'ban-phim-co-aula-f99-pro-den-xam-xanh-la-grey-wood-v3-switch', 'brand_aula_291', 'cat_gaming-gear', 1690000, 1690000, 0, 1352000, 24, 'in_stock', 'Bàn Phím Cơ AULA F99 PRO (Đen + Xám + Xanh lá/ Grey Wood V3 switch)', 'THÔNG SỐ KỸ THUẬT - Bàn phím cơ gaming AULA F99 Pro - Độ bền: 60 triệu lần bấm - Kết nối: 3 mode có dây Type-C &amp; không dây 2.4G &amp; BT - Màu sắc: Đen + Trắng + Xanh lá - Keycap PBT Double-Shot - Đèn nền: LED RGB 16,8 triệu màu - Loại switch: Greywood V3 switch - Hiệu ứng âm thanh khi gõ phím: Linear - Hot-Swap 5 pin - Gasket mount - Núm xoay đa chức năng - Mạch xuôi - Số lượng phím: 99 phím - Hành trình phím: 4.0mm - Điện áp/dòng sạc: DC 5V-1250mA - Điện áp định mức: DC 3.7V (đầy đủ 4.2V) - Dòng điện định mức: 250mA @3.7V (hiệu ứng ánh sáng mặc định); 20mA (tắt đèn nền) - Dung lượng pin: Pin lithium 8000mAh có thể sạc lại (2x4000mAh) - Thời gian sử dụng sau khi sạc đầy pin: Khoảng 32H (hiệu ứng ánh sáng mặc định) Khoảng 400H (tắt tất cả đèn) - Tốc độ phản hồi: Chế độ có dây 1000Hz, chế độ 2.4G 1000Hz, chế độ Bluetooth 125Hz. - Giao diện sạc: Type-C - Kích thước bàn phím (L x W x H): 406.76 × 139.31 × 43.28 ± 0.1 mm - Trọng lượng: Khoảng 1205g (không có cáp/bộ thu)/ 1254g (với cáp/bộ thu) - Phím FN đa chức năng - Hệ điều hành tương thích: WINXP/WIN7/WIN8/WIN10/Android/IOS/MAC - Phụ kiện kèm theo: Sách hướng dẫn sử dụng + Dây USB type-C + Dụng cụ thay switch + Switch tặng kèm (1-4 chiếc) &nbsp; &nbsp;', '{"Model":"Bàn Phím Cơ AULA F99 PRO (Đen + Xám + Xanh lá/ Grey Wood V3 switch)"}', 0, 1);
