INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1053914730', 'SP109734', '1053914730', 'https://www.maytinhbienhoa.vn/products/ghe-tms09-ergonomic-cong-thai-hoc-black', 'Ghế TMS09(418) Ergonomic Công Thái Học Black', 'ghe-tms09-ergonomic-cong-thai-hoc-black', 'brand_ergonomic_675', 'cat_gaming-chairs', 1390000, 1390000, 0, 1112000, 24, 'in_stock', 'Ghế TMS09(418) Ergonomic Công Thái Học Black', 'THÔNG SỐ CƠ BẢN: Tay nhựa bọc đệm có thể điều chỉnh Đệm mút bọc vải lưới thoáng mát Piston thủy lực chịu trọng lượng tới 100kg Chân nhựa đúc PP cao cấp, chắc chắn Bánh xe nhựa bọc cao su di chuyển êm ái, nhạy bén. &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Đặc điểm nổi bật của sản phẩm ghế Văn Phòng Mẫu Mới 2023 GHE_CÔNG THÁI HỌC TMS09&nbsp; + Thiết kế xoay độc đáo mang lại sự tiện lợi cho công việc:&nbsp; Ghế văn phòng&nbsp; lịch lãm là dòng ghế đặc biệt được tạo ra từ sự nghiên cứu chuyên sâu về thói quen cũng như sức khỏe của dân văn phòng, giúp mang lại sự tiện lợi tối đa cho công việc với chân xoay có bánh xe trượt 360 độ giúp bạn có thể xoay chuyển dễ dàng mọi góc độ để trao đổi công việc với mọi người. + Đệm lưng vải dệt lưới cao cấp tạo cảm giác thoải mái khi ngồi:&nbsp; Đệm lưng ghế văn phòng&nbsp; tms09 thiết kế&nbsp;&nbsp;với đường rãnh giữa các Oval cấu thành từ những sợi vải polyester đan xen giúp không khí được lưu thông tránh được cảm giác bức bí khi ngồi làm việc lâu. + Kết cấu lưng uống cong làm giảm đau lưng hiệu quả:&nbsp; Sản phẩm có kết cấu khung uốn cong dạng lưng rời đệm với sự kết hợp sử dụng nhiều đường cong uốn lượn ở 2 bên giúp ôm sát vào cột sống khi ngồi, tạo nên cấu trúc nâng đỡ tuyệt vời cho toàn bộ phần cột sống và 4 cơ bắp lưng, từ đó giúp hạn chế những cơn đau xuất hiện ở vùng thắt lưng, đau mỏi, thoái hóa cột sống do ngồi lâu, vận động ít. + Tựa đầu điều chỉnh lên xuống tùy ý&nbsp; + Tay ghế gập bọc lớp đệm mút êm ái', '{"Model":"Ghế TMS09(418) Ergonomic Công Thái Học Black"}', 0, 1);
