INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1076205564', 'SP1084070', '1076205564', 'https://www.maytinhbienhoa.vn/products/ghe-e-dra-egc236-new-cityzen-gaming-black-1', 'GHẾ E-DRA EGC236 NEW CITYZEN GAMING BLACK', 'ghe-e-dra-egc236-new-cityzen-gaming-black-1', 'brand_e-dra_329', 'cat_gaming-chairs', 1790000, 1790000, 0, 1432000, 24, 'in_stock', 'GHẾ E-DRA EGC236 NEW CITYZEN GAMING BLACK', '&nbsp; THÔNG SỐ KỸ THUẬT &nbsp; &nbsp; Mục Mô Tả Chi Tiết Chất liệu Da PVC, Fabric cao cấp Màu sắc Đen đỏ Chiều cao ghế Lên đến 1250mm Tay vịn Cố định Góc điều chỉnh tựa lưng Bệ đỡ: Đa năng, ngả 135 độ Tính năng chính Tải trọng lên đến 120kg (theo góc đứng), Bánh xe được thiết kế ko gây tiếng ồn, Quay 360 độ Kích thước 1250 x 530 x 670mm Trọng lượng 13.7kg (Không thùng) Bảo hành 12 tháng &nbsp; MÔ TẢ SẢN PHẨM NÂNG CAO Ghế gaming E-Dra New Citizen EGC236 (Black)&nbsp;là lựa chọn lý tưởng dành cho game thủ, streamer và dân văn phòng cần một chiếc ghế vừa thoải mái, vừa có thiết kế ngầu, đậm chất eSports. Với chất liệu cao cấp, thiết kế chắc chắn và khả năng ngả lưng linh hoạt, sản phẩm mang đến tư thế ngồi tối ưu cho những giờ làm việc hoặc chơi game kéo dài. &nbsp; Thiết kế mạnh mẽ, màu đen sang trọng Ghế EGC236 sở hữu tông màu đen chủ đạo đầy cá tính, phù hợp với nhiều không gian: từ góc gaming tại nhà đến môi trường làm việc chuyên nghiệp. Phần khung được thiết kế vững chắc, bệ đỡ đa năng tạo cảm giác an toàn khi ngồi, dù bạn đang làm việc, thư giãn hay “combat” trong những trận game căng thẳng. &nbsp; Chất liệu da PVC và vải Fabric cao cấp – Bền bỉ và thoáng khí Ghế được hoàn thiện từ da PVC và vải Fabric cao cấp, mang lại sự kết hợp hoàn hảo giữa độ bền và khả năng thoát khí. Bề mặt da dễ lau chùi, chống thấm nước nhẹ, trong khi lớp vải ở phần tiếp xúc giúp người dùng không bị nóng lưng khi ngồi lâu – một điểm cộng lớn cho ghế gaming cao cấp giá tốt như EGC236. &nbsp; Tựa ', '{"Chất liệu":"Da PVC, Fabric cao cấp","Màu sắc":"Đen đỏ","Chiều cao ghế":"Lên đến 1250mm","Tay vịn":"Cố định","Góc điều chỉnh tựa lưng":"Bệ đỡ: Đa năng, ngả 135 độ","Tính năng chính":"Tải trọng lên đến 120kg (theo góc đứng), Bánh xe được thiết kế ko gây tiếng ồn, Quay 360 độ","Kích thước":"1250 x 530 x 670mm","Trọng lượng":"13.7kg (Không thùng)","Bảo hành":"12 tháng"}', 0, 1);
