INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1062873592', 'SP1081397', '1062873592', 'https://www.maytinhbienhoa.vn/products/ghe-cth919-ergonomic-cong-thai-hoc-black', 'Ghế CTH919 Ergonomic Công Thái Học Black', 'ghe-cth919-ergonomic-cong-thai-hoc-black', 'brand_kh-c_503', 'cat_gaming-chairs', 2490000, 2490000, 0, 1992000, 24, 'in_stock', 'Ghế CTH919 Ergonomic Công Thái Học Black', 'Thông số kỹ thuật chi tiết: &nbsp; Model: Ghế công thái học CTH-919 Loại ghế: Ghế công thái học Chất liệu: Nhựa tổng hợp/ thép không gỉ Khả năng chịu tải: 120kg Tính năng: Chức năng căng chỉnh độ cao, Phân tán lực ngồi đều Kích thước: 60 x 60 x 80cm Trọng Lượng: 15kg &nbsp; Điểm nổi bật: &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ghế công thái học CTH-919 màu đen: thiết kế ergonomics, sang trọng và tiện ích. Ghế công thái học CTH-919 | Màu đen đặc biệt được thiết kế với khả năng căng chỉnh độ cao, giúp người sử dụng có thể tinh chỉnh để ngồi thoải mái. Chất liệu nhựa tổng hợp/ thép không gỉ mang lại sự bền bỉ và dễ dàng vệ sinh. &nbsp; Ứng dụng thực tế: &nbsp; Phòng làm việc: Giúp cải thiện tư duy và tạo cảm giác thoải mái khi làm việc. Phòng học: Đảm bảo sự thoải mái và chân thực trong quá trình học tập. Phòng chơi game: Hỗ trợ người chơi cảm giác chân thực và thoải mái khi ngồi lâu. &nbsp; So sánh với các sản phẩm cùng phân khúc: &nbsp; Ghế Công Thái Học CTH-919 | Màu đen được đánh giá cao về tính năng sẵn có và chất lượng vật liệu so với các sản phẩm tương tự trong phân khúc. &nbsp; Đối tượng phù hợp: &nbsp; Nhóm nhân viên văn phòng: Để nâng cao hiệu suất làm việc và sức khỏe. Sinh viên và học sinh: Dễ dàng tinh chỉnh để phù hợp với vị trí ngồi và giữ thẳng lưng.', '{"Model":"Ghế công thái học CTH-919","Loại ghế":"Ghế công thái học","Chất liệu":"Nhựa tổng hợp/ thép không gỉ","Khả năng chịu tải":"120kg","Tính năng":"Chức năng căng chỉnh độ cao, Phân tán lực ngồi đều","Kích thước":"60 x 60 x 80cm","Trọng Lượng":"15kg","Phòng làm việc":"Giúp cải thiện tư duy và tạo cảm giác thoải mái khi làm việc."}', 0, 1);
