INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1016697399', 'SP004347', '1016697399', 'https://www.maytinhbienhoa.vn/products/modem-draytek-vigor-2912-series-new-bh-24th', 'MODEM DRAYTEK VIGOR 2912 Series', 'modem-draytek-vigor-2912-series-new-bh-24th', 'brand_dreytek_536', 'cat_accessories', 1290000, 2390000, 46, 1032000, 24, 'in_stock', 'MODEM DRAYTEK VIGOR 2912 Series', 'THÔNG SỐ KỸ THUẬT WAN 1: 10/100Mbps, RJ45 WAN 2: 10/100Mbps, RJ45 (chuyển đổi từ LAN1) WAN 3: USB 2.0 gắn 3.5G/4G modem VPN Server 16 kênh (PPTP, L2TP, IPSec); VPN Trunking (Backup); VPN qua 3G/4G (Dial-out) Kiểm soát và quản lý băng thông giúp tối ưu hóa đường truyền internet Tính năng Web Portal: Hiện trang quảng cáo khi khách hàng kết nối internet Tính năng Firewall mạnh mẽ, linh hoạt, quản trị phân quyền truy cập Internet (IP/MAC Address, Port Service, URL/Web content filter, schedule,...) Hỗ trợ Phần mềm quản lý tập trung Vigor ACS SI, quản lý tất cả các Router Vigor thông qua Internet &nbsp; Năng lực xử lý được nâng cấp Khả năng cân bằng tải được nâng cấp từ 30Mbps lên đến 100Mbps, số session tối đa đồng thời được nâng từ 10.000 lên tối đa 30.000 sessions giúp Vigor2912 có khả năng đáp ứng được hầu hết các gói cước tốc độ cao hiện nay và chịu tải cho hệ thống máy tính đến 50 người dùng. &nbsp; &nbsp; &nbsp; Khả năng&nbsp;cân bằng tải linh hoạt và mạnh mẽ hơn Nếu như trước đây dòng sản phẩm Vigor2910 Series chỉ có thể dùng USB 3G&nbsp;như một kết nối dự phòng cho&nbsp;WAN1&nbsp;thì nay&nbsp;Vigor2912 giờ&nbsp;đây có thể dùng cổng&nbsp;USB 2.0 của mình như 1 kết nối&nbsp;WAN thứ 3 để dự phòng hoặc cân bằng tải cho cả 2 cổng WAN chính, nhờ&nbsp;đó bạn có thể vừa chạy cân bằng tải&nbsp;WAN1 + WAN2, vừa dùng 3G&nbsp;để backup,&nbsp;điều mà trước&nbsp;đây&nbsp;Vigor2910 Series hoàn toàn "bó tay".&nbsp;Ngoài ra thì Vigor2912 còn hỗ trợ cả các USB 4G tốc độ cao. &nbsp; &nbsp; &', '{"WAN 1":"10/100Mbps, RJ45","WAN 2":"10/100Mbps, RJ45 (chuyển đổi từ LAN1)","WAN 3":"USB 2.0 gắn 3.5G/4G modem","Tính năng Web Portal":"Hiện trang quảng cáo khi khách hàng kết nối internet"}', 0, 1);
