INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1022517558', 'SP006936', '1022517558', 'https://www.maytinhbienhoa.vn/products/loa-logitech-z313', 'LOA LOGITECH Z313 50W 2.1', 'loa-logitech-z313', 'brand_logitech_591', 'cat_accessories', 949000, 849000, 0, 759200, 24, 'in_stock', 'LOA LOGITECH Z313 50W 2.1', 'Loa Logitech Z313 2.1 Loa Logitech Z313&nbsp; hệ thống âm thanh stereo 2.1, bao gồm 1 loa Bass và 2 loa treble có công suất 50W. Loa &nbsp; cho âm thanh mạnh mẽ hơn với loa bass công suất, kết hợp với 2 loa treble cho âm thanh hài hòa và trong trẻo hơn.&nbsp;Loa có thể điều chỉnh âm thanh và chỉnh độ Bass thông qua bộ phận tùy chỉnh âm thanh.&nbsp; Logitech Z313&nbsp; sẽ mang đến cho bạn một bữa tiệc âm thanh hoàn hảo. Tính năng sản phẩm: - Hệ thống loa 2.1, công suất lên tới 50W, phù hợp để nghe nhiều dòng nhạc khác nhau. - Nghe Âm thanh mạnh mẽ&nbsp;với loa bass, có thiết kế dưới đáy. - 2 loa treble làm tăng sự hài hòa và trong trẻo của bản nhạc. - Tùy chỉnh âm thanh và độ Bass dễ dàng thông qua tùy chỉnh âm thanh. - Kết nối thiết bị qua cổng 3.5mm, phù hợp với nhiều thiết bị di động hiện nay. - Ngỏ cắm Headphone cho bạn thưởng thức âm thanh ngay trên tai nghe. - Thiết kế cá tính, trang nhã với không gian nhà bạn. Thông số kỹ thuật: + Hệ thống loa: 2.1. + Tổng công suất: 25W + Số lượng loa: 1 Loa bass, 2 loa treble. + Điều chỉnh âm lượng: Có. + Kết nối thiết bị: jack cắm 3.5mm. + Điện áp:&nbsp;&nbsp;AC 100 V - 240V, 50 / 60 Hz 350mA. XEM THÊM: LOA CREATIVE LOA BLUENER LOA SOUDBAR LOA DI ĐỘNG', '{"Model":"LOA LOGITECH Z313 50W 2.1"}', 0, 1);
