INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1029312996', 'SP009489', '1029312996', 'https://www.maytinhbienhoa.vn/products/loa-logitech-z407-khong-day-2-1', 'LOA LOGITECH Z407 KHÔNG DÂY 2.1 - 80W', 'loa-logitech-z407-khong-day-2-1', 'brand_logitech_591', 'cat_accessories', 1989000, 2490000, 20, 1591200, 24, 'in_stock', 'LOA LOGITECH Z407 KHÔNG DÂY 2.1 - 80W', '* THÔNG SỐ KỸ THUẬT Hãng sản xuất: Logitech&nbsp; Model: Z407 2.1 Total watts (Peak): 80W Total watts (RMS): 40W Subwoofer: 20W Satellites: 2 x 10W 3.5 mm input: 1 Micro-USB input: 1 Bluetooth: 5.0 Dimensions: Satellite:&nbsp; 199.9 x&nbsp;93.9 x 85.2 mm (389.6 g) Subwoofer:&nbsp; 240&nbsp;x&nbsp;234&nbsp;x 180&nbsp;(2450.6 g) Wireless Control Dial:&nbsp; 69.9&nbsp;x&nbsp;29.4&nbsp;(51.8 g) Additional features: 20-meter (65 feet) wireless range 12-month battery life (2 AAA included) System requirements: Windows, Mac, or Chrome based computer via AUX, USB-A, Bluetooth and iOS or Android Package contents: Two satellite speakers Subwoofer 3.5 mm cable User documentation Đánh giá chi tiết loa vi tính không dây Logitech Z407 2.1 Chơi game và giải trí cùng âm thanh tuyệt vời cùng&nbsp;loa Bluetooth&nbsp;Logitech Z470 gồm loa siêu trầm và điều khiển không dây. Cảm nhận âm thanh đắm chìm, âm trầm sâu và rõ ràng, đồng thời điều khiển bằng nút xoay không dây. Z407 là loa hai vị trí thời trang, bạn có thể đặt chúng theo chiều ngang hoặc chiều dọc.&nbsp; Loa có thể kết nối bằng nhiều cách, từ Bluetooth 5.0, cáp chuyển đổi USB sang Audio 3,5 mm và đầu vào phụ 3,5mm. Chìm đắm trong âm thanh&nbsp; Bộ loa đi kèm công suất 80 watt. Xử lý tín hiệu kỹ thuật số (DSP) mang đến âm thanh sống động như thật. Loa siêu trầm có công suất 20 watt được chuyển xuống, tăng cường “bùng nổ” nghe nhạc, xem phim và chơi game, đồng thời duy trì âm thanh sống động, phong phú. Đa kết nối và chuyển đổi không dây L', '{"Hãng sản xuất:":"Logitech&nbsp;","Model:":"Z407 2.1","Total watts (Peak):":"80W","Total watts (RMS):":"40W","Subwoofer:":"20W","Satellites:":"2 x 10W","3.5 mm input:":"1","Micro-USB input:":"1","Bluetooth:":"5.0","Dimensions:":"Satellite:&nbsp; 199.9 x&nbsp;93.9 x 85.2 mm (389.6 g) Subwoofer:&nbsp; 240&nbsp;x&nbsp;234&nbsp;x 180&nbsp;(2450.6 g) Wireless Control Dial:&nbsp; 69.9&nbsp;x&nbsp;29.4&nbsp;(51.8 g)","Additional features:":"20-meter (65 feet) wireless range 12-month battery life (2 AAA included)","System requirements:":"Windows, Mac, or Chrome based computer via AUX, USB-A, Bluetooth and iOS or Android"}', 0, 1);
