INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1034298846', 'SP104996', '1034298846', 'https://www.maytinhbienhoa.vn/products/tan-nhiet-nuoc-aio-asus-rog-strix-lc-ii-280-argb', 'TẢN NHIỆT NƯỚC AIO ASUS ROG STRIX LC II 280 ARGB', 'tan-nhiet-nuoc-aio-asus-rog-strix-lc-ii-280-argb', 'brand_asus_316', 'cat_accessories', 4990000, 6590000, 24, 3992000, 24, 'in_stock', 'TẢN NHIỆT NƯỚC AIO ASUS ROG STRIX LC II 280 ARGB', 'TẶNG&nbsp;KIT SOCKET 1700 NZXT/ASUS ROG (SP106226) Bộ tản nhiệt AIO cho&nbsp; CPU ROG Strix LC II 280 ARGB với Aura Sync, hỗ trợ&nbsp;Intel&nbsp; ® &nbsp;LGA 1150/1151/1155/1156/1200/2066 và AMD AM4 / TR4 và quạt tản nhiệt ARGB kép ROG 140 mm Máy bơm Asetek thế hệ thứ bảy mang lại khả năng làm mát vượt trội và kiểm soát tiếng ồn tối thiểu với phạm vi hoạt động bắt đầu từ 800 vòng / phút. Quạt tản nhiệt công nghệ ROG Axial cung cấp luồng không khí tối ưu và áp suất tĩnh. Hệ thống chiếu sáng RGB có thể xử lý riêng trên nắp máy bơm phủ NCVM và quạt tản nhiệt mang đến một thiết kế hiện đại, kiểu dáng đẹp. Tính thẩm mỹ bổ sung hoàn hảo cho các bo mạch chủ ROG để mang lại những gì tốt nhất cho PC của bạn. Ống nước được gia cố giúp tăng độ bền vượt trội . &nbsp; Thông số kỹ thuật Block nước – Khối nước dimention:80 x 80 x 45 mm – Vật liệu khối (Tấm CPU):Đồng Máy bơm &nbsp; – Công nghệ :Máy bơm Asetek thế hệ thứ 7 – Tốc độ của bơm&nbsp; :800 – 2.800 +/- 300 – Điện áp :12V DC, 2W, 0,3A Rad nước tản nhiệt &nbsp; – Kích thước bộ rad tản nhiệt:&nbsp;143 x 315 x 30mm – Vật liệu tản nhiệt:&nbsp;Nhôm&nbsp; – Ống:&nbsp;Ống cao su&nbsp; – Chiều dài ống:&nbsp;380 mm Quạt Quạt:MÔ HÌNH QUẠT ROG STRIX 14 ARGB – Kích thước:&nbsp;2 x Khe cắm quạt (140mm) – Kích thước:140 x 140 x 25,5mm – Tốc độ:&nbsp;700 – 2100 vòng / phút +/- 10% – Áp suất tĩnh:3,1 mmH2O – Luồng không khí:&nbsp;102,3 CFM – Tiếng ồn:&nbsp;35,7 dB (A) – Chế độ điều khiển:&nbsp;PWM / DC Các tính năng đặc biệt Hỗ trợ AURA Sync Khả năn', '{"Block nước":"– Khối nước dimention:80 x 80 x 45 mm – Vật liệu khối (Tấm CPU):Đồng","Máy bơm &nbsp;":"– Công nghệ :Máy bơm Asetek thế hệ thứ 7 – Tốc độ của bơm&nbsp; :800 – 2.800 +/- 300 – Điện áp :12V DC, 2W, 0,3A","Rad nước tản nhiệt &nbsp;":"– Kích thước bộ rad tản nhiệt:&nbsp;143 x 315 x 30mm – Vật liệu tản nhiệt:&nbsp;Nhôm&nbsp; – Ống:&nbsp;Ống cao su&nbsp; – Chiều dài ống:&nbsp;380 mm","Các tính năng đặc biệt":"Hỗ trợ AURA Sync","Khả năng tương thích":"Intel: LGA 1150, 1151, 1152, 1155, 1156, 1200, 1366, 2011, 2011-3, 2066 AMD: AM4, TR4 *","Bảo hành":"– 6 năm","Bổ sung":"Dòng ROG STRIX LC * Giá đỡ đi kèm với Gói CPU TR4."}', 0, 1);
