INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1039885200', 'SP106196', '1039885200', 'https://www.maytinhbienhoa.vn/products/bo-phat-wifi-4g-lte-d-link-dwr-m920-chuan-n-300mbps', 'BỘ PHÁT WIFI 4G LTE D-LINK DWR-M920 - CHUẨN N 300MBPS', 'bo-phat-wifi-4g-lte-d-link-dwr-m920-chuan-n-300mbps', 'brand_d-link_415', 'cat_accessories', 1290000, 1290000, 0, 1032000, 24, 'in_stock', 'BỘ PHÁT WIFI 4G LTE D-LINK DWR-M920 - CHUẨN N 300MBPS', 'Giao diện Kết nối không dây chuẩn N 300 Hỗ trợ USIM để kết nối Internet thông qua 4G LTE Cat 4 3 cổng LAN tốc độ 10/100Mbps 1 cổng WAN tốc độ 10/100Mbps Số lượng Ăn-ten 2×2 Ăn-ten cho mạng không dây Wi-fi – 3dBi 2×2 Ăn-ten cho mạng 4G LTE – 3dBi Chuẩn Wi-Fi 802.11n/g/b Hỗ trợ 1 băng tầng: 2.4GHz Tốc độ tối đa 300Mbps khi sử dụng mạng Internet từ nhà cung cấp dịch vụ Tốc độ tải xuống/lên khi sử dụng mạng 4G LTE lần lượt 150/50Mbps Bảo mật mạng không dây WEP WPA2™ (Wi-Fi Protected Access) Nút Wi-Fi Protected Setup (WPS) cho kết nối bảo mật “một chạm” với các thiết bị khác Thông tin &amp; nâng cấp Dễ dàng thiết lập và sử dụng Hỗ trợ chuyển đổi dự phòng WAN (3G / 4G &amp; kết nối băng thông rộng có dây) Kích thước 192x 118x 31 mm (W x D x H) Lưu ý: &nbsp;Thiết bị sử dụng nguồn điện trực tiếp từ cổng cắm trên ổ điện. Thiết bị không tích hợp pin! Bộ định tuyến 4G LTE DWR-M920 của D-Link cho phép bạn truy cập và chia sẻ kết nối băng thông rộng di động 4G LTE của mình. Sau khi kết nối, bạn có thể truyền dữ liệu, truyền phát phương tiện và gửi tin nhắn SMS. Chỉ cần lắp thẻ SIM / USIM của bạn và chia sẻ kết nối Internet 4G LTE của bạn thông qua mạng không dây tốc độ cao hoặc bất kỳ cổng nào trong ba cổng Ethernet. DWR-M920 có các tùy chọn cho cả Internet băng thông rộng có dây thông qua cổng WAN tích hợp và băng thông rộng 3G / 4G không dây sử dụng thẻ SIM. Nó cũng hỗ trợ chuyển đổi dự phòng khi băng thông rộng có dây bị ngắt, nó sẽ tự động chuyển sang băng rộng di động, cung cấp cho b', '{"Giao diện":"Kết nối không dây chuẩn N 300 Hỗ trợ USIM để kết nối Internet thông qua 4G LTE Cat 4 3 cổng LAN tốc độ 10/100Mbps 1 cổng WAN tốc độ 10/100Mbps","Số lượng Ăn-ten":"2×2 Ăn-ten cho mạng không dây Wi-fi – 3dBi 2×2 Ăn-ten cho mạng 4G LTE – 3dBi","Chuẩn Wi-Fi":"802.11n/g/b Hỗ trợ 1 băng tầng: 2.4GHz Tốc độ tối đa 300Mbps khi sử dụng mạng Internet từ nhà cung cấp dịch vụ Tốc độ tải xuống/lên khi sử dụng mạng 4G LTE lần lượt 150/50Mbps","Bảo mật mạng không dây":"WEP WPA2™ (Wi-Fi Protected Access) Nút Wi-Fi Protected Setup (WPS) cho kết nối bảo mật “một chạm” với các thiết bị khác"}', 0, 1);
