INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1065251777', 'SP1081686', '1065251777', 'https://www.maytinhbienhoa.vn/products/usb-thu-wifi-tp-link-archer-t2u-plus', 'USB THU WIFI TP-LINK ARCHER T2U PLUS - Băng Tần Kép', 'usb-thu-wifi-tp-link-archer-t2u-plus', 'brand_tp-link_511', 'cat_networking-cameras', 249000, 249000, 0, 199200, 24, 'in_stock', 'USB THU WIFI TP-LINK ARCHER T2U PLUS - Băng Tần Kép', 'THÔNG SỐ KỸ THUẬT &nbsp; Băng tần Wifi Wi-Fi Tốc Độ Cao: Hỗ trợ 256QAM tăng tốc độ dữ liệu, 200 Mbps trên băng tần 2.4 GHz và 433 Mbps trên băng tần 5 GHz, giúp bạn tận hưởng trọn vẹn Wi-Fi chuẩn AC tốc độ cao. Tính năng Bluetooth Không Angten Ăng-ten ngoài Chuẩn kết nối Chuẩn AC Chuẩn cắm USB Mô tả khác Wi-Fi Băng Tần Kép: Băng tần 2.4 GHz và 5 GHz cung cấp kết nối linh hoạt, cho phép các thiết bị của bạn truy cập vào router Wi-Fi băng tần kép mới nhất mang lại tốc độ nhanh hơn và vùng phủ rộng hơn. Ăng Ten Độ Lợi Cao: Ăng ten độ lợi cao 5dBi tăng cường đáng kể cường độ tín hiệu truyền và nhận của bộ chuyển đổi USB Hỗ Trợ Hệ Điều Hành Mới Nhất: Hoàn toàn tương thích với Windows 11/10/8.1/8/7/XP, Mac OS 10.15 và cũ hơn &nbsp; Cạc mạng Wifi USB TP-Link Archer T2U Plus AC600Mbps &nbsp; Archer T2U Plus&nbsp;là thiết bị thu sóng Wifi chuẩn AC thiết kế nhỏ gọn, cung cấp tốc độ mạnh mẽ trên 2 băng tần 2.4GHz và 5GHz, có thể sử dụng dễ dàng ở bất kỳ nơi nào bạn muốn. Kiểu dáng thanh mảnh, tinh tế, màu đen hiện đại, cổng kết nối USB cho phép bạn cắm trực tiếp&nbsp; cạc mạng Wifi USB &nbsp;vào laptop, PC của mình với thao tác đơn giản, nhanh gọn. Thiết bị mạng đạt tốc độ cao Nhờ hỗ trợ 256QAM mà tốc độ dữ liệu trên băng tần 2.4GHz tăng từ 150 đến 200 Mbps, cho hiệu suất nhanh hơn 33%, phục vụ hoàn hảo cho các nhu cầu thường nhật như lướt web, nghe nhạc, trong khi tốc độ 433 Mbps trên băng tần 5GHz lại phù hợp cho bạn gọi video trực tuyến chuẩn HD, chơi game trực tuyến mà không sợ ', '{"Băng tần Wifi":"Wi-Fi Tốc Độ Cao: Hỗ trợ 256QAM tăng tốc độ dữ liệu, 200 Mbps trên băng tần 2.4 GHz và 433 Mbps trên băng tần 5 GHz, giúp bạn tận hưởng trọn vẹn Wi-Fi chuẩn AC tốc độ cao.","Tính năng Bluetooth":"Không","Angten":"Ăng-ten ngoài","Chuẩn kết nối":"Chuẩn AC","Chuẩn cắm":"USB"}', 0, 1);
