INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1058023170', 'SP1081112', '1058023170', 'https://www.maytinhbienhoa.vn/products/usb-bluetooth-5-3-tp-link-ub500-plus', 'USB Bluetooth 5.3 TP-Link UB500 Plus', 'usb-bluetooth-5-3-tp-link-ub500-plus', 'brand_tp-link_511', 'cat_networking-cameras', 145000, 145000, 0, 116000, 24, 'in_stock', 'USB Bluetooth 5.3 TP-Link UB500 Plus', '* Bluetooth 5.3&nbsp;—&nbsp;Cải thiện bảo mật và độ tin cậy so với Bluetooth thế hệ trước * Kết nối không dây&nbsp;– Cung cấp khả năng giao tiếp ổn định và thuận tiện giữa các thiết bị Bluetooth và PC hoặc máy tính xách tay của bạn * Ăng-ten đa hướng có thể điều chỉnh&nbsp;–&nbsp;Xoay và điều chỉnh ăng-ten đa hướng để cải thiện trải nghiệm và hiệu suất của người dùng trong các môi trường khác nhau.​​​​​​ * Hệ điều hành được hỗ trợ&nbsp;– Windows 11/10/8.1/7 &nbsp; &nbsp; - Bluetooth 5.3: Tốc Độ Nhanh Hơn, Mạnh Mẽ Hơn Công nghệ Bluetooth 5.3 tiên tiến nhất hiện nay thừa hưởng tốc độ vượt trội từ các phiên bản trước đó. Bluetooth 5.3 mới nhất còn được cải thiện về độ tin cậy và bảo mật, đảm bảo sự phối hợp mạnh mẽ hơn với các thiết bị như tay cầm chơi game, tai nghe, bàn phím, và nhiều thiết bị khác. &nbsp; - Anten Có Thể Điều Chỉnh, Đa Hướng Với anten có thể điều chỉnh đa hướng, bạn dễ dàng xoay và điều chỉnh để tối ưu hóa trải nghiệm người dùng và hiệu suất trong các môi trường khác nhau. - Kết Nối Bluetooth Với Máy Tính Của Bạn UB500 Plus biến các PC và laptop không có Bluetooth trở nên có khả năng kết nối Bluetooth. Chỉ cần kết nối các thiết bị Bluetooth của bạn với máy tính và tận hưởng một cách dễ dàng. Thiết bị hỗ trợ kết nối đồng thời lên đến 7 thiết bị Bluetooth với kết nối không dây mạnh mẽ. Bạn có thể chuyển file, nhạc, video giữa các thiết bị Bluetooth và máy tính với tốc độ truyền tải nhanh gấp 2 lần.* Dữ liệu về tốc độ, khoảng cách, và dung lượng dựa trên thử nghi', '{"Model":"USB Bluetooth 5.3 TP-Link UB500 Plus"}', 0, 1);
