INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1053279648', 'SP109576', '1053279648', 'https://www.maytinhbienhoa.vn/products/bo-phat-wifi-6-tp-link-archer-ax12-ax1500-2-bang-tan-wpa3', 'BỘ PHÁT WIFI 6 TP-LINK ARCHER AX12 - AX1500 | 2 BĂNG TẦN | WPA3', 'bo-phat-wifi-6-tp-link-archer-ax12-ax1500-2-bang-tan-wpa3', 'brand_tp-link_511', 'cat_networking-cameras', 779000, 1099000, 29, 623200, 24, 'in_stock', 'BỘ PHÁT WIFI 6 TP-LINK ARCHER AX12 - AX1500 | 2 BĂNG TẦN | WPA3', 'THÔNG SỐ KỸ THUẬT &nbsp; Tốc độ WIFI AX1500 5 GHz: 1201 Mbps (802.11ax) 2.4 GHz: 300 Mbps (802.11n) Chuẩn kết nối Chuẩn AX (Wifi 6) Angten 4 Ăng-ten ngoài Cổng kết nối 1× Gigabit WAN Port 3× Gigabit LAN Ports Tốc độ LAN 10/100/1000Mbps Công nghệ Mesh Có Nhu cầu sử dụng Gia đình, Nhà hàng Số thiết bị truy cập 30-40 User Lắp đặt Để bàn Mô tả khác Công nghệ Wi-Fi 6 truyền nhiều dữ liệu hơn đến nhiều thiết bị hơn bằng cách sử dụng công nghệ OFDMA và MU-MIMO mang tính cách mạng đồng thời giúp giảm độ trễ. Vùng phủ sóng tốt hơn: Đạt được vùng phủ sóng WiFi mạnh nhất, đáng tin cậy nhất với Archer AX12 vì nó tập trung cường độ tín hiệu cho các thiết bị của bạn bằng công nghệ Beamforming và bốn ăng-ten ngoài mạnh mẽ. Tăng thời lượng pin: Công nghệ Target Wake Time giúp giảm mức tiêu thụ năng lượng của thiết bị đễ kéo dài thời lượng sử dụng pin.3 &nbsp; Bộ phát wifi 6 TP-Link Archer AX12 (Chuẩn AX/ AX1500Mbps/ 4 Ăng-ten ngoài/ Wifi Mesh/ 35 User) Được trang bị công nghệ không dây mới nhất,&nbsp; Bộ phát wifi &nbsp;6 TP-Link Archer AX12 có tốc độ nhanh hơn, khả năng chịu tải lớn hơn và hạn chế tối đa hiện tượng tắc nghẽn mạng. Tốc độ tối đa Tất cả các cổng kết nối mạng trên&nbsp; Bộ phát wifi 6 TP-Link Archer AX12&nbsp; cho phép bạn tận dụng tối đa sự ổn định và tốc độ cao của Interne, lên tới 1Gbps. Bạn có thể kết nối với PC, smart TV để tận hưởng kết nối mạng nhanh chóng và đáng tin cậy. &nbsp; WiFi phủ sóng khắp ngôi nhà Sở hữu 4 ăng-ten ngoài hiệu suất cao,&nbsp; Bộ phát wifi 6 TP-L', '{"Tốc độ WIFI":"AX1500 5 GHz: 1201 Mbps (802.11ax) 2.4 GHz: 300 Mbps (802.11n)","Chuẩn kết nối":"Chuẩn AX (Wifi 6)","Angten":"4 Ăng-ten ngoài","Cổng kết nối":"1× Gigabit WAN Port 3× Gigabit LAN Ports","Tốc độ LAN":"10/100/1000Mbps","Công nghệ Mesh":"Có","Nhu cầu sử dụng":"Gia đình, Nhà hàng","Số thiết bị truy cập":"30-40 User","Lắp đặt":"Để bàn"}', 0, 1);
