INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1068159945', 'SP1082229', '1068159945', 'https://www.maytinhbienhoa.vn/products/camera-ezviz-h6c-pro-2k-3mp-xoay-360-do-trong-nha', 'Camera Ezviz H6C Pro 2K (3MP/XOAY 360 ĐỘ/TRONG NHÀ)', 'camera-ezviz-h6c-pro-2k-3mp-xoay-360-do-trong-nha', 'brand_ezviz_408', 'cat_networking-cameras', 459000, 459000, 0, 367200, 24, 'in_stock', 'Camera Ezviz H6C Pro 2K (3MP/XOAY 360 ĐỘ/TRONG NHÀ)', 'Thông số kỹ thuật camera WiFi quay quét thông minh EZVIZ H6C PRO 2K+ – Camera quay quét sử dụng trong nhà – Chuấn nén H.265 – Cảm biến ảnh: F2.4 @ 1/3″ Progressive Scan CMOS – Độ phân giải 4MP, 2560 x 1440 – Ống kính: 4mm, góc nhìn: 85 ° (Chéo), 75 ° (Ngang), 45 ° (Dọc) – Hồng ngoại 10m – Chuẩn Wi-Fi: IEEE 802.11 b, 802.11 g, 802.11 n – Dải tần số: 2,4 ~ 2,4835 GHz – Hỗ trợ DNR 3D, WDR kỹ thuật số, Bộ lọc cắt hồng ngoại với tính năng tự động chuyển đổi. – Hỗ trợ phát hiện và theo dõi chuyển động thông minh – Hỗ trợ thẻ nhớ MicroSD (Lên đến 256 GB) – Hỗ trợ lưu trữ EZVIZ CloudPlay (đăng ký mua riêng) – Cài đặt wifi thông minh với phần mềm EZVIZ – quá trình cài đặt chỉ mất vài phút với người lần đầu sử dụng – Nguồn cấp: DC 5V/ 1A – Công suất: Tối đa 5 W – Kích thước: 88 × 88,2 × 119 mm – Khối lượng tịnh: 218g – Điều kiện hoạt động: -10° đến 45°C (14° đến 113°F); Độ ẩm 95% trở xuống (không ngưng tụ) – Chứng nhận: CE/ UL/ FCC/ WEEE/ REACH/ RoHS/ UKCA – Xuất xứ: Trung Quốc. – Bảo hành: 24 tháng. &nbsp; Camera WiFi quay quét EZVIZ H6C PRO 2K+ EZVIZ H6C PRO&nbsp; 2K+ &nbsp;là một chiếc&nbsp; camera IP Wifi &nbsp;linh hoạt đơn giản mà bạn có thể cài đặt trong nhà làm màn hình cho thú cưng hoặc em bé hoặc sử dụng nó để thêm một lớp bảo vệ bổ sung trong nhà của bạn. Không giống như nhiều máy ảnh chỉ ghi lại ở một góc xem cố định, H6c xoay để chụp toàn cảnh với độ rõ nét và thậm chí có thể phát hiện và theo dõi chuyển động một cách thông minh. Với sự trợ giúp ', '{"Model":"Camera Ezviz H6C Pro 2K (3MP/XOAY 360 ĐỘ/TRONG NHÀ)"}', 0, 1);
