INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1071744628', 'SP1082995', '1071744628', 'https://www.maytinhbienhoa.vn/products/camera-wifi-ezviz-h6c-g1-3k-5mp-360-do', 'Camera WiFi EZVIZ H6C G1 3K 5MP 360 ĐỘ', 'camera-wifi-ezviz-h6c-g1-3k-5mp-360-do', 'brand_ezviz_408', 'cat_networking-cameras', 590000, 590000, 0, 472000, 24, 'in_stock', 'Camera WiFi EZVIZ H6C G1 3K 5MP 360 ĐỘ', 'Thông số kỹ thuật Camera quan sát Chế độ bảo hành 24 tháng Độ phân giải 5.0 Megapixel Chuẩn nén H.265 Camera theo ống kính Loại 4mm Tầm quan sát 20m Tính năng, hỗ trợ – Tầm nhìn đêm có màu – Phát hiện người và thú cưng – Theo dõi tự động (Auto Tracking) – Phát hiện tiếng ồn lớn – Chế độ tuần tra tự động – Đàm thoại hai chiều – Nút gạt che riêng tư – Băng tần kép Wi-Fi 2.4GHz và 5GHz – Hỗ trợ lưu trữ linh hoạt Nguồn điện DC 5V / 2A Kích thước 88 × 88 × 117.3 mm Trọng lượng 222g &nbsp; &nbsp; Camera Ezviz H6C G1 3K ( 5MP ) Camera Ezviz H6C G1 3K ( 5MP ) &nbsp;là mẫu camera an ninh trong nhà mới nhất, được thiết kế để nâng cao trải nghiệm giám sát thông minh cho gia đình hiện đại. Với độ phân giải 3K Ultra HD, sản phẩm mang đến hình ảnh rõ nét vượt trội, giúp bạn theo dõi mọi hoạt động trong nhà một cách chi tiết. Camera Ezviz H6C G1 3K Diện mạo hoàn toàn mới – Bứt phá mọi giới hạn Camera Ezviz H6C G1 3K ( 5MP ) Camera được yêu thích nhất mọi thời đại Vẫn hiệu năng đáng tin cậy ấy, nhưng giờ đây khoác lên mình diện mạo hoàn toàn mới. &nbsp;Camera Ezviz H6C G1 3K ( 5MP )&nbsp; chính là bước tiến đột phá trong dòng camera quay quét trong nhà của EZVIZ. Chi tiết tinh xảo, câu chuyện sống động. Trọn vẹn với 3K. Bao quát mọi góc nhìn. Kể cả trên cao hay dưới thấp. Camera Ezviz H6C G1 3K ( 5MP ) &nbsp;được thiết kế để mang đến tầm nhìn rộng hơn hẳn và khác biệt so với phần lớn camera trên thị trường. Giờ đây, bạn có thể dễ dàng tìm được vị trí lắp đặt tối ưu và sử dụng linh hoạt cho n', '{"Camera quan sát":"Chế độ bảo hành","Độ phân giải":"5.0 Megapixel","Chuẩn nén":"H.265","Camera theo ống kính":"Loại 4mm","Tầm quan sát":"20m","Nguồn điện":"DC 5V / 2A","Kích thước":"88 × 88 × 117.3 mm","Trọng lượng":"222g"}', 0, 1);
