INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1074530156', 'SP1083586', '1074530156', 'https://www.maytinhbienhoa.vn/products/camera-ezviz-h8c-pro-3k-5mp-xoay-360-do-ngoai-troi-dam-thoai-2-chieu', 'CAMERA EZVIZ H8C Pro 3K (5MP/ XOAY 360 ĐỘ/ NGOÀI TRỜI/ ĐÀM THOẠI 2 CHIỀU)', 'camera-ezviz-h8c-pro-3k-5mp-xoay-360-do-ngoai-troi-dam-thoai-2-chieu', 'brand_ezviz_408', 'cat_networking-cameras', 949000, 949000, 0, 759200, 24, 'in_stock', 'CAMERA EZVIZ H8C Pro 3K (5MP/ XOAY 360 ĐỘ/ NGOÀI TRỜI/ ĐÀM THOẠI 2 CHIỀU)', '&nbsp; &nbsp; &nbsp; Camera Quay 360 Ngoài Trời Ezviz H8C Pro 3K (5MP) Kinh nghiệm tăng cường an ninh ngoài trời với&nbsp; Camera Quay 360 Ngoài Trời Ezviz H8C Pro 3K (5MP) , cung cấp video 360 độ đặc biệt, sống động trong 3K để đảm bảo không có chi tiết về tài sản của bạn bị không chú ý, từ ngày sang đêm. Nhờ tính năng theo dõi phóng to tự động tiên tiến của nó, H8c Pro 3K Pans và Tilts để chụp toàn bộ hoạt động của một người hoặc một chiếc xe di chuyển xung quanh nhà của bạn, và phản ứng với cảnh báo hữu ích và âm thanh tại chỗ và sự ngăn chặn ánh sáng để cung cấp thêm an ninh ngay cả khi bạn không nhìn. Thông số kỹ thuật camera ngoài trời Ezviz&nbsp;H8C Pro 3K&nbsp;(CS-H8c-R200-1J5WKFL) Camera quay quét WiFi 3K – H.265 •Độ phân giải 2880*1620 @ 30fps •Ống kính 4mm@ F1.6, 108°(Chéo), 91° (Ngang), 48° (Dọc), •Quay ngang 350°, dọc 80° •Hỗ trợ DWDR, 3D DNR , ICR •Chuấn nén H.265/H.264 •Phát hiện chuyển động, phát hiện hình dáng người, phương tiện •Theo dõi chuyển động thông minh •Hỗ trợ cảnh báo bằng còi và đèn chớp •Hỗ trợ 3 chế độ hoạt động: màu ban đêm, hồng ngoại ban đêm, màu thông minh •Hỗ trợ khe cắm thẻ nhớ đến 512GB •Hỗ trợ lên đến 12 điểm preset •Tích hợp Micro và Loa – Hỗ trợ đàm thoại 2 chiều với chất lượng âm thanh trung thực •Hồng ngoại 30m, đèn trợ sáng 20m •Hỗ trợ WiFi , IEEE802.11b, 802.11g, 802.11n , tần số 2.4GHz •Hỗ trợ WiFi + cài đặt WiFi thông minh với phần mềm EZVIZ – quá trình cài đặt chỉ mất vài phút với ngườ', '{"Model":"CAMERA EZVIZ H8C Pro 3K (5MP/ XOAY 360 ĐỘ/ NGOÀI TRỜI/ ĐÀM THOẠI 2 CHIỀU)"}', 0, 1);
