INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1054585976', 'SP1080076', '1054585976', 'https://www.maytinhbienhoa.vn/products/camera-wifi-ezviz-h9c-quay-quet-ong-kinh-kep-5mp-5mp', 'CAMERA WIFI EZVIZ H9C QUAY QUÉT, ỐNG KÍNH KÉP 3K (5MP+5MP)', 'camera-wifi-ezviz-h9c-quay-quet-ong-kinh-kep-5mp-5mp', 'brand_ezviz_408', 'cat_networking-cameras', 1350000, 1350000, 0, 1080000, 24, 'in_stock', 'CAMERA WIFI EZVIZ H9C QUAY QUÉT, ỐNG KÍNH KÉP 3K (5MP+5MP)', 'Thông số kỹ thuật camera&nbsp;WiFi quay quét, ống kính kép EZVIZ H9c (3MP+3MP) – Model: CS-H9c-R100-8H33WKFL – Độ phân giải 3MP+3MP – Chuấn nén H.265/H.264 – Camera chính 2K + Camera toàn cảnh 2K – 2 chế độ tuần tra để giám sát tự động – Phát hiện kép để tự động theo dõi thông minh, Phát hiện hình dáng người/phương tiện AI – Tầm nhìn màu ban đêm 30m, tầm nhìn hồng ngoại ban đêm 30m – Đàm thoại 2 chiều, Điều khiển 1 chạm để thay đổi chế độ xem được liên kết – Cảnh báo báo động với còi và đèn cảnh báo – Hỗ trợ WiFi, IEEE802.11b, 802.11g, 802.11n , tần số 2.4GHz + 1 cổng mạng 10/100M – Hỗ trợ thẻ nhớ MicroSD tối đa 512GB, Hỗ trợ lưu trữ Ezviz Cloud – Tương thích với Google và Alexa – Hỗ trợ WiFi + cài đặt WiFi thông minh với phần mềm EZVIZ – quá trình cài đặt chỉ mất vài phút với người lần đầu sử dụng – Chống bụi nước IP66 (ngoài trời) – Nguồn cấp: DC12V/1A – Công suất: &lt;5.32W. – Chất liệu vỏ kim loại + nhựa kết hợp – Chứng nhận: CE/ UL/ FCC/ WEEE/ REACH/ RoHS/ UKCA – Xuất xứ: Trung Quốc. – Bảo hành: 24&nbsp;tháng. &nbsp; Camera EZVIZ H9c (3MP+3MP) &nbsp;với kết nối không dây wifi không dây có thể là lựa chọn lý tưởng của bạn như một&nbsp;camera ngoài trời&nbsp;giàu tính năng nhằm tăng cường an toàn cho ngôi nhà, đặc biệt là để giám sát khu vực rộng lớn. Với độ phân giải kép 2K+2K vượt trội và góc nhìn 360 độ, nó có thể dễ dàng quan sát sân sau hoặc lối vào gara của bạn mà không có điểm mù. Camera H9c còn bổ sung thêm tính năng phát hiện người và tự đ', '{"Model":"CAMERA WIFI EZVIZ H9C QUAY QUÉT, ỐNG KÍNH KÉP 3K (5MP+5MP)"}', 0, 1);
