INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1066295332', 'SP1081770', '1066295332', 'https://www.maytinhbienhoa.vn/products/camera-wifi-ezviz-c6n-pro-2k-3mp', 'Camera Wifi EZVIZ C6N Pro 2K 3MP', 'camera-wifi-ezviz-c6n-pro-2k-3mp', 'brand_ezviz_408', 'cat_networking-cameras', 439000, 439000, 0, 351200, 24, 'in_stock', 'Camera Wifi EZVIZ C6N Pro 2K 3MP', 'Các thông số của&nbsp;Camera Ezviz C6N Pro 2K 3MP &nbsp; Chuẩn nén: H.264/H.265 Độ phân giải 3MP/2K Độ phân giải tối đa: 2560 × 1440 Tỷ lệ khung hình: Tối đa 30fps; Tự điều chỉnh trong quá trình truyền mạng Cảm biến ảnh: F1.6@1/3″ CMOS Ống kính: 4mm, góc nhìn: 90°(Chéo), 80° (Ngang), 43°(Dọc) Tầm quan sát: 10m Hỗ trợ WDR kỹ thuật số, DNR 3D Hỗ trợ tính năng thông minh: Phát hiện chuyển động, Phát hiện hình dạng con người, Phát hiện tiếng ồn lớn, Phát hiện chế độ tuần tra Hỗ trợ khe cắm thẻ nhớ Micro SD (Tối đa 512G) Tiêu chuẩn: IEEE802.11a, 802.11b, 802.11g, 802.11n, Nguồn điện: DC 5V/ 2A Mức tiêu thụ điện năng: Tối đa 8W Kích thước: 88mm x 88.2 mm x 119mm Trọng lượng: 252 g Chứng nhận: CE/ UL/ FCC/ WEEE/ REACH/ RoHS/ UKCA Xuất xứ: Trung Quốc Các tính năng nổi bật của&nbsp;Camera Ezviz C6N Pro 2K 3MP Camera trong nhà C6N Pro 2K 3MP&nbsp;với tầm quan sát toàn diện 360 độ: Với Camera C6N Pro 2K 3MP, bạn có thể quan sát từng góc nhỏ trong ngôi nhà của mình. Với góc quay ngang 340° và góc nhìn rộng, Camera C6N Pro 3MP mang đến khả năng quan sát toàn diện cả ngày lẫn đêm. Camera Ezviz C6N Pro 2K 3MP quan sát toàn diện Hình ảnh sắc nét ngay cả trong điều kiện ánh sáng yếu: Tính năng hồng ngoại và đèn ánh sáng trắng giúp&nbsp;Camera Ezviz C6N Pro 2K 3MP quan sát rõ ràng ngay cả trong điều kiện thiếu ánh sáng. Chất lượng hình ảnh vẫn đảm bảo sắc nét, truyền tải mọi góc nhìn chi tiết một cách rõ ràng. Camera Ezviz C6N Pro 2K 3MP ghi hình ảnh trong đêm với khoảng cách 10 mét Camera Wif', '{"Chuẩn nén":"H.264/H.265","Độ phân giải tối đa":"2560 × 1440","Tỷ lệ khung hình":"Tối đa 30fps; Tự điều chỉnh trong quá trình truyền mạng","Cảm biến ảnh":"F1.6@1/3″ CMOS","Ống kính":"4mm, góc nhìn: 90°(Chéo), 80° (Ngang), 43°(Dọc)","Tầm quan sát":"10m","Hỗ trợ tính năng thông minh":"Phát hiện chuyển động, Phát hiện hình dạng con người, Phát hiện tiếng ồn lớn, Phát hiện chế độ tuần tra","Tiêu chuẩn":"IEEE802.11a, 802.11b, 802.11g, 802.11n,"}', 0, 1);
