INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1057881419', 'SP1081090', '1057881419', 'https://www.maytinhbienhoa.vn/products/camera-tiandy-tc-h332n-wifi-hong-ngoai-3-0-megapixel-i2w-wifi-eu-4mm-v4-1', 'Camera TIANDY TC-H332N Wifi Hồng Ngoại 3.0 Megapixel (I2W/WIFI/Eu/4mm/V4.1)', 'camera-tiandy-tc-h332n-wifi-hong-ngoai-3-0-megapixel-i2w-wifi-eu-4mm-v4-1', 'brand_tiandy_457', 'cat_networking-cameras', 399000, 399000, 0, 319200, 24, 'in_stock', 'Camera TIANDY TC-H332N Wifi Hồng Ngoại 3.0 Megapixel (I2W/WIFI/Eu/4mm/V4.1)', 'Camera IP Wifi hồng ngoại 3.0 Megapixel TIANDY TC-H332N (I2W/Wifi/4mm/V4.0) - Cảm biến hình ảnh: 1/2.8” CMOS.&nbsp; - Độ phân giải: 2304x1296@20fps. - Chuẩn nén video: S265+/H265/H264, hỗ trợ 2 luồng video. - Ống kính cố định: f4mm/F2.0, Fixed Iris. - Tầm quan sát hồng ngoại: 20m.&nbsp; - Hỗ trợ đèn Led trợ sáng ban đêm cho hình ảnh có màu.&nbsp; - Chức năng giảm nhiễu số 3D-DNR. - Chức năng bù ngược sáng BLC. - Chức năng chống ngược sáng Digital WDR. - Hỗ trợ Wifi IEEE802.11b/g/n, băng tần 2.4GHz. - Tích hợp micro và loa trên&nbsp; camera &nbsp;cho phép đàm thoại 2 chiều. Phát ra âm thanh cảnh báo báo động. - Báo động tin nhắn qua điện thoại khi phát hiện chuyển động. - Hỗ trợ theo dõi người chuyển động. - Khe cắm thẻ SD tối đa 512GB. - Có cổng mạng, có nút reset cứng. - Chuẩn ONVIF quốc tế. - Nguồn cấp: DC12V. - Vật liệu: Vỏ nhựa. &nbsp; Thông số kỹ thuật Camera Image Sensor 1/2.8\' CMOS Signal System PAL Min. Illumination Color: 0.02Lux@ (F2.0, ACG ON), B/W: 0Lux with IR Shutter Time 1s to 1/100,000s Day &amp; Night Dual IR Cut Filter with Auto Switch Wide Dynamic Range Digital WDR Lens Lens Type Fixed Focus 4mm Lens Mount M12 Aperture F2.0, Fixed FOV Horizontal field of view:&nbsp;82.4° Vertical field of view:&nbsp;45.4° Illuminator IR LEDs 4 IR Range Up to 20 m Wavelength 850nm White LEDs/Warmlights 1 Range Up to 10 m Compression Standard Video Compression S+265/H.265/H.264 Video Bit Rate 32 Kbps~4Mbps Audio Compression G.711A/G.711U Audio Bit Rate 8kHz, 16kHz Image Max. ', '{"Camera":"Image Sensor","Signal System":"PAL","Min. Illumination":"Color: 0.02Lux@ (F2.0, ACG ON), B/W: 0Lux with IR","Shutter Time":"1s to 1/100,000s","Day &amp; Night":"Dual IR Cut Filter with Auto Switch","Wide Dynamic Range":"Digital WDR","Lens":"Lens Type","Focus":"4mm","Lens Mount":"M12","Aperture":"F2.0, Fixed","FOV":"Horizontal field of view:&nbsp;82.4° Vertical field of view:&nbsp;45.4°","Illuminator":"IR LEDs"}', 0, 1);
