INSERT INTO products (id, sku, source_id, source_url, name, slug, brand_id, category_id, price, original_price, discount_percent, cost_price, warranty_months, status, short_description, description, specs, is_featured, is_new) VALUES ('prod_1042408845', 'SP106951', '1042408845', 'https://www.maytinhbienhoa.vn/products/camera-ip-wifi-tenda-cp3-full-hd-1080p-360', 'Camera Wifi Tenda CP3 Full HD 1080P 360', 'camera-ip-wifi-tenda-cp3-full-hd-1080p-360', 'brand_tenda_364', 'cat_networking-cameras', 290000, 599000, 52, 232000, 24, 'in_stock', 'Camera Wifi Tenda CP3 Full HD 1080P 360', 'Camera IP Wifi Tenda CP3 Full HD 1080P 360 - Camera an ninh với nhiều chế độ thông minh Camera IP Wifi Tenda CP3 Full HD 1080P 360 &nbsp;có thiết kế bảo mật cao với kết nối wifi xuyên tường giúp người dùng bắt trọn từng khoảnh khắc, hoạt động trong khuôn viên ngôi nhà, trước cửa quán hay trong lớp học. Bảo đảm an ninh với công nghệ phát hiện chuyển động và cảnh báo qua smartphone tiện lợi, điều chỉnh nhanh chóng qua App riêng biệt. Đặc điểm nổi bật Camera quay quét cho gia đình, với khả năng quan sát toàn cảnh 360° và độ phân giải FullHD 1080P&nbsp; Hỗ trợ giao tiếp qua giọng nói 2 chiều, phát hiện và theo dõi chuyển động thông minh, tính năng báo động bằng âm thanh và đèn&nbsp; Thích hợp cho gia đình, cửa hàng, lớp học... Phát hiện chuyển động lạ và cảnh báo ngay qua còi báo động và đèn LED Tự động phát hiện và theo dõi các mục tiêu di động, bằng thuật toán thị giác AI “Smart Tracking” Chế độ cài đặt sẵn đến 3 giọng nói cảnh báo trên camera Đàm thoại 2 chiều rõ ràng Tự xoay xuống để giấu đi ống kính khi kích hoạt chế độ riêng tư Công nghệ bảo mật tiên tiến Quan sát mọi ngóc ngách bên trong ngôi nhà Camera IP Wifi Tenda CP3 Full HD 1080P 360 tuy có thiết kế nhỏ nhắn nhưng lợi ích mà camera mang lại không hề nhỏ, thiết bị có khả năng ghi lại những hình ảnh sắc nét, không góc chết với tốc độ cao nhờ vào động cơ mạnh mẽ. Camera Tenda CP3 có thể quay quay ngang 360° và dọc 155° (90° trên, 65° dưới). Chất lượng hình ảnh của video Full HD 1080P kết hợp với cảm biến 2MP cung cấp vid', '{"Model":"Camera Wifi Tenda CP3 Full HD 1080P 360"}', 0, 1);
